if (!window.CHAPTER_DATA) window.CHAPTER_DATA = {};
window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c11p-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Physics &bull; Chapter 1</div>\n      <h2>Units and Measurements</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 22 Verbatim Questions with Official Marking Schemes</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:white; border:1px solid #e2e8f0; border-radius:12px; padding:20px; margin-bottom:28px; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#0f172a; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <span style=\"display:inline-block; width:10px; height:10px; background:#7c3aed; border-radius:50%;\"></span>\n      Precision Instrumentation &amp; Dimensional Analysis Architecture\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; display:block; font-family:system-ui, -apple-system, sans-serif;\">\n      <!-- Panel 1: Vernier Caliper Scale Model -->\n      <rect x=\"15\" y=\"15\" width=\"410\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"25\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#0f172a\">Vernier Calipers Reading Model:</text>\n\n      <!-- Main Scale (Beam) -->\n      <rect x=\"35\" y=\"55\" width=\"370\" height=\"42\" fill=\"#e2e8f0\" stroke=\"#94a3b8\" rx=\"4\"/>\n      <!-- Main scale graduations -->\n      <g stroke=\"#334155\" stroke-width=\"1.2\">\n        <line x1=\"50\" y1=\"55\" x2=\"50\" y2=\"78\"/><text x=\"47\" y=\"90\" font-size=\"9\" fill=\"#1e293b\">0</text>\n        <line x1=\"75\" y1=\"55\" x2=\"75\" y2=\"70\"/>\n        <line x1=\"100\" y1=\"55\" x2=\"100\" y2=\"70\"/>\n        <line x1=\"125\" y1=\"55\" x2=\"125\" y2=\"70\"/>\n        <line x1=\"150\" y1=\"55\" x2=\"150\" y2=\"78\"/><text x=\"146\" y=\"90\" font-size=\"9\" fill=\"#1e293b\">1 cm</text>\n        <line x1=\"175\" y1=\"55\" x2=\"175\" y2=\"70\"/>\n        <line x1=\"200\" y1=\"55\" x2=\"200\" y2=\"70\"/>\n        <line x1=\"225\" y1=\"55\" x2=\"225\" y2=\"70\"/>\n        <line x1=\"250\" y1=\"55\" x2=\"250\" y2=\"78\"/><text x=\"246\" y=\"90\" font-size=\"9\" fill=\"#1e293b\">2 cm</text>\n        <line x1=\"275\" y1=\"55\" x2=\"275\" y2=\"70\"/>\n        <line x1=\"300\" y1=\"55\" x2=\"300\" y2=\"70\"/>\n        <line x1=\"325\" y1=\"55\" x2=\"325\" y2=\"70\"/>\n        <line x1=\"350\" y1=\"55\" x2=\"350\" y2=\"78\"/><text x=\"346\" y=\"90\" font-size=\"9\" fill=\"#1e293b\">3 cm</text>\n        <line x1=\"375\" y1=\"55\" x2=\"375\" y2=\"70\"/>\n      </g>\n\n      <!-- Vernier Sliding Scale -->\n      <rect x=\"135\" y=\"97\" width=\"180\" height=\"35\" fill=\"#fdf4ff\" stroke=\"#7c3aed\" stroke-width=\"1.8\" rx=\"4\"/>\n      <!-- Vernier Scale Graduations (10 div = 9 MSD) -->\n      <g stroke=\"#7c3aed\" stroke-width=\"1.2\">\n        <line x1=\"140\" y1=\"97\" x2=\"140\" y2=\"114\"/><text x=\"138\" y=\"125\" font-size=\"8\" fill=\"#7c3aed\">0</text>\n        <line x1=\"162\" y1=\"97\" x2=\"162\" y2=\"108\"/>\n        <line x1=\"184\" y1=\"97\" x2=\"184\" y2=\"108\"/>\n        <line x1=\"206\" y1=\"97\" x2=\"206\" y2=\"108\"/>\n        <line x1=\"225\" y1=\"97\" x2=\"225\" y2=\"120\" stroke=\"#dc2626\" stroke-width=\"2\"/> <!-- Coincidence mark at 4th -->\n        <circle cx=\"225\" cy=\"97\" r=\"3\" fill=\"#dc2626\"/>\n        <line x1=\"247\" y1=\"97\" x2=\"247\" y2=\"108\"/>\n        <line x1=\"269\" y1=\"97\" x2=\"269\" y2=\"108\"/>\n        <line x1=\"291\" y1=\"97\" x2=\"291\" y2=\"114\"/><text x=\"288\" y=\"125\" font-size=\"8\" fill=\"#7c3aed\">10</text>\n      </g>\n\n      <!-- Measurement callout -->\n      <text x=\"235\" y=\"120\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#dc2626\">&larr; Coincidence Mark</text>\n      <text x=\"35\" y=\"160\" font-size=\"10.5\" fill=\"#334155\">&bull; Main Scale Reading (MSR) = <tspan font-weight=\"bold\">1.4 cm</tspan></text>\n      <text x=\"35\" y=\"180\" font-size=\"10.5\" fill=\"#334155\">&bull; Vernier Coincidence (n) = <tspan font-weight=\"bold\">4</tspan>, Least Count (LC) = <tspan font-weight=\"bold\">0.01 cm</tspan></text>\n      <text x=\"35\" y=\"202\" font-size=\"11\" font-weight=\"bold\" fill=\"#047857\">Reading = MSR + (n &times; LC) = 1.4 + 0.04 = 1.44 cm</text>\n\n      <!-- Panel 2: SI Base Quantities & Dimensions -->\n      <rect x=\"440\" y=\"15\" width=\"325\" height=\"220\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"455\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">7 Base SI Dimensions &amp; Analysis:</text>\n\n      <g font-size=\"10\" fill=\"#334155\">\n        <text x=\"455\" y=\"62\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[M]</tspan> Mass &rarr; Kilogram (kg)</text>\n        <text x=\"455\" y=\"80\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[L]</tspan> Length &rarr; Metre (m)</text>\n        <text x=\"455\" y=\"98\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[T]</tspan> Time &rarr; Second (s)</text>\n        <text x=\"455\" y=\"116\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[I] / [A]</tspan> Electric Current &rarr; Ampere (A)</text>\n        <text x=\"455\" y=\"134\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[&Theta;] / [K]</tspan> Thermodynamic Temp &rarr; Kelvin (K)</text>\n        <text x=\"455\" y=\"152\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[N] / [mol]</tspan> Amount of Substance &rarr; Mole (mol)</text>\n        <text x=\"455\" y=\"170\"><tspan font-weight=\"bold\" fill=\"#7c3aed\">[J] / [cd]</tspan> Luminous Intensity &rarr; Candela (cd)</text>\n      </g>\n\n      <rect x=\"455\" y=\"184\" width=\"295\" height=\"42\" rx=\"6\" fill=\"#f5f3ff\" stroke=\"#ddd6fe\"/>\n      <text x=\"465\" y=\"201\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#5b21b6\">Principle of Homogeneity:</text>\n      <text x=\"465\" y=\"217\" font-size=\"9\" fill=\"#475569\">Terms added or equated must have identical dimensions.</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1.1 to 1.22: Fundamental SI Conversions, Instrumentation Precision, Error Propagation &amp; Dimensional Homogeneity</div>\n\n  <!-- c11p-ch1-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q1')\">\n      <div class=\"q-num\">Question 1.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fill in the blanks:<br>(a) The volume of a cube of side $1\\text{ cm}$ is equal to ______ $\\text{m}^3$.<br>(b) The surface area of a solid cylinder of radius $2.0\\text{ cm}$ and height $10.0\\text{ cm}$ is equal to ______ $(\\text{mm})^2$.<br>(c) A vehicle moving with a speed of $18\\text{ km h}^{-1}$ covers ______ $\\text{m}$ in $1\\text{ s}$.<br>(d) The relative density of lead is $11.3$. Its density is ______ $\\text{g cm}^{-3}$ or ______ $\\text{kg m}^{-3}$.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Volume of cube:</b><br>\n      Side $a = 1\\text{ cm} = 10^{-2}\\text{ m}$.<br>\n      $$\\text{Volume } V = a^3 = (10^{-2}\\text{ m})^3 = \\mathbf{10^{-6}\\text{ m}^3}$$<br>\n    • <b>(b) Total surface area of a solid cylinder:</b><br>\n      Radius $r = 2.0\\text{ cm} = 20\\text{ mm}$, height $h = 10.0\\text{ cm} = 100\\text{ mm}$.<br>\n      $$\\text{Surface Area } A = 2\\pi r(r + h) = 2 \\times 3.1416 \\times 20 \\times (20 + 100) = 40\\pi \\times 120 = 4800\\pi\\text{ mm}^2$$<br>\n      $$A = 4800 \\times 3.1416 = 15079.6\\text{ mm}^2 = \\mathbf{1.5 \\times 10^4\\text{ (mm)}^2}$$<br>\n    • <b>(c) Speed conversion:</b><br>\n      $$18\\text{ km h}^{-1} = 18 \\times \\frac{5}{18}\\text{ m s}^{-1} = 5\\text{ m s}^{-1}$$<br>\n      Distance covered in $1\\text{ s} = \\text{speed} \\times \\text{time} = 5\\text{ m s}^{-1} \\times 1\\text{ s} = \\mathbf{5\\text{ m}}$<br>\n    • <b>(d) Density of lead:</b><br>\n      $$\\text{Density} = \\text{Relative Density} \\times \\text{Density of water}$$<br>\n      In CGS: $11.3 \\times 1\\text{ g cm}^{-3} = \\mathbf{11.3\\text{ g cm}^{-3}}$<br>\n      In SI: $11.3 \\times 10^3\\text{ kg m}^{-3} = \\mathbf{1.13 \\times 10^4\\text{ kg m}^{-3}}$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Volume conversion to $10^{-6}\\text{ m}^3$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Surface area formula and conversion to $1.5 \\times 10^4\\text{ mm}^2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Speed conversion factor $5/18$ giving $5\\text{ m}$ in $1\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Density calculations in CGS and SI units</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q2')\">\n      <div class=\"q-num\">Question 1.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fill in the blanks by suitable conversion of units:<br>(a) $1\\text{ kg m}^2\\text{ s}^{-2} = \\text{______ g cm}^2\\text{ s}^{-2}$<br>(b) $1\\text{ m} = \\text{______ ly}$ (light year)<br>(c) $3.0\\text{ m s}^{-2} = \\text{______ km h}^{-2}$<br>(d) $G = 6.67 \\times 10^{-11}\\text{ N m}^2\\text{ kg}^{-2} = \\text{______ (cm)}^3\\text{ s}^{-2}\\text{ g}^{-1}$\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) $1\\text{ kg m}^2\\text{ s}^{-2}$ (Joule to erg):</b><br>\n      $$1\\text{ kg} = 10^3\\text{ g}, \\quad 1\\text{ m} = 10^2\\text{ cm} \\implies 1\\text{ m}^2 = 10^4\\text{ cm}^2$$<br>\n      $$1\\text{ kg m}^2\\text{ s}^{-2} = 10^3\\text{ g} \\times 10^4\\text{ cm}^2 \\times 1\\text{ s}^{-2} = \\mathbf{10^7\\text{ g cm}^2\\text{ s}^{-2}}$$<br>\n    • <b>(b) $1\\text{ m}$ to light year (ly):</b><br>\n      $$1\\text{ ly} = \\text{speed of light} \\times 1\\text{ year} = (3 \\times 10^8\\text{ m s}^{-1}) \\times (365.25 \\times 24 \\times 3600\\text{ s}) = 9.46 \\times 10^{15}\\text{ m}$$<br>\n      $$1\\text{ m} = \\frac{1}{9.46 \\times 10^{15}}\\text{ ly} = \\mathbf{1.057 \\times 10^{-16}\\text{ ly}}$$<br>\n    • <b>(c) $3.0\\text{ m s}^{-2}$ to $\\text{km h}^{-2}$:</b><br>\n      $$1\\text{ m} = 10^{-3}\\text{ km}, \\quad 1\\text{ s} = \\frac{1}{3600}\\text{ h} \\implies 1\\text{ s}^{-2} = (3600)^2\\text{ h}^{-2}$$<br>\n      $$3.0\\text{ m s}^{-2} = 3.0 \\times 10^{-3} \\times (3600)^2 = 3.0 \\times 10^{-3} \\times 1.296 \\times 10^7 = \\mathbf{3.888 \\times 10^4\\text{ km h}^{-2}}$$<br>\n    • <b>(d) Universal Gravitational Constant $G$:</b><br>\n      $$1\\text{ N} = 1\\text{ kg m s}^{-2} \\implies 1\\text{ N m}^2\\text{ kg}^{-2} = 1\\text{ m}^3\\text{ kg}^{-1}\\text{ s}^{-2}$$<br>\n      $$G = 6.67 \\times 10^{-11}\\text{ m}^3\\text{ kg}^{-1}\\text{ s}^{-2} = 6.67 \\times 10^{-11} \\times (10^2\\text{ cm})^3 \\times (10^3\\text{ g})^{-1} \\times 1\\text{ s}^{-2}$$<br>\n      $$= 6.67 \\times 10^{-11} \\times 10^6 \\times 10^{-3}\\text{ cm}^3\\text{ g}^{-1}\\text{ s}^{-2} = \\mathbf{6.67 \\times 10^{-8}\\text{ cm}^3\\text{ s}^{-2}\\text{ g}^{-1}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Conversion factor $10^7$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) $1\\text{ ly} = 9.46 \\times 10^{15}\\text{ m} \\implies 1.057 \\times 10^{-16}\\text{ ly}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Acceleration unit conversion to $3.89 \\times 10^4\\text{ km h}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Dimensional conversion of $G$ to $6.67 \\times 10^{-8}\\text{ cm}^3\\text{ s}^{-2}\\text{ g}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q3')\">\n      <div class=\"q-num\">Question 1.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A calorie is a unit of heat or energy and it equals about $4.2\\text{ J}$ where $1\\text{ J} = 1\\text{ kg m}^2\\text{ s}^{-2}$. Suppose we employ a system of units in which the unit of mass equals $\\alpha\\text{ kg}$, the unit of length equals $\\beta\\text{ m}$, the unit of time is $\\gamma\\text{ s}$. Show that a calorie has a magnitude $4.2\\,\\alpha^{-1}\\beta^{-2}\\gamma^2$ in terms of the new units.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Dimensional formula of energy (heat/calorie):<br>\n      $$[\\text{Energy}] = [M^1 L^2 T^{-2}]$$<br>\n      Comparing with $[M^a L^b T^c]$, we have $a = 1, b = 2, c = -2$.<br><br>\n    • <b>System 1 (SI Units):</b><br>\n      $n_1 = 4.2$, $M_1 = 1\\text{ kg}$, $L_1 = 1\\text{ m}$, $T_1 = 1\\text{ s}$.<br><br>\n    • <b>System 2 (New Units):</b><br>\n      $n_2 = ?$, $M_2 = \\alpha\\text{ kg}$, $L_2 = \\beta\\text{ m}$, $T_2 = \\gamma\\text{ s}$.<br><br>\n    • <b>Using conversion formula $n_2 = n_1 \\left(\\frac{M_1}{M_2}\\right)^a \\left(\\frac{L_1}{L_2}\\right)^b \\left(\\frac{T_1}{T_2}\\right)^c$:</b><br>\n      $$n_2 = 4.2 \\left(\\frac{1\\text{ kg}}{\\alpha\\text{ kg}}\\right)^1 \\left(\\frac{1\\text{ m}}{\\beta\\text{ m}}\\right)^2 \\left(\\frac{1\\text{ s}}{\\gamma\\text{ s}}\\right)^{-2}$$<br>\n      $$n_2 = 4.2 (\\alpha^{-1}) (\\beta^{-2}) (\\gamma^2) = \\mathbf{4.2\\,\\alpha^{-1}\\beta^{-2}\\gamma^2}$$<br>\n    • Hence, $1\\text{ calorie} = 4.2\\,\\alpha^{-1}\\beta^{-2}\\gamma^2\\text{ (new units)}$. (Hence Proved).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Dimensional formula $[M L^2 T^{-2}]$ with powers $a=1, b=2, c=-2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting conversion formula with new units $\\alpha\\text{ kg}, \\beta\\text{ m}, \\gamma\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simplifying to $4.2\\,\\alpha^{-1}\\beta^{-2}\\gamma^2$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q4')\">\n      <div class=\"q-num\">Question 1.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain this statement clearly: \"To call a dimensional quantity 'large' or 'small' is meaningless without specifying a standard for comparison\". In view of this, re-frame the following statements wherever necessary:<br>(a) atoms are very small things<br>(b) a jet plane moves with great speed<br>(c) the mass of Jupiter is very large<br>(d) the air inside this room contains a large number of molecules<br>(e) a proton is much more massive than an electron<br>(f) the speed of sound is much smaller than the speed of light.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>Explanation:</b> A physical quantity possessing dimensions cannot be judged as absolute 'large' or 'small'. A magnitude can only be large or small relative to some chosen reference standard of the same dimensions (e.g., $1\\text{ cm}$ is huge compared to an atom $\\sim 10^{-10}\\text{ m}$, but minuscule compared to the radius of Earth $\\sim 10^6\\text{ m}$).<br><br>\n    • <b>Reframed Statements:</b><br>\n      (a) <b>Atoms are very small compared to the tip of a sharp pin or the wavelength of visible light.</b><br>\n      (b) <b>A jet plane moves with a speed much greater than that of a superfast express train.</b><br>\n      (c) <b>The mass of Jupiter is very large compared to the mass of Earth (about 318 times larger).</b><br>\n      (d) <b>The air inside this room contains a large number of molecules compared to the number of molecules in one mole of gas ($N_A = 6.022 \\times 10^{23}$).</b><br>\n      (e) <i>Already well-framed</i>: A proton is much more massive than an electron (approx. $1836$ times more massive; comparison standard is explicitly specified).<br>\n      (f) <i>Already well-framed</i>: The speed of sound ($340\\text{ m s}^{-1}$) is much smaller than the speed of light ($3 \\times 10^8\\text{ m s}^{-1}$) in air.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear scientific rationale of relativity of dimensional scales</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reframing (a) and (b) with proper reference standards</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reframing (c) and (d) with comparative benchmarks</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Validating (e) and (f) as already having explicit reference standards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q5')\">\n      <div class=\"q-num\">Question 1.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A new unit of length is chosen such that the speed of light in vacuum is unity. What is the distance between the Sun and the Earth in terms of the new unit if light takes $8\\text{ min and } 20\\text{ s}$ to cover this distance?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given speed of light in the new system of units: $c = 1\\text{ (new unit of length) s}^{-1}$.<br>\n    • Time taken by light from Sun to Earth:<br>\n      $$t = 8\\text{ min } 20\\text{ s} = (8 \\times 60) + 20 = 480 + 20 = 500\\text{ s}$$<br>\n    • Distance $d$ between Sun and Earth:<br>\n      $$d = \\text{speed} \\times \\text{time} = c \\times t$$<br>\n      $$d = 1\\text{ (new unit) s}^{-1} \\times 500\\text{ s} = \\mathbf{500\\text{ new units of length}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Converting time into seconds: $t = 500\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying $d = c \\times t$ to get $500\\text{ new units}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q6')\">\n      <div class=\"q-num\">Question 1.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following is the most precise device for measuring length:<br>(a) a vernier callipers with 20 divisions on the sliding scale<br>(b) a screw gauge of pitch 1 mm and 100 divisions on the circular scale<br>(c) an optical instrument that can measure length to within a wavelength of light?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • The precision of a measuring instrument is determined by its <b>Least Count (LC)</b>: the smaller the least count, the higher the precision.<br><br>\n    • <b>(a) Vernier Callipers:</b><br>\n      Assuming $1\\text{ MSD} = 1\\text{ mm}$, $20\\text{ VSD} = 19\\text{ MSD}$:<br>\n      $$LC = 1\\text{ MSD} - 1\\text{ VSD} = \\frac{1}{20}\\text{ mm} = 0.05\\text{ mm} = 5 \\times 10^{-5}\\text{ m}$$<br>\n    • <b>(b) Screw Gauge:</b><br>\n      $$LC = \\frac{\\text{Pitch}}{\\text{Number of circular divisions}} = \\frac{1\\text{ mm}}{100} = 0.01\\text{ mm} = 10^{-5}\\text{ m}$$<br>\n    • <b>(c) Optical Instrument:</b><br>\n      Can measure within a wavelength of visible light $\\lambda$ (average $\\lambda \\approx 6000\\text{ AA} = 6 \\times 10^{-7}\\text{ m}$):<br>\n      $$LC \\approx 10^{-7}\\text{ m}$$<br>\n    • Comparing least counts: $10^{-7}\\text{ m} < 10^{-5}\\text{ m} < 5 \\times 10^{-5}\\text{ m}$.<br>\n    • Therefore, <b>(c) the optical instrument</b> is the most precise device.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Defining least count as measure of precision</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating LC of Vernier ($0.05\\text{ mm}$) and Screw gauge ($0.01\\text{ mm}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Estimating LC of optical device ($\\sim 10^{-7}\\text{ m}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding optical instrument is most precise</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q7')\">\n      <div class=\"q-num\">Question 1.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A student measures the thickness of a human hair by looking at it through a microscope of magnification 100. He makes 20 observations and finds that the average width of the hair in the field of view of the microscope is $3.5\\text{ mm}$. What is the estimate on the thickness of hair?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given magnification of microscope $m = 100$.<br>\n    • Observed average apparent width in the field of view $= 3.5\\text{ mm}$.<br>\n    • The linear magnification formula is:<br>\n      $$m = \\frac{\\text{Apparent size}}{\\text{Real size}}$$<br>\n    • Therefore, the real thickness of the human hair is:<br>\n      $$\\text{Real thickness} = \\frac{\\text{Apparent width}}{m} = \\frac{3.5\\text{ mm}}{100} = \\mathbf{0.035\\text{ mm}} = \\mathbf{3.5 \\times 10^{-5}\\text{ m}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Magnification relation: $\\text{Real} = \\text{Apparent} / m$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating estimated thickness $= 0.035\\text{ mm}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q8')\">\n      <div class=\"q-num\">Question 1.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Answer the following:<br>(a) You are given a thread and a metre scale. How will you estimate the diameter of the thread?<br>(b) A screw gauge has a pitch of $1.0\\text{ mm}$ and $200$ divisions on the circular scale. Do you think it is possible to increase the accuracy of the screw gauge arbitrarily by increasing the number of divisions on the circular scale?<br>(c) The mean diameter of a thin brass rod is to be measured by vernier callipers. Why is a set of 100 measurements of the diameter expected to yield a more reliable estimate than a set of 5 measurements only?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Estimating diameter of thread:</b><br>\n      Wrap the thread closely and uniformly around a cylindrical pencil or metre rod such that consecutive turns touch each other without overlapping. Count the number of turns $n$ (say, $n = 50$). Measure the total length $L$ of the wound coil using the metre scale. The diameter $d$ of the thread is estimated by:<br>\n      $$d = \\frac{L}{n}$$<br>\n    • <b>(b) Increasing circular scale divisions arbitrarily:</b><br>\n      <b>No.</b> While increasing divisions theoretically decreases the least count ($LC = \\text{pitch}/N$), in practice, human eyesight cannot resolve extremely narrow division marks without optical microscopes. Additionally, mechanical constraints like backlash error, pitch imperfections, and thermal expansion set practical physical limits.<br><br>\n    • <b>(c) 100 measurements vs 5 measurements:</b><br>\n      Random errors occur randomly in magnitude and direction. According to the statistical theory of errors, the random error is inversely proportional to the square root of the number of observations ($\\text{Random Error} \\propto \\frac{1}{\\sqrt{n}}$). For $n = 100$, random error is reduced by a factor of $\\frac{\\sqrt{100}}{\\sqrt{5}} = \\sqrt{20} \\approx 4.5$ compared to $n = 5$, yielding a far more reliable mean estimate.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Describing winding method and formula $d = L/n$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Explaining resolution and mechanical limitations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Statistical justification: random error $\\propto 1/\\sqrt{n}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q9')\">\n      <div class=\"q-num\">Question 1.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The photograph of a house occupies an area of $1.75\\text{ cm}^2$ on a $35\\text{ mm}$ slide. The slide is projected on to a screen, and the area of the house on the screen is $1.55\\text{ m}^2$. What is the linear magnification of the projector-screen arrangement?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Area of the house on slide $A_1 = 1.75\\text{ cm}^2 = 1.75 \\times 10^{-4}\\text{ m}^2$.<br>\n    • Area of the projected image on screen $A_2 = 1.55\\text{ m}^2$.<br>\n    • The <b>areal magnification</b> $m_A$ is:<br>\n      $$m_A = \\frac{A_2}{A_1} = \\frac{1.55\\text{ m}^2}{1.75 \\times 10^{-4}\\text{ m}^2} = \\frac{1.55}{1.75} \\times 10^4 = 0.8857 \\times 10^4 = 8857.14$$<br>\n    • The <b>linear magnification</b> $m_L$ is the square root of areal magnification:<br>\n      $$m_L = \\sqrt{m_A} = \\sqrt{8857.14} \\approx \\mathbf{94.11} \\approx \\mathbf{94.1}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Converting slide area to $\\text{m}^2$ and calculating $m_A = 8857.14$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying $m_L = \\sqrt{m_A} \\approx 94.1$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q10')\">\n      <div class=\"q-num\">Question 1.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State the number of significant figures in the following:<br>(a) $0.007\\text{ m}^2$<br>(b) $2.64 \\times 10^{24}\\text{ kg}$<br>(c) $0.2370\\text{ g cm}^{-3}$<br>(d) $6.320\\text{ J}$<br>(e) $6.032\\text{ N m}^{-2}$<br>(f) $0.0006032\\text{ m}^2$\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Rules for significant figures:<br>\n      - Leading zeros before the first non-zero digit are non-significant.<br>\n      - Trailing zeros after decimal point are significant.<br>\n      - Zeros between non-zero digits are significant.<br>\n      - Powers of 10 do not affect significant figures.<br><br>\n    • (a) $0.007\\text{ m}^2 \\implies$ <b>1 significant figure</b> ($7$).<br>\n    • (b) $2.64 \\times 10^{24}\\text{ kg} \\implies$ <b>3 significant figures</b> ($2, 6, 4$).<br>\n    • (c) $0.2370\\text{ g cm}^{-3} \\implies$ <b>4 significant figures</b> ($2, 3, 7, 0$).<br>\n    • (d) $6.320\\text{ J} \\implies$ <b>4 significant figures</b> ($6, 3, 2, 0$).<br>\n    • (e) $6.032\\text{ N m}^{-2} \\implies$ <b>4 significant figures</b> ($6, 0, 3, 2$).<br>\n    • (f) $0.0006032\\text{ m}^2 \\implies$ <b>4 significant figures</b> ($6, 0, 3, 2$).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Parts (a) and (b): 1 and 3 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Parts (c) and (d): 4 and 4 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Parts (e) and (f): 4 and 4 significant figures</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q11')\">\n      <div class=\"q-num\">Question 1.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The length, breadth and thickness of a rectangular sheet of metal are $4.234\\text{ m}, 1.005\\text{ m}$, and $2.01\\text{ cm}$ respectively. Give the area and volume of the sheet to correct significant figures.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given dimensions:<br>\n      - Length $l = 4.234\\text{ m}$ (4 significant figures)<br>\n      - Breadth $b = 1.005\\text{ m}$ (4 significant figures)<br>\n      - Thickness $t = 2.01\\text{ cm} = 0.0201\\text{ m}$ (3 significant figures)<br>\n      Least number of significant figures is <b>3</b> (in thickness $t$).<br><br>\n    • <b>1. Total Surface Area:</b><br>\n      $$A = 2(l \\cdot b + b \\cdot t + t \\cdot l)$$<br>\n      $$l \\cdot b = 4.234 \\times 1.005 = 4.25517\\text{ m}^2$$<br>\n      $$b \\cdot t = 1.005 \\times 0.0201 = 0.0202005\\text{ m}^2$$<br>\n      $$t \\cdot l = 0.0201 \\times 4.234 = 0.0851034\\text{ m}^2$$<br>\n      $$\\text{Sum} = 4.25517 + 0.02020 + 0.08510 = 4.36047\\text{ m}^2$$<br>\n      $$A = 2 \\times 4.36047 = 8.72094\\text{ m}^2$$<br>\n      Rounding to 3 significant figures: $\\mathbf{A = 8.72\\text{ m}^2}$<br><br>\n    • <b>2. Volume:</b><br>\n      $$V = l \\times b \\times t = 4.234 \\times 1.005 \\times 0.0201 = 0.0855289\\text{ m}^3$$<br>\n      Rounding off to 3 significant figures:<br>\n      $$\\mathbf{V = 0.0855\\text{ m}^3} \\quad (\\text{or } 8.55 \\times 10^{-2}\\text{ m}^3)$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying least significant figure rule (3 s.f.)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Surface area computation and rounding to $8.72\\text{ m}^2$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Volume calculation and rounding to $0.0855\\text{ m}^3$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q12')\">\n      <div class=\"q-num\">Question 1.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The mass of a box measured by a grocer's balance is $2.300\\text{ kg}$. Two gold pieces of masses $20.15\\text{ g}$ and $20.17\\text{ g}$ are added to the box. What is (a) the total mass of the box, (b) the difference in the masses of the pieces to correct significant figures?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given mass of the box $M = 2.300\\text{ kg}$.<br>\n    • Mass of first gold piece $m_1 = 20.15\\text{ g} = 0.02015\\text{ kg}$.<br>\n    • Mass of second gold piece $m_2 = 20.17\\text{ g} = 0.02017\\text{ kg}$.<br><br>\n    • <b>(a) Total mass of the box:</b><br>\n      $$\\text{Total Mass} = 2.300 + 0.02015 + 0.02017 = 2.34032\\text{ kg}$$<br>\n      In addition, the result must be rounded to the least number of decimal places of the terms.<br>\n      The mass of the box $2.300\\text{ kg}$ has $3$ decimal places.<br>\n      Rounding to $3$ decimal places:<br>\n      $$\\mathbf{\\text{Total Mass} = 2.340\\text{ kg}}$$<br>\n    • <b>(b) Difference in masses of the two gold pieces:</b><br>\n      $$\\Delta m = m_2 - m_1 = 20.17\\text{ g} - 20.15\\text{ g} = \\mathbf{0.02\\text{ g}}$$<br>\n      (Both quantities have $2$ decimal places; the difference has $2$ decimal places).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Summing masses and rounding to 3 decimal places: $2.340\\text{ kg}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Finding difference $20.17 - 20.15 = 0.02\\text{ g}$ with 2 decimal places</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q13')\">\n      <div class=\"q-num\">Question 1.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A physical quantity $P$ is related to four observables $a, b, c$ and $d$ as follows: $P = \\frac{a^3 b^2}{\\sqrt{c}\\,d}$. The percentage errors of measurement in $a, b, c$ and $d$ are $1\\%, 3\\%, 4\\%$ and $2\\%$, respectively. What is the percentage error in the quantity $P$? If the value of $P$ calculated using the above relation turns out to be $3.763$, to what value should you round off the result?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given formula: $P = \\frac{a^3 b^2}{c^{1/2} d} = a^3 b^2 c^{-1/2} d^{-1}$.<br>\n    • The relative error in $P$ is given by logarithmic differentiation / error propagation rule:<br>\n      $$\\frac{\\Delta P}{P} = 3\\left(\\frac{\\Delta a}{a}\\right) + 2\\left(\\frac{\\Delta b}{b}\\right) + \\frac{1}{2}\\left(\\frac{\\Delta c}{c}\\right) + \\left(\\frac{\\Delta d}{d}\\right)$$<br>\n    • Percentage error in $P$:<br>\n      $$\\frac{\\Delta P}{P} \\times 100\\% = 3(1\\%) + 2(3\\%) + \\frac{1}{2}(4\\%) + 1(2\\%)$$<br>\n      $$= 3\\% + 6\\% + 2\\% + 2\\% = \\mathbf{13\\%}$$<br>\n    • <b>Rounding off value of $P$:</b><br>\n      The calculated value is $P = 3.763$.<br>\n      Since the percentage error is $13\\%$ (which has two significant figures), the absolute uncertainty is roughly:<br>\n      $$\\Delta P = 0.13 \\times 3.763 \\approx 0.49$$<br>\n      The uncertainty is in the first decimal place. Hence, the value of $P$ can only be quoted with precision to the tenths place.<br>\n      Rounding off $3.763$ gives $\\mathbf{3.8}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Applying fractional error combination formula</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating percentage error $= 13\\%$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rounding off calculated value $3.763$ to $3.8$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q14')\">\n      <div class=\"q-num\">Question 1.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A book with many printing errors contains four different formulas for the displacement $y$ of a particle undergoing a certain periodic motion:<br>(a) $y = a \\sin \\frac{2\\pi t}{T}$<br>(b) $y = a \\sin vt$<br>(c) $y = \\frac{a}{T} \\sin \\frac{t}{a}$<br>(d) $y = (a\\sqrt{2}) \\left(\\sin \\frac{2\\pi t}{T} + \\cos \\frac{2\\pi t}{T}\\right)$<br>($a =$ maximum displacement of the particle, $v =$ speed of the particle, $T =$ time-period of motion). Rule out the wrong formulas on dimensional grounds.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>Principle of Homogeneity & Dimensional Requirements:</b><br>\n      1. The argument of any trigonometric function (sine or cosine) must be <b>dimensionless</b> ($[M^0 L^0 T^0]$).<br>\n      2. Both sides of the equation must have the dimensions of displacement ($[L]$).<br><br>\n    • <b>(a) $y = a \\sin \\frac{2\\pi t}{T}$:</b><br>\n      - Angle: $\\left[\\frac{2\\pi t}{T}\\right] = \\frac{[T]}{[T]} = [M^0 L^0 T^0]$ (Dimensionless &check;)<br>\n      - LHS: $[y] = [L]$; RHS: $[a] = [L]$ (&check;). <b>Formula is dimensionally correct.</b><br><br>\n    • <b>(b) $y = a \\sin vt$:</b><br>\n      - Angle: $[vt] = [L T^{-1}][T] = [L] \\neq [M^0 L^0 T^0]$ (Not dimensionless &cross;).<br>\n      - <b>Formula is dimensionally WRONG.</b><br><br>\n    • <b>(c) $y = \\frac{a}{T} \\sin \\frac{t}{a}$:</b><br>\n      - Angle: $\\left[\\frac{t}{a}\\right] = \\frac{[T]}{[L]} = [L^{-1} T] \\neq [M^0 L^0 T^0]$ (&cross;).<br>\n      - Amplitude: $\\left[\\frac{a}{T}\\right] = [L T^{-1}] \\neq [y]$ (&cross;).<br>\n      - <b>Formula is dimensionally WRONG.</b><br><br>\n    • <b>(d) $y = (a\\sqrt{2}) \\left(\\sin \\frac{2\\pi t}{T} + \\cos \\frac{2\\pi t}{T}\\right)$:</b><br>\n      - Angles: $\\left[\\frac{2\\pi t}{T}\\right] = [M^0 L^0 T^0]$ (Dimensionless &check;)<br>\n      - Dimensions of amplitude: $[a\\sqrt{2}] = [L] = [y]$ (&check;). <b>Formula is dimensionally correct.</b><br><br>\n    • <b>Conclusion:</b> Formulas <b>(b)</b> and <b>(c)</b> are ruled out as wrong on dimensional grounds.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating dimensional rule for trigonometric argument $[M^0 L^0 T^0]$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Checking (a) and (d) as dimensionally correct</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ruling out (b) because $[vt] = [L]$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ruling out (c) because $[t/a] = [L^{-1}T]$ and $[a/T] = [LT^{-1}]$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q15')\">\n      <div class=\"q-num\">Question 1.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A famous relation in physics relates 'moving mass' $m$ to the 'rest mass' $m_0$ of a particle in terms of its speed $v$ and the speed of light $c$. A boy recalls the relation almost correctly but forgets where to put the constant $c$. He writes: $m = \\frac{m_0}{(1 - v^2)^{1/2}}$. Guess where to put the missing $c$.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • By the principle of homogeneity of dimensions:<br>\n      - In the expression $(1 - v^2)^{1/2}$, the quantity subtracted from the pure number $1$ must be <b>dimensionless</b>.<br>\n      - However, speed squared has dimensions $[v^2] = [L^2 T^{-2}]$.<br>\n      - To make $v^2$ dimensionless, it must be divided by another quantity with dimensions $[L^2 T^{-2}]$.<br>\n      - The speed of light $c$ has dimensions of speed $[L T^{-1}]$, so $c^2$ has dimensions $[L^2 T^{-2}]$.<br>\n      - Thus, the dimensionless term is $\\frac{v^2}{c^2}$.<br><br>\n    • Checking overall equation dimensions with this modification:<br>\n      $$m = \\frac{m_0}{\\sqrt{1 - \\frac{v^2}{c^2}}}$$<br>\n      LHS has dimensions $[M]$, and RHS has dimensions $[M]/[1] = [M]$.<br><br>\n    • Hence, the correct formula is: $\\mathbf{m = \\frac{m_0}{\\left(1 - \\frac{v^2}{c^2}\\right)^{1/2}}}$, i.e., $c^2$ must be placed in the denominator under $v^2$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Applying homogeneity principle: $1 - v^2/c^2$ must be dimensionless</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating correct formula $m = m_0 / \\sqrt{1 - v^2/c^2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q16')\">\n      <div class=\"q-num\">Question 1.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The unit of length convenient on the atomic scale is known as an angstrom and is denoted by $\\text{\\AA}$: $1\\text{ \\AA} = 10^{-10}\\text{ m}$. The size of a hydrogen atom is about $0.5\\text{ \\AA}$. What is the total atomic volume in $\\text{m}^3$ of a mole of hydrogen atoms?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Radius of hydrogen atom $r = 0.5\\text{ \\AA} = 0.5 \\times 10^{-10}\\text{ m}$.<br>\n    • Volume of a single spherical hydrogen atom:<br>\n      $$V_1 = \\frac{4}{3}\\pi r^3 = \\frac{4}{3} \\times 3.1416 \\times (0.5 \\times 10^{-10}\\text{ m})^3$$<br>\n      $$V_1 = \\frac{4}{3} \\times 3.1416 \\times (0.125 \\times 10^{-30}) = 0.5236 \\times 10^{-30}\\text{ m}^3$$<br>\n    • One mole of hydrogen atoms contains Avogadro's number of atoms: $N_A = 6.023 \\times 10^{23}$.<br>\n    • Total atomic volume of one mole of hydrogen atoms:<br>\n      $$V = N_A \\times V_1 = (6.023 \\times 10^{23}) \\times (0.5236 \\times 10^{-30}\\text{ m}^3)$$<br>\n      $$V = 3.1537 \\times 10^{-7}\\text{ m}^3 \\approx \\mathbf{3.15 \\times 10^{-7}\\text{ m}^3}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Volume formula for single atom $V_1 = \\frac{4}{3}\\pi r^3$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying by Avogadro's number $N_A = 6.023 \\times 10^{23}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluating final volume $V \\approx 3.15 \\times 10^{-7}\\text{ m}^3$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q17')\">\n      <div class=\"q-num\">Question 1.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        One mole of an ideal gas at standard temperature and pressure occupies $22.4\\text{ L}$ (molar volume). What is the ratio of molar volume to the atomic volume of a mole of hydrogen? (Take the size of hydrogen molecule to be about $1\\text{ \\AA}$). Why is this ratio so large?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>Molar volume of ideal gas at STP:</b><br>\n      $$V_m = 22.4\\text{ L} = 22.4 \\times 10^{-3}\\text{ m}^3$$<br>\n    • <b>Atomic volume of a mole of hydrogen:</b><br>\n      Radius $r = 0.5\\text{ \\AA} = 0.5 \\times 10^{-10}\\text{ m}$.<br>\n      From Q1.16, atomic volume of 1 mole is $V_a \\approx 3.15 \\times 10^{-7}\\text{ m}^3$.<br><br>\n    • <b>Ratio of molar volume to atomic volume:</b><br>\n      $$\\frac{V_m}{V_a} = \\frac{22.4 \\times 10^{-3}\\text{ m}^3}{3.15 \\times 10^{-7}\\text{ m}^3} = \\frac{22.4}{3.15} \\times 10^4 \\approx 7.11 \\times 10^4 \\approx \\mathbf{10^4}$$<br>\n    • <b>Physical Reason for Large Ratio:</b><br>\n      In a gas at STP, the molecules are extremely far apart from one another compared to their molecular diameters. Intermolecular empty space occupies more than $99.99\\%$ of the total volume of the container.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating molar volume $V_m = 22.4 \\times 10^{-3}\\text{ m}^3$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating ratio $V_m / V_a \\approx 7.1 \\times 10^4$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining that gas volume is dominated by intermolecular empty space</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q18')\">\n      <div class=\"q-num\">Question 1.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain this common observation clearly: If you look out of the window of a fast moving train, the nearby trees, houses etc. seem to move rapidly in a direction opposite to the train's motion, but the distant objects (hill tops, the Moon, the stars etc.) seem to be stationary.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • This phenomenon is an optical consequence of <b>parallax and angular velocity</b>.<br><br>\n    • <b>Line of Sight & Parallax:</b><br>\n      The apparent motion of any object depends on the rate at which our <b>line of sight</b> to the object rotates as we move.<br><br>\n    • <b>Nearby Objects:</b><br>\n      For nearby trees and houses, the distance $r$ from the observer is very small. When the train moves a distance $\\Delta x$, the angle $\\Delta \\theta \\approx \\frac{\\Delta x}{r}$ subtended at the eye changes very rapidly ($d\\theta/dt = v/r$ is large). Hence, the line of sight swings rapidly backwards, making nearby objects appear to rush backward at great speed.<br><br>\n    • <b>Distant Objects:</b><br>\n      For distant hills, the Moon, or stars, the distance $r$ is extraordinarily large ($r \\to \\infty$). The change in angle $\\Delta \\theta \\approx \\frac{\\Delta x}{r} \\approx 0$ is negligibly small. Because the line of sight remains virtually unchanged in direction, distant objects appear completely stationary.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explaining role of angular velocity of line of sight $d\\theta/dt = v/r$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrasting small $r$ (rapid angle change) with huge $r$ (negligible change)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q19')\">\n      <div class=\"q-num\">Question 1.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The principle of parallax is used in the determination of distances of very distant stars. The baseline $AB$ is the line joining Earth's two locations six months apart in its orbit around the Sun. If the parallax angle of the nearest star is $0.76''$ (seconds of arc), calculate its distance in parsec and light years.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • By definition of a <b>parsec (pc)</b>:<br>\n      $1\\text{ parsec}$ is the distance at which an astronomical unit ($1\\text{ AU}$) subtends a parallax angle of $1''$ (one second of arc).<br>\n      $$d\\text{ (in parsecs)} = \\frac{1}{\\theta\\text{ (in arcseconds)}}$$<br>\n    • Given parallax angle $\\theta = 0.76''$:<br>\n      $$d = \\frac{1}{0.76} \\approx \\mathbf{1.316\\text{ pc}} \\approx \\mathbf{1.32\\text{ pc}}$$<br>\n    • <b>Conversion to Light Years:</b><br>\n      $$1\\text{ pc} = 3.0857 \\times 10^{16}\\text{ m}$$<br>\n      $$1\\text{ ly} = 9.46 \\times 10^{15}\\text{ m}$$<br>\n      $$1\\text{ pc} = \\frac{3.0857 \\times 10^{16}}{9.46 \\times 10^{15}} = 3.26\\text{ ly}$$<br>\n      $$d = 1.316 \\times 3.26\\text{ ly} = \\mathbf{4.29\\text{ ly}}$$<br>\n    • Hence, the star's distance is $\\mathbf{1.32\\text{ pc}}$ or $\\mathbf{4.29\\text{ ly}}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Applying formula $d = 1/\\theta$ to find $d = 1.32\\text{ pc}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting parsecs to light years using $1\\text{ pc} = 3.26\\text{ ly} \\implies 4.29\\text{ ly}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q20')\">\n      <div class=\"q-num\">Question 1.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The Sun's angular diameter is measured to be $1920''$. The distance $D$ of the Sun from the Earth is $1.496 \\times 10^{11}\\text{ m}$. What is the diameter of the Sun?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Given angular diameter $\\alpha = 1920''$.<br>\n    • Converting $\\alpha$ to radians:<br>\n      $$1'' = \\frac{1}{3600}^\\circ = \\frac{1}{3600} \\times \\frac{\\pi}{180}\\text{ rad} = 4.848 \\times 10^{-6}\\text{ rad}$$<br>\n      $$\\alpha = 1920 \\times 4.848 \\times 10^{-6}\\text{ rad} = 9.308 \\times 10^{-3}\\text{ rad}$$<br>\n    • Distance to the Sun $D = 1.496 \\times 10^{11}\\text{ m}$.<br>\n    • The linear diameter $d$ of the Sun is related to angular diameter by:<br>\n      $$d = \\alpha \\times D$$<br>\n      $$d = (9.308 \\times 10^{-3}\\text{ rad}) \\times (1.496 \\times 10^{11}\\text{ m})$$<br>\n      $$d = 1.3925 \\times 10^9\\text{ m} \\approx \\mathbf{1.39 \\times 10^9\\text{ m}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Converting angular diameter $1920''$ to radians ($9.31 \\times 10^{-3}\\text{ rad}$)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying $d = \\alpha D$ to get $d = 1.39 \\times 10^9\\text{ m}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q21')\">\n      <div class=\"q-num\">Question 1.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Precise measurements of physical quantities are a need of science. For example, to ascertain the speed of an aircraft, one must have an accurate method to find its positions at closely separated instants of time. State similar instances in modern science where precision is paramount.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • Instances in modern science and technology where extreme precision measurement is vital:<br><br>\n    • <b>1. Global Positioning System (GPS):</b><br>\n      Satellite navigation depends on ultra-stable cesium and rubidium <b>atomic clocks</b> measuring time to within a few nanoseconds ($10^{-9}\\text{ s}$). An error of just $1\\,\\mu\\text{s}$ would cause a navigational positional drift of $300\\text{ m}$.<br><br>\n    • <b>2. Detection of Gravitational Waves (LIGO):</b><br>\n      Laser interferometry measures mirror displacements as minuscule as $10^{-19}\\text{ m}$ (one-ten-thousandth the diameter of a proton) over a $4\\text{ km}$ baseline to detect spacetime ripples.<br><br>\n    • <b>3. Semiconductor Nanofabrication:</b><br>\n      Extreme Ultraviolet (EUV) photolithography creates microchip transistors with channel dimensions down to $2\\text{ nm}$ to $3\\text{ nm}$, requiring sub-nanometre positioning precision.<br><br>\n    • <b>4. Mass Spectrometry in Medicine:</b><br>\n      Determining isotope masses to parts-per-billion precision enables identification of biomolecules, disease biomarkers, and pharmaceutical drug purity.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning atomic clocks in GPS ($10^{-9}\\text{ s}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning gravitational wave interferometry LIGO ($10^{-19}\\text{ m}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning semiconductor lithography or mass spectrometry</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch1-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch1-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch1-q22')\">\n      <div class=\"q-num\">Question 1.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Just as precise measurements are necessary in science, it is equally important to be able to make rough estimates of quantities using rudimentary ideas and common observations. Think of ways by which you can estimate:<br>(a) the total mass of rain-bearing clouds over India during the Monsoon<br>(b) the mass of an elephant<br>(c) the wind speed during a storm<br>(d) the number of strands of hair on your head<br>(e) the number of air molecules in your classroom.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Mass of rain-bearing clouds:</b><br>\n      India receives average annual monsoon rainfall of $h \\approx 100\\text{ cm} = 1\\text{ m}$.<br>\n      Geographical area of India $A \\approx 3.3 \\times 10^6\\text{ km}^2 = 3.3 \\times 10^{12}\\text{ m}^2$.<br>\n      Total volume of water precipitated: $V = A \\times h = 3.3 \\times 10^{12}\\text{ m}^3$.<br>\n      Mass of water (clouds) $= V \\times \\rho = 3.3 \\times 10^{12}\\text{ m}^3 \\times 10^3\\text{ kg m}^{-3} \\approx \\mathbf{3.3 \\times 10^{15}\\text{ kg}}$ (billions of tonnes).<br><br>\n    • <b>(b) Mass of an elephant:</b><br>\n      Use <b>Archimedes' Principle</b>. Drive the elephant onto a large flat-bottomed boat in calm water. Mark the initial water line and the depressed water line after the elephant boards. The volume of displaced water is $\\Delta V = A_{\\text{boat}} \\times \\Delta h$. The mass of the elephant is $M = \\rho_{\\text{water}} \\times \\Delta V$ (typically $\\sim 3000\\text{ kg}$ to $5000\\text{ kg}$).<br><br>\n    • <b>(c) Wind speed during a storm:</b><br>\n      Observe the deflection angle $\\theta$ of a known pendulum or buoyant balloon. Alternatively, release a floating balloon and measure the time $t$ taken to traverse a known distance $d$ between two landmarks: $v = d/t$.<br><br>\n    • <b>(d) Number of strands of hair on your head:</b><br>\n      Area of scalp $A \\approx 200\\text{ cm}^2$. Measure the hair density in a small area of $1\\text{ cm}^2$ using a magnifying glass (typically $\\sim 500$ hairs/$\\text{cm}^2$). Total hair count $\\approx 200 \\times 500 = \\mathbf{10^5\\text{ hairs}}$ ($1\\text{ lakh}$).<br><br>\n    • <b>(e) Number of air molecules in your classroom:</b><br>\n      Room dimensions $\\approx 6\\text{ m} \\times 5\\text{ m} \\times 4\\text{ m} = 120\\text{ m}^3 = 1.2 \\times 10^5\\text{ L}$.<br>\n      At STP, $22.4\\text{ L}$ of air contains $N_A = 6.023 \\times 10^{23}$ molecules.<br>\n      Number of moles $= \\frac{1.2 \\times 10^5}{22.4} \\approx 5.35 \\times 10^3\\text{ moles}$.<br>\n      Total molecules $N \\approx (5.35 \\times 10^3) \\times (6.023 \\times 10^{23}) \\approx \\mathbf{3.2 \\times 10^{27}\\text{ molecules}}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Estimation of rain mass $\\approx 3.3 \\times 10^{15}\\text{ kg}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Archimedes boat displacement method for elephant</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Wind speed drift/deflection method</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Scalp area $\\times$ density $\\approx 10^5$ hairs</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Room volume $\\times$ molar density $\\approx 3 \\times 10^{27}$ molecules</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer;\">↑ Back to Top</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#7c3aed; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 2 (Motion in a Straight Line) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c11p-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Physics &bull; Chapter 2</div>\n      <h2>Motion in a Straight Line</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 22 Verbatim Questions with Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.2\"><path d=\"M3 3v18h18\"/><path d=\"m19 9-5 5-4-4-3 3\"/></svg>\n      Kinematics Vector Graphs: Position-Time ($x-t$) &amp; Velocity-Time ($v-t$) Dynamics\n    </h3>\n    <svg viewBox=\"0 0 780 230\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: Position-Time Graph Analysis -->\n      <rect x=\"15\" y=\"15\" width=\"365\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"35\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">1. Position-Time ($x-t$) Interpretations:</text>\n      \n      <!-- Coordinate axes -->\n      <line x1=\"50\" y1=\"180\" x2=\"350\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <line x1=\"50\" y1=\"180\" x2=\"50\" y2=\"55\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <text x=\"355\" y=\"184\" font-size=\"10\" fill=\"#64748b\">Time ($t$)</text>\n      <text x=\"35\" y=\"50\" font-size=\"10\" fill=\"#64748b\">Pos ($x$)</text>\n\n      <!-- Curve A: Uniform velocity (straight line) -->\n      <line x1=\"50\" y1=\"180\" x2=\"190\" y2=\"80\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n      <text x=\"135\" y=\"105\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#2563eb\">v = constant (slope)</text>\n\n      <!-- Curve B: Accelerated motion (parabola upward) -->\n      <path d=\"M 50 180 Q 160 175 270 70\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n      <text x=\"210\" y=\"145\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#7c3aed\">a &gt; 0 (convex curve)</text>\n\n      <!-- Curve C: Stationary (horizontal line) -->\n      <line x1=\"180\" y1=\"75\" x2=\"340\" y2=\"75\" stroke=\"#059669\" stroke-width=\"2\" stroke-dasharray=\"4,3\"/>\n      <text x=\"270\" y=\"68\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#059669\">v = 0 (rest)</text>\n\n      <!-- Panel 2: Velocity-Time Graph & Area -->\n      <rect x=\"400\" y=\"15\" width=\"365\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"420\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">2. Velocity-Time ($v-t$) Relations:</text>\n      \n      <!-- Coordinate axes -->\n      <line x1=\"435\" y1=\"180\" x2=\"735\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <line x1=\"435\" y1=\"180\" x2=\"435\" y2=\"55\" stroke=\"#64748b\" stroke-width=\"1.8\"/>\n      <text x=\"740\" y=\"184\" font-size=\"10\" fill=\"#64748b\">Time ($t$)</text>\n      <text x=\"415\" y=\"50\" font-size=\"10\" fill=\"#64748b\">Vel ($v$)</text>\n\n      <!-- Trapezoid area under v-t curve -->\n      <polygon points=\"435,140 590,75 590,180 435,180\" fill=\"#ede9fe\" stroke=\"#7c3aed\" stroke-width=\"1.5\"/>\n      <line x1=\"435\" y1=\"140\" x2=\"590\" y2=\"75\" stroke=\"#7c3aed\" stroke-width=\"3\"/>\n\n      <!-- Annotations -->\n      <text x=\"445\" y=\"135\" font-size=\"10\" font-weight=\"bold\" fill=\"#7c3aed\">u</text>\n      <text x=\"595\" y=\"75\" font-size=\"10\" font-weight=\"bold\" fill=\"#7c3aed\">v</text>\n      <text x=\"470\" y=\"160\" font-size=\"10\" font-weight=\"bold\" fill=\"#5b21b6\">Area = Displacement (&Delta;x)</text>\n      <text x=\"515\" y=\"100\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#2563eb\">Slope = Acceleration (a)</text>\n\n      <!-- Retardation line -->\n      <line x1=\"590\" y1=\"75\" x2=\"720\" y2=\"180\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n      <text x=\"640\" y=\"125\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#dc2626\">Retardation (a &lt; 0)</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 2.1 to 2.22: Point Objects, $x-t$ &amp; $v-t$ Graph Interpretations, Relative Velocity &amp; Kinematic Equations</div>\n\n  <!-- c11p-ch2-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q1')\">\n      <div class=\"q-num\">Question 2.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In which of the following examples of motion, can the body be considered approximately a point object:<br>(a) a railway carriage moving without jerks between two stations.<br>(b) a monkey sitting on top of a man cycling smoothly on a circular track.<br>(c) a spinning cricket ball that turns sharply on hitting the ground.<br>(d) a tumbling beaker that has slipped off the edge of a table.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Criterion for a Point Object:</b> An object is treated as a point object if the linear distance it travels is very large compared to its own geometrical dimensions.<br><br>\n    • <b>(a) Railway carriage between stations:</b> The distance between two railway stations is typically several kilometers, which is enormously larger than the length of a single carriage (~$20$–$30\\text{ m}$). Hence, the carriage <b>can be considered a point object</b>.<br><br>\n    • <b>(b) Monkey on a cycling man:</b> The radius and perimeter of a normal circular cycling track is very large compared to the size of the monkey. Hence, the monkey <b>can be treated approximately as a point object</b>.<br><br>\n    • <b>(c) Spinning cricket ball:</b> While turning sharply on the pitch, the rotational motion and deformation/contact area of the ball are comparable to its diameter, and spin significantly influences its trajectory over a short path. Hence, it <b>cannot be considered a point object</b>.<br><br>\n    • <b>(d) Tumbling beaker off table:</b> The height of a normal laboratory table ($~1\\text{ m}$) is comparable to the size of the beaker ($~10$–$15\\text{ cm}$), and tumbling involves significant rotational motion over this short distance. Hence, the beaker <b>cannot be treated as a point object</b>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of point object in terms of path distance vs body dimensions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification for (a) and (b) as valid point approximations</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification for (c) and (d) rejecting point object model</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q2')\">\n      <div class=\"q-num\">Question 2.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The position-time ($x-t$) graphs for two children A and B returning from their school $O$ to their homes $P$ and $Q$ respectively are shown in Fig. 2.1. Choose the correct entries in the brackets below:<br>(a) (A/B) lives closer to the school than (B/A)<br>(b) (A/B) starts from the school earlier than (B/A)<br>(c) (A/B) walks faster than (B/A)<br>(d) A and B reach home at the (same/different) time<br>(e) (A/B) overtakes (B/A) on the road (once/twice).\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Refer to the position-time graph with origin $O$ at the school:<br><br>\n    • <b>(a) Home distance:</b> The vertical intercept on the position axis represents the distance of the home from the school $O$. Distance $OP < OQ$. Therefore, <b>A lives closer to the school than B</b>.<br><br>\n    • <b>(b) Starting time:</b> For child A, motion starts at $t = 0$. For child B, motion starts at a positive time $t > 0$. Therefore, <b>A starts from the school earlier than B</b>.<br><br>\n    • <b>(c) Walking speed:</b> The slope of the $x-t$ graph represents velocity ($v = \\frac{dx}{dt}$). The slope of straight line B is steeper than line A ($\\text{Slope}_B > \\text{Slope}_A$). Therefore, <b>B walks faster than A</b>.<br><br>\n    • <b>(d) Arrival time:</b> By projecting the respective endpoints corresponding to $P$ and $Q$ onto the time axis, both lines terminate at the same time coordinate $t$ (or child B reaches earlier depending on exact graph coordinates; in the standard NCERT diagram, child A and child B reach home at <b>different</b> times, with B taking less time).<br><br>\n    • <b>(e) Overtaking:</b> The two graphs intersect at exactly one point where their position coordinates coincide at the same instant. Since B starts later but walks faster, <b>B overtakes A on the road once</b>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Correct choice based on position intercepts $OP < OQ$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Starting time deduced from time axis origins</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Speed evaluated via slope of $x-t$ curve ($v = \\Delta x / \\Delta t$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Arrival time analysis at home coordinates</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Single point of intersection indicating B overtakes A once</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q3')\">\n      <div class=\"q-num\">Question 2.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A woman starts from her home at $9.00\\text{ am}$, walks with a speed of $5\\text{ km h}^{-1}$ on a straight road up to her office $2.5\\text{ km}$ away, stays at the office up to $5.00\\text{ pm}$, and returns home by an auto with a speed of $25\\text{ km h}^{-1}$. Choose suitable scales and plot the $x-t$ graph of her motion.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Forward Journey (Home to Office):</b><br>\n    • Distance $d = 2.5\\text{ km}$, Speed $v_1 = 5\\text{ km h}^{-1}$.<br>\n    • Time taken $t_1 = \\frac{d}{v_1} = \\frac{2.5\\text{ km}}{5\\text{ km h}^{-1}} = 0.5\\text{ h} = 30\\text{ minutes}$.<br>\n    • She reaches office at $9.00\\text{ am} + 30\\text{ min} = \\mathbf{9.30\\text{ am}}$.<br><br>\n    <b>2. Stay at Office:</b><br>\n    • From $9.30\\text{ am}$ to $5.00\\text{ pm}$ ($7.5\\text{ hours}$), she remains stationary at $x = 2.5\\text{ km}$.<br>\n    • The graph is a straight horizontal line parallel to the time axis.<br><br>\n    <b>3. Return Journey (Office to Home):</b><br>\n    • Speed $v_2 = 25\\text{ km h}^{-1}$.<br>\n    • Time taken $t_2 = \\frac{2.5\\text{ km}}{25\\text{ km h}^{-1}} = 0.1\\text{ h} = 6\\text{ minutes}$.<br>\n    • She reaches home at $5.00\\text{ pm} + 6\\text{ min} = \\mathbf{5.06\\text{ pm}}$.<br><br>\n    <b>Graph Description:</b><br>\n    • Time axis: $1\\text{ cm} = 1\\text{ hour}$ (from $9.00\\text{ am}$ to $6.00\\text{ pm}$).<br>\n    • Position axis: $1\\text{ cm} = 0.5\\text{ km}$ (from $0$ to $2.5\\text{ km}$).<br>\n    • Straight line with positive slope from $(9.00\\text{ am}, 0)$ to $(9.30\\text{ am}, 2.5\\text{ km})$.<br>\n    • Horizontal line from $(9.30\\text{ am}, 2.5\\text{ km})$ to $(5.00\\text{ pm}, 2.5\\text{ km})$.<br>\n    • Steep negative slope from $(5.00\\text{ pm}, 2.5\\text{ km})$ to $(5.06\\text{ pm}, 0)$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of forward walking travel time ($30\\text{ min}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stationary duration representation at office ($9:30\\text{ am}$ to $5:00\\text{ pm}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of auto return journey time ($6\\text{ min}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scale specification and piecewise linear $x-t$ plot profile</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q4')\">\n      <div class=\"q-num\">Question 2.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A drunkard walking in a narrow lane takes 5 steps forward and 3 steps backward, followed again by 5 steps forward and 3 steps backward, and so on. Each step is $1\\text{ m}$ long and requires $1\\text{ s}$. Determine chronologically and graphically how long the drunkard takes to fall into a pit $13\\text{ m}$ away from the start.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Step Analysis:</b><br>\n    • 1 forward step = $+1\\text{ m}$ in $1\\text{ s}$.<br>\n    • 1 backward step = $-1\\text{ m}$ in $1\\text{ s}$.<br>\n    • In each cycle of $(5 + 3) = 8\\text{ steps}$, time taken = $8\\text{ s}$.<br>\n    • Net displacement per cycle = $5\\text{ m} - 3\\text{ m} = +2\\text{ m}$.<br><br>\n    <b>2. Cumulative Cycle Tracking:</b><br>\n    • Cycle 1 ($t = 8\\text{ s}$): Net position = $2\\text{ m}$.<br>\n    • Cycle 2 ($t = 16\\text{ s}$): Net position = $4\\text{ m}$.<br>\n    • Cycle 3 ($t = 24\\text{ s}$): Net position = $6\\text{ m}$.<br>\n    • Cycle 4 ($t = 32\\text{ s}$): Net position = $8\\text{ m}$.<br><br>\n    <b>3. Final Forward Stride:</b><br>\n    • At $t = 32\\text{ s}$, he is at position $x = 8\\text{ m}$.<br>\n    • The pit is at $x = 13\\text{ m}$, which is $(13 - 8) = 5\\text{ m}$ ahead.<br>\n    • He now takes 5 forward steps, covering $5\\text{ m}$ in $5\\text{ s}$.<br>\n    • Position reached = $8\\text{ m} + 5\\text{ m} = 13\\text{ m}$ (into the pit!).<br>\n    • He immediately falls into the pit and does <i>not</i> take the 3 backward steps.<br><br>\n    $$\\text{Total Time} = 32\\text{ s} + 5\\text{ s} = \\mathbf{37\\text{ seconds}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of cycle displacement ($+2\\text{ m}$) and time ($8\\text{ s}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Position calculation after 4 complete cycles ($8\\text{ m}$ at $32\\text{ s}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Recognizing that final 5 steps hit the pit before backward steps occur</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final correct answer: $37\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q5')\">\n      <div class=\"q-num\">Question 2.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A jet airplane travelling at the speed of $500\\text{ km h}^{-1}$ ejects its products of combustion at the speed of $1500\\text{ km h}^{-1}$ relative to the jet plane. What is the speed of the latter with respect to an observer on the ground?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let the direction of motion of the jet plane be positive.<br><br>\n    • Speed of jet plane relative to ground: $v_J = +500\\text{ km h}^{-1}$.<br>\n    • The combustion products are ejected in the opposite direction (backwards).<br>\n    • Relative speed of combustion products with respect to jet: $v_{CJ} = -1500\\text{ km h}^{-1}$.<br><br>\n    Using the relative velocity relation:<br>\n    $$v_{CJ} = v_C - v_J$$<br>\n    $$v_C = v_{CJ} + v_J = -1500 + 500 = \\mathbf{-1000\\text{ km h}^{-1}}$$\n    <br>\n    The negative sign indicates that the combustion products move opposite to the jet plane.<br>\n    Therefore, with respect to an observer on the ground, the combustion products move at a speed of $\\mathbf{1000\\text{ km h}^{-1}}$ in the direction opposite to the flight of the jet.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Sign convention and vector relative velocity equation stated</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution: $v_C = v_{CJ} + v_J = -1500 + 500$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer with direction: $1000\\text{ km h}^{-1}$ opposite to flight</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q6')\">\n      <div class=\"q-num\">Question 2.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A car moving along a straight highway with speed of $126\\text{ km h}^{-1}$ is brought to a stop within a distance of $200\\text{ m}$. What is the retardation of the car (assumed uniform), and how long does it take for the car to stop?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Given:</b><br>\n    • Initial velocity $u = 126\\text{ km h}^{-1} = 126 \\times \\frac{5}{18}\\text{ m s}^{-1} = 35\\text{ m s}^{-1}$.<br>\n    • Final velocity $v = 0$.<br>\n    • Stopping distance $s = 200\\text{ m}$.<br><br>\n    <b>1. Calculation of Retardation ($a$):</b><br>\n    Using the third kinematic equation $v^2 = u^2 + 2as$:<br>\n    $$0^2 = (35)^2 + 2a(200)$$<br>\n    $$400a = -1225 \\implies a = -\\frac{1225}{400} = -3.0625\\text{ m s}^{-2}$$<br>\n    $$\\therefore \\text{Retardation } = -a = \\mathbf{3.06\\text{ m s}^{-2}}$$\n    <br>\n    <b>2. Calculation of Time Taken ($t$):</b><br>\n    Using the first kinematic equation $v = u + at$:<br>\n    $$0 = 35 - 3.0625 t \\implies t = \\frac{35}{3.0625} = \\mathbf{11.43\\text{ s}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Unit conversion $126\\text{ km/h} = 35\\text{ m/s}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Use of $v^2 - u^2 = 2as$ to find retardation $a = 3.06\\text{ m/s}^2$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Use of $v = u + at$ to find stopping time $t = 11.43\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q7')\">\n      <div class=\"q-num\">Question 2.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Two trains A and B of length $400\\text{ m}$ each are moving on two parallel tracks with a uniform speed of $72\\text{ km h}^{-1}$ in the same direction, with A ahead of B. The driver of B decides to overtake A and accelerates by $1\\text{ m s}^{-2}$. If after $50\\text{ s}$, the guard of B just brushes past the driver of A, what was the original distance between them?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Given:</b><br>\n    • Speed of both trains $u_A = u_B = 72\\text{ km h}^{-1} = 72 \\times \\frac{5}{18} = 20\\text{ m s}^{-1}$.<br>\n    • Length of train A = $L_A = 400\\text{ m}$; Length of train B = $L_B = 400\\text{ m}$.<br>\n    • Acceleration of A: $a_A = 0$; Acceleration of B: $a_B = 1\\text{ m s}^{-2}$.<br>\n    • Time $t = 50\\text{ s}$.<br><br>\n    <b>Relative Motion Formulation:</b><br>\n    Let relative acceleration of B with respect to A be $a_{rel} = a_B - a_A = 1 - 0 = 1\\text{ m s}^{-2}$.<br>\n    Initial relative speed $u_{rel} = u_B - u_A = 20 - 20 = 0\\text{ m s}^{-1}$.<br><br>\n    Distance covered by B relative to A in $50\\text{ s}$:<br>\n    $$s_{rel} = u_{rel}t + \\frac{1}{2}a_{rel}t^2 = 0 + \\frac{1}{2}(1)(50)^2 = \\frac{2500}{2} = 1250\\text{ m}$$\n    <br>\n    <b>Geometrical Relation:</b><br>\n    For the guard of B (tail of B) to brush past the driver of A (front of A):<br>\n    $$s_{rel} = \\text{Original separation } (d) + \\text{Length of A} + \\text{Length of B}$$<br>\n    $$1250 = d + 400 + 400 = d + 800$$<br>\n    $$d = 1250 - 800 = \\mathbf{450\\text{ m}}$$\n    <br>\n    $$\\therefore \\text{Original distance between the two trains was } \\mathbf{450\\text{ m}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Speed conversion to $20\\text{ m/s}$ and relative acceleration setup</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative distance calculated: $s_{rel} = 1250\\text{ m}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inclusion of train lengths: $s_{rel} = d + L_A + L_B$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final separation $d = 450\\text{ m}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q8')\">\n      <div class=\"q-num\">Question 2.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        On a two-lane road, car A is travelling with a speed of $36\\text{ km h}^{-1}$. Two cars B and C approach car A in opposite directions with a speed of $54\\text{ km h}^{-1}$ each. At a certain instant, when the distance AB is equal to AC, both being $1\\text{ km}$, B decides to overtake A before C does. What minimum acceleration of car B is required to avoid an accident?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Speeds:</b><br>\n    • $v_A = 36\\text{ km h}^{-1} = 36 \\times \\frac{5}{18} = 10\\text{ m s}^{-1}$ (moving forward, say $+x$).<br>\n    • $v_B = 54\\text{ km h}^{-1} = 54 \\times \\frac{5}{18} = 15\\text{ m s}^{-1}$ (moving in same direction as A).<br>\n    • $v_C = 54\\text{ km h}^{-1} = 15\\text{ m s}^{-1}$ (approaching in opposite direction, $-x$).<br><br>\n    <b>1. Relative velocity of C with respect to A:</b><br>\n    $$v_{CA} = v_C - (-v_A) = 15 + 10 = 25\\text{ m s}^{-1}$$<br>\n    Distance between A and C = $1\\text{ km} = 1000\\text{ m}$.<br>\n    Time taken for car C to reach car A:<br>\n    $$t = \\frac{\\text{Distance}}{v_{CA}} = \\frac{1000}{25} = \\mathbf{40\\text{ s}}$$\n    <br>\n    <b>2. Required Acceleration of car B:</b><br>\n    Car B must cover the $1000\\text{ m}$ separation relative to car A in less than or equal to $40\\text{ s}$.<br>\n    Relative velocity of B with respect to A:<br>\n    $$u_{BA} = v_B - v_A = 15 - 10 = 5\\text{ m s}^{-1}$$<br>\n    Using relative kinematic equation $s = u_{BA}t + \\frac{1}{2}at^2$:<br>\n    $$1000 = 5(40) + \\frac{1}{2}a(40)^2$$<br>\n    $$1000 = 200 + 800a$$<br>\n    $$800a = 800 \\implies a = \\mathbf{1.0\\text{ m s}^{-2}}$$\n    <br>\n    $$\\therefore \\text{Minimum acceleration of car B required to avoid an accident is } \\mathbf{1\\text{ m s}^{-2}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Speed conversions: $v_A = 10\\text{ m/s}$, $v_B = 15\\text{ m/s}$, $v_C = 15\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative velocity $v_{CA} = 25\\text{ m/s}$ and time to pass $t = 40\\text{ s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Kinematic equation for car B relative to A with $u_{BA} = 5\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final minimum acceleration $a = 1\\text{ m s}^{-2}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q9')\">\n      <div class=\"q-num\">Question 2.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Two towns A and B are connected by a regular bus service with a bus leaving in either direction every $T$ minutes. A man cycling with a speed of $20\\text{ km h}^{-1}$ in the direction A to B notices that a bus goes past him every $18\\text{ min}$ in the direction of his motion, and every $6\\text{ min}$ in the opposite direction. What is the period $T$ of the bus service and with what speed (assumed constant) do the buses ply on the road?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let speed of each bus = $v_b\\text{ km h}^{-1}$.<br>\n    Speed of cyclist = $v_c = 20\\text{ km h}^{-1}$.<br>\n    Distance between consecutive buses leaving the station = $d = v_b \\times \\frac{T}{60}\\text{ km}$.<br><br>\n    • <b>Buses moving in same direction (A to B):</b><br>\n      Relative speed = $(v_b - v_c) = (v_b - 20)\\text{ km h}^{-1}$.<br>\n      Time interval between buses = $18\\text{ min} = \\frac{18}{60}\\text{ h}$.<br>\n      $$\\therefore d = (v_b - 20) \\times \\frac{18}{60} \\quad \\text{--- (Equation 1)}$$<br><br>\n    • <b>Buses moving in opposite direction (B to A):</b><br>\n      Relative speed = $(v_b + v_c) = (v_b + 20)\\text{ km h}^{-1}$.<br>\n      Time interval between buses = $6\\text{ min} = \\frac{6}{60}\\text{ h}$.<br>\n      $$\\therefore d = (v_b + 20) \\times \\frac{6}{60} \\quad \\text{--- (Equation 2)}$$<br><br>\n    Equating the two distances:<br>\n    $$(v_b - 20) \\times 18 = (v_b + 20) \\times 6$$<br>\n    $$3(v_b - 20) = v_b + 20 \\implies 3v_b - 60 = v_b + 20$$<br>\n    $$2v_b = 80 \\implies \\mathbf{v_b = 40\\text{ km h}^{-1}}$$\n    <br>\n    Substituting $v_b = 40$ into $d = v_b \\frac{T}{60}$ and Equation 2:<br>\n    $$40 \\times \\frac{T}{60} = (40 + 20) \\times \\frac{6}{60}$$<br>\n    $$40 T = 60 \\times 6 = 360 \\implies \\mathbf{T = 9\\text{ minutes}}$$\n    <br>\n    $$\\therefore \\text{Bus speed } = \\mathbf{40\\text{ km h}^{-1}}, \\quad \\text{Service interval } T = \\mathbf{9\\text{ minutes}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Relative velocity setup for same direction ($v_b - 20$) and opposite direction ($v_b + 20$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equating distance equations for relative travel</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for bus speed: $v_b = 40\\text{ km h}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for service interval: $T = 9\\text{ minutes}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q10')\">\n      <div class=\"q-num\">Question 2.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A player throws a ball upwards with an initial speed of $29.4\\text{ m s}^{-1}$.<br>(a) What is the direction of acceleration during the upward motion of the ball?<br>(b) What are the velocity and acceleration of the ball at the highest point of its motion?<br>(c) Choose the $x = 0\\text{ m}$ and $t = 0\\text{ s}$ to be the location and time of the ball at its highest point, vertically downward direction to be the positive direction of x-axis, and give the signs of position, velocity and acceleration of the ball during its upward, and downward motion.<br>(d) To what height does the ball rise and after how long does the ball return to the player’s hands? (Take $g = 9.8\\text{ m s}^{-2}$ and neglect air resistance).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Direction of acceleration:</b> Throughout the flight (upward, at peak, and downward), the only force acting on the ball is gravity. Therefore, acceleration is always directed <b>vertically downwards</b> towards the center of Earth ($g = 9.8\\text{ m s}^{-2}$).<br><br>\n    • <b>(b) At the highest point:</b><br>\n      Velocity $v = \\mathbf{0\\text{ m s}^{-1}}$ (instantaneously at rest).<br>\n      Acceleration $a = \\mathbf{9.8\\text{ m s}^{-2}\\text{ vertically downwards}}$.<br><br>\n    • <b>(c) Signs with origin at highest point ($x=0$) and downward as positive ($+x$):</b><br>\n      - <i>During upward motion:</i> The ball is below the highest point, so $x < 0$ (<b>negative</b>). It is moving upward (opposite to positive downwards), so velocity $v < 0$ (<b>negative</b>). Gravity acts downward, so acceleration $a > 0$ (<b>positive</b>).<br>\n      - <i>During downward motion:</i> The ball is below the highest point, so $x > 0$ (<b>positive</b>). It is moving downwards, so velocity $v > 0$ (<b>positive</b>). Acceleration acts downward, so $a > 0$ (<b>positive</b>).<br><br>\n    • <b>(d) Maximum height and total time:</b><br>\n      At max height $H$, $v = 0$. Using $v^2 = u^2 - 2gH$:<br>\n      $$0 = (29.4)^2 - 2(9.8)H \\implies 19.6 H = 864.36 \\implies H = \\mathbf{44.1\\text{ m}}$$<br>\n      Time of ascent $t_1 = \\frac{u}{g} = \\frac{29.4}{9.8} = 3.0\\text{ s}$.<br>\n      Since air resistance is neglected, time of ascent = time of descent.<br>\n      $$\\text{Total time of flight} = 2 \\times 3.0 = \\mathbf{6.0\\text{ seconds}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Acceleration direction vertically downward throughout</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Velocity $= 0$, acceleration $= 9.8\\text{ m/s}^2$ downward at apex</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Correct sign designations for upward ($x<0, v<0, a>0$) and downward ($x>0, v>0, a>0$)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Maximum height $H = 44.1\\text{ m}$ and total time $T = 6.0\\text{ s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q11')\">\n      <div class=\"q-num\">Question 2.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Read each statement below carefully and state with reasons and examples, if it is true or false;<br>A particle in one-dimensional motion<br>(a) with zero speed at an instant may have non-zero acceleration at that instant<br>(b) with zero speed may have non-zero velocity,<br>(c) with constant speed must have zero acceleration,<br>(d) with positive value of acceleration must be speeding up.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) True:</b> When a ball is thrown vertically upwards, at the highest point its instantaneous speed is zero, but its acceleration is non-zero ($g = 9.8\\text{ m s}^{-2}$ vertically downwards).<br><br>\n    • <b>(b) False:</b> Speed is the magnitude of velocity ($|\\vec{v}|$). If speed is zero, the magnitude of velocity is zero, so velocity must be identically zero.<br><br>\n    • <b>(c) True:</b> In 1D motion, there are only two directions (positive or negative). If speed is constant and motion is in 1D, velocity cannot change its magnitude or direction without momentarily passing through zero. Thus, $\\frac{dv}{dt} = 0$, meaning acceleration must be zero. (Note: in 2D circular motion, constant speed has centripetal acceleration, but here motion is strictly 1D).<br><br>\n    • <b>(d) False:</b> Speeding up occurs when velocity and acceleration have the <i>same</i> sign. If velocity is negative ($v < 0$) and acceleration is positive ($a > 0$), the speed ($|v|$) decreases (the particle slows down). For example, a ball thrown upwards with downward chosen as the negative direction.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) True with ball at highest point counterexample</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False since speed is the magnitude of velocity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True for strict 1D rectilinear motion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) False since positive acceleration retards negative velocity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q12')\">\n      <div class=\"q-num\">Question 2.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A ball is dropped from a height of $90\\text{ m}$ on a floor. At each collision with the floor, the ball loses one tenth of its speed. Plot the speed-time graph of its motion between $t = 0$ to $12\\text{ s}$.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. First Fall from $90\\text{ m}$ ($t = 0$ to $t_1$):</b><br>\n    Initial velocity $u = 0$, $s = 90\\text{ m}$, $g = 9.8\\text{ m s}^{-2}$.<br>\n    Time to hit floor: $t_1 = \\sqrt{\\frac{2s}{g}} = \\sqrt{\\frac{2 \\times 90}{9.8}} = \\sqrt{18.367} \\approx \\mathbf{4.28\\text{ s}}$.<br>\n    Speed on impact: $v_1 = \\sqrt{2gs} = \\sqrt{2 \\times 9.8 \\times 90} = \\sqrt{1764} = \\mathbf{42\\text{ m s}^{-1}}$.<br><br>\n    <b>2. First Rebound:</b><br>\n    Speed lost = $\\frac{1}{10} v_1 = 4.2\\text{ m s}^{-1}$.<br>\n    Rebound speed: $u_2 = \\frac{9}{10} \\times 42 = \\mathbf{37.8\\text{ m s}^{-1}}$.<br>\n    Time of ascent to new peak: $t_2 = \\frac{u_2}{g} = \\frac{37.8}{9.8} \\approx \\mathbf{3.86\\text{ s}}$.<br>\n    Time of descent back to floor: $t_3 = t_2 = \\mathbf{3.86\\text{ s}}$.<br>\n    Total time for this bounce cycle = $2 \\times 3.86 = 7.72\\text{ s}$.<br>\n    Next floor impact occurs at: $t = 4.28 + 7.72 = \\mathbf{12.0\\text{ s}}$!<br>\n    Speed just before second impact = $37.8\\text{ m s}^{-1}$.<br><br>\n    <b>3. Speed-Time Graph Description:</b><br>\n    • From $t = 0$ to $4.28\\text{ s}$: Speed increases linearly from $0$ to $42\\text{ m s}^{-1}$ ($v = gt$).<br>\n    • At $t = 4.28\\text{ s}$: Speed drops discontinuously from $42\\text{ m s}^{-1}$ to $37.8\\text{ m s}^{-1}$.<br>\n    • From $t = 4.28$ to $8.14\\text{ s}$: Speed decreases linearly from $37.8\\text{ m s}^{-1}$ to $0$.<br>\n    • From $t = 8.14$ to $12.0\\text{ s}$: Speed increases linearly from $0$ to $37.8\\text{ m s}^{-1}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">First impact time $t_1 = 4.28\\text{ s}$ and velocity $v_1 = 42\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rebound speed $u_2 = 37.8\\text{ m/s}$ with 10% kinetic speed loss</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Time of bounce cycle $2 \\times 3.86 = 7.72\\text{ s}$ terminating at $t = 12\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Piecewise linear speed-time graph characteristic slopes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q13')\">\n      <div class=\"q-num\">Question 2.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain clearly, with examples, the distinction between:<br>(a) magnitude of displacement (sometimes called distance) over an interval of time, and the total length of path covered by a particle over the same interval;<br>(b) magnitude of average velocity over an interval of time, and the average speed over the same interval. [Average speed of a particle over an interval of time is defined as the total path length divided by the time interval]. Show in both (a) and (b) that the second quantity is either greater than or equal to the first. When is the equality sign true? [For simplicity, consider one-dimensional motion only].\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Magnitude of Displacement vs Total Path Length:</b><br>\n      - <i>Magnitude of displacement:</i> It is the shortest straight-line distance between the initial and final positions of the particle: $|\\Delta x| = |x_2 - x_1|$.<br>\n      - <i>Total path length:</i> It is the actual distance travelled along the path taken by the particle.<br>\n      - <i>Example:</i> A person walks from $x = 0$ to $x = +100\\text{ m}$ and returns back to $x = +40\\text{ m}$.<br>\n        Displacement magnitude = $|40 - 0| = 40\\text{ m}$.<br>\n        Total path length = $100\\text{ m} + 60\\text{ m} = 160\\text{ m}$.<br>\n        Clearly, $\\mathbf{\\text{Total path length} \\ge |\\text{Displacement}|}$.<br><br>\n    • <b>(b) Average Speed vs Magnitude of Average Velocity:</b><br>\n      - Magnitude of average velocity: $|\\bar{v}| = \\frac{|\\Delta x|}{\\Delta t}$.<br>\n      - Average speed: $v_{avg} = \\frac{\\text{Total path length}}{\\Delta t}$.<br>\n      - Since total path length $\\ge |\\Delta x|$, dividing both sides by positive $\\Delta t$ gives:<br>\n        $$\\mathbf{v_{avg} \\ge |\\bar{v}|}$$\n    <br>\n    • <b>Condition for Equality:</b><br>\n      The equality sign holds ($\\text{Path Length} = |\\text{Displacement}|$ and $v_{avg} = |\\bar{v}|$) <b>if and only if the particle moves strictly in a straight line in a single unidirectional sense without reversing its direction</b>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear mathematical distinction between displacement magnitude and path length with 1D example</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation showing average speed $\\ge$ average velocity magnitude</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exact equality condition: unidirectional motion without reversal</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q14')\">\n      <div class=\"q-num\">Question 2.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A man walks on a straight road from his home to a market $2.5\\text{ km}$ away with a speed of $5\\text{ km h}^{-1}$. Finding the market closed, he instantly turns and walks back home with a speed of $7.5\\text{ km h}^{-1}$. What is the<br>(a) magnitude of average velocity, and<br>(b) average speed of the man over the interval of time (i) 0 to $30\\text{ min}$, (ii) 0 to $50\\text{ min}$, (iii) 0 to $40\\text{ min}$?\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Time calculations:</b><br>\n    • Time taken from home to market: $t_1 = \\frac{2.5\\text{ km}}{5\\text{ km h}^{-1}} = 0.5\\text{ h} = 30\\text{ min}$.<br>\n    • Time taken from market to home: $t_2 = \\frac{2.5\\text{ km}}{7.5\\text{ km h}^{-1}} = \\frac{1}{3}\\text{ h} = 20\\text{ min}$.<br>\n    • Total round trip time = $30 + 20 = 50\\text{ min}$.<br><br>\n    <b>(i) Interval 0 to 30 min:</b><br>\n    • Position at $30\\text{ min}$: at the market ($x = 2.5\\text{ km}$).<br>\n    • Displacement = $2.5\\text{ km}$; Path length = $2.5\\text{ km}$.<br>\n    • Magnitude of average velocity = $\\frac{2.5\\text{ km}}{0.5\\text{ h}} = \\mathbf{5\\text{ km h}^{-1}}$.<br>\n    • Average speed = $\\frac{2.5\\text{ km}}{0.5\\text{ h}} = \\mathbf{5\\text{ km h}^{-1}}$.<br><br>\n    <b>(ii) Interval 0 to 50 min:</b><br>\n    • Position at $50\\text{ min}$: back home ($x = 0$).<br>\n    • Net displacement = $0\\text{ km}$.<br>\n    • Total path length = $2.5 + 2.5 = 5.0\\text{ km}$.<br>\n    • Magnitude of average velocity = $\\frac{0}{50/60} = \\mathbf{0\\text{ km h}^{-1}}$.<br>\n    • Average speed = $\\frac{5.0\\text{ km}}{50/60\\text{ h}} = \\frac{5 \\times 6}{5} = \\mathbf{6.0\\text{ km h}^{-1}}$.<br><br>\n    <b>(iii) Interval 0 to 40 min:</b><br>\n    • In the first $30\\text{ min}$, he walks $2.5\\text{ km}$ to market.<br>\n    • In the next $10\\text{ min}$ ($1/6\\text{ h}$), return distance = $7.5 \\times \\frac{1}{6} = 1.25\\text{ km}$.<br>\n    • Net displacement from home = $2.5 - 1.25 = 1.25\\text{ km}$.<br>\n    • Total path length = $2.5 + 1.25 = 3.75\\text{ km}$.<br>\n    • Magnitude of average velocity = $\\frac{1.25\\text{ km}}{40/60\\text{ h}} = \\frac{1.25 \\times 3}{2} = \\mathbf{1.875\\text{ km h}^{-1}}$.<br>\n    • Average speed = $\\frac{3.75\\text{ km}}{40/60\\text{ h}} = \\frac{3.75 \\times 3}{2} = \\mathbf{5.625\\text{ km h}^{-1}}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Travel time breakdown: $30\\text{ min}$ forward, $20\\text{ min}$ return</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) $0$–$30\\text{ min}$: avg velocity $= 5\\text{ km/h}$, avg speed $= 5\\text{ km/h}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) $0$–$50\\text{ min}$: avg velocity $= 0$, avg speed $= 6\\text{ km/h}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) $0$–$40\\text{ min}$: avg velocity $= 1.875\\text{ km/h}$, avg speed $= 5.625\\text{ km/h}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q15')\">\n      <div class=\"q-num\">Question 2.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In Exercises 2.13 and 2.14, we have carefully distinguished between average speed and magnitude of average velocity. No such distinction is necessary when we consider instantaneous speed and magnitude of instantaneous velocity. The instantaneous speed is always equal to the magnitude of instantaneous velocity. Why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Mathematical Explanation:</b><br>\n    By definition, instantaneous velocity is the derivative of position with respect to time over an infinitesimal time interval $\\Delta t \\to 0$:<br>\n    $$\\vec{v} = \\lim_{\\Delta t \\to 0} \\frac{\\Delta \\vec{x}}{\\Delta t}$$<br>\n    The magnitude of instantaneous velocity is:<br>\n    $$|\\vec{v}| = \\lim_{\\Delta t \\to 0} \\frac{|\\Delta \\vec{x}|}{\\Delta t}$$<br><br>\n    Instantaneous speed is defined as the rate of path length covered over an infinitesimal time interval $\\Delta t \\to 0$:<br>\n    $$v = \\lim_{\\Delta t \\to 0} \\frac{\\Delta s}{\\Delta t}$$<br><br>\n    <b>The Infinitesimal Limit Principle:</b><br>\n    As the time interval $\\Delta t \\to 0$, the motion of a particle occurs over an infinitesimally short path segment. Over an infinitesimal time, a physical body cannot abruptly reverse or change direction; hence, the path covered $\\Delta s$ becomes strictly identical to the magnitude of the displacement vector $|\\Delta \\vec{x}|$:<br>\n    $$\\lim_{\\Delta t \\to 0} |\\Delta \\vec{x}| = \\lim_{\\Delta t \\to 0} \\Delta s$$<br>\n    Dividing both sides by $\\Delta t$ gives:<br>\n    $$|\\vec{v}| = v$$<br>\n    $$\\therefore \\text{Instantaneous speed is always identical to the magnitude of instantaneous velocity.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of instantaneous velocity as limit $\\Delta t \\to 0$ of $\\Delta x / \\Delta t$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equivalence of infinitesimal displacement $|\\Delta x|$ and arc length $\\Delta s$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rigorous conclusion that $|v| = \\text{instantaneous speed}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q16')\">\n      <div class=\"q-num\">Question 2.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Look at the graphs (a) to (d) in Fig. 2.3 carefully and state, with reasons, which of these cannot possibly represent one-dimensional motion of a particle.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>Graph (a) [$x-t$ closed curve/circle]:</b> At any given time $t$ within the circle, a vertical line drawn parallel to the position axis intersects the curve at two distinct values of position $x$. A particle cannot be in two different locations at the same instant in time. Hence, <b>Graph (a) cannot represent 1D motion</b>.<br><br>\n    • <b>Graph (b) [$v-t$ loop/ellipse]:</b> A vertical line intersects the curve at two different velocities for a single instant of time. A physical particle cannot possess two distinct velocities simultaneously. Hence, <b>Graph (b) cannot represent 1D motion</b>.<br><br>\n    • <b>Graph (c) [Speed-$t$ curve with negative values]:</b> Speed is the absolute magnitude of velocity and can never be negative ($v \\ge 0$). The graph displays negative values of speed. Hence, <b>Graph (c) cannot represent 1D motion</b>.<br><br>\n    • <b>Graph (d) [Total path length-$t$ curve with negative slope]:</b> Total path length covered by a moving body must continuously increase or remain constant with time; it can never decrease ($\\frac{ds}{dt} \\ge 0$). Graph (d) shows path length decreasing in certain intervals. Hence, <b>Graph (d) cannot represent 1D motion</b>.<br><br>\n    $$\\mathbf{\\text{Conclusion: None of the four graphs can represent 1D motion of a particle.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Rejected: Single time instant cannot have two distinct positions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Rejected: Single time instant cannot have two distinct velocities</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Rejected: Speed cannot be negative</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Rejected: Total path length can never decrease with time</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q17')\">\n      <div class=\"q-num\">Question 2.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fig. 2.4 shows the $x-t$ plot of one-dimensional motion of a particle. Is it correct to say from the graph that the particle moves in a straight line for $t < 0$ and on a parabolic path for $t > 0$? If not, suggest a suitable physical context for this graph.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Critique of the statement:</b><br>\n    <b>No, the statement is completely incorrect.</b><br>\n    An $x-t$ graph is a plot of <i>position versus time</i>, NOT the physical spatial trajectory (path in space) of the particle. The motion is given to be one-dimensional (rectilinear motion along a straight line, say the vertical or horizontal axis). The parabolic shape in the $x-t$ graph for $t > 0$ indicates that position depends quadratically on time ($x \\propto t^2$), which signifies <b>motion with constant acceleration along a straight line</b>, not motion along a physical curved parabolic path in 2D space.<br><br>\n    <b>2. Suitable Physical Context:</b><br>\n    A classic example is a ball dropped from rest from a certain height (or released from the edge of a roof at $t = 0$):<br>\n    • For $t < 0$, the ball is held at rest at origin ($x = 0$).<br>\n    • At $t = 0$, it is released and falls freely under gravity with constant downward acceleration $g$, following the relation $x = \\frac{1}{2}gt^2$ along a vertical straight line.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clarification that $x-t$ plot is not the trajectory in space</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Interpretation of parabolic $x-t$ as constant acceleration rectilinear motion ($x \\propto t^2$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical context example: freely falling body released at $t=0$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q18')\">\n      <div class=\"q-num\">NCERT Exercise</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A police van moving on a highway with a speed of $30\\text{ km h}^{-1}$ fires a bullet at a thief’s car speeding away in the same direction with a speed of $192\\text{ km h}^{-1}$. If the muzzle speed of the bullet is $150\\text{ m s}^{-1}$, with what speed does the bullet hit the thief’s car? (Note: Obtain that speed which is relevant for damaging the thief’s car).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Given Speeds:</b><br>\n    • Speed of police van: $v_P = 30\\text{ km h}^{-1} = 30 \\times \\frac{5}{18} = \\frac{25}{3}\\text{ m s}^{-1} \\approx 8.33\\text{ m s}^{-1}$.<br>\n    • Speed of thief’s car: $v_T = 192\\text{ km h}^{-1} = 192 \\times \\frac{5}{18} = \\frac{160}{3}\\text{ m s}^{-1} \\approx 53.33\\text{ m s}^{-1}$.<br>\n    • Muzzle speed of bullet relative to police gun/van: $v_{BP} = 150\\text{ m s}^{-1}$.<br><br>\n    <b>1. Speed of bullet with respect to ground ($v_B$):</b><br>\n    Since the bullet is fired from the moving police van in the forward direction:<br>\n    $$v_B = v_{BP} + v_P = 150 + \\frac{25}{3} = \\frac{475}{3}\\text{ m s}^{-1} \\approx 158.33\\text{ m s}^{-1}$$<br><br>\n    <b>2. Speed of bullet relative to thief’s car ($v_{BT}$):</b><br>\n    The speed that causes damage upon impact is the relative velocity of the bullet with respect to the thief's car:<br>\n    $$v_{BT} = v_B - v_T = \\frac{475}{3} - \\frac{160}{3} = \\frac{315}{3} = \\mathbf{105\\text{ m s}^{-1}}$$\n    <br>\n    $$\\therefore \\text{The bullet hits the thief’s car with a damaging speed of } \\mathbf{105\\text{ m s}^{-1}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Unit conversions to $\\text{m s}^{-1}$: $v_P = 25/3\\text{ m/s}$, $v_T = 160/3\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Absolute ground speed of bullet: $v_B = 150 + 25/3 = 475/3\\text{ m/s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative speed at impact: $v_{BT} = v_B - v_T = 315/3$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer: $105\\text{ m s}^{-1}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q19')\">\n      <div class=\"q-num\">Question 2.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Suggest a suitable physical situation for each of the following graphs (Fig. 2.5):<br>(a) $x-t$ graph showing position increasing, then becoming constant, then returning.<br>(b) $v-t$ graph showing alternating positive and negative velocity spikes with decreasing peaks.<br>(c) $a-t$ graph showing acceleration zero, a brief impulse spike, and returning to zero.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) $x-t$ Graph:</b> A ball is initially at rest at a wall. It is kicked towards another wall, rebounds, and comes to rest, OR a person walks from a room to a gate at constant speed, stops there for a while, and returns back.<br><br>\n    • <b>(b) $v-t$ Graph:</b> A ball is dropped on a hard floor from a certain height. It accelerates downwards (increasing speed), rebounds with reduced speed due to energy dissipation in collision, rises to a lower apex, falls again, and repeatedly bounces until coming to rest.<br><br>\n    • <b>(c) $a-t$ Graph:</b> A cricket ball moving with uniform velocity is struck sharply by a bat for a fraction of a second (providing an impulse of acceleration) and continues moving with uniform velocity thereafter.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Realistic physical situation for $x-t$ curve</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Bouncing ball model with collision dissipation for $v-t$ curve</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Impulsive force model (bat hitting cricket ball) for $a-t$ spike</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q20')\">\n      <div class=\"q-num\">Question 2.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fig. 2.6 gives the $x-t$ plot of a particle executing one-dimensional simple harmonic motion. Give the signs of position, velocity and acceleration variables of the particle at $t = 0.3\\text{ s}, 1.2\\text{ s}, -1.2\\text{ s}$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    In Simple Harmonic Motion (SHM), acceleration is related to position by:<br>\n    $$a = -\\omega^2 x$$<br>\n    Thus, acceleration $a$ always has the <b>opposite sign</b> to position $x$.<br>\n    Velocity $v = \\frac{dx}{dt}$ is given by the <b>slope</b> of the tangent to the $x-t$ curve at that instant.<br><br>\n    • <b>1. At $t = 0.3\\text{ s}$ (in the first valley):</b><br>\n      - Position $x < 0$ (<b>negative</b>).<br>\n      - Tangent slope is negative ($x$ is decreasing towards minima): velocity $v < 0$ (<b>negative</b>).<br>\n      - Acceleration $a = -\\omega^2 x > 0$ (<b>positive</b>).<br><br>\n    • <b>2. At $t = 1.2\\text{ s}$ (in the crest):</b><br>\n      - Position $x > 0$ (<b>positive</b>).<br>\n      - Tangent slope is positive ($x$ is rising): velocity $v > 0$ (<b>positive</b>).<br>\n      - Acceleration $a = -\\omega^2 x < 0$ (<b>negative</b>).<br><br>\n    • <b>3. At $t = -1.2\\text{ s}$ (on the negative time axis):</b><br>\n      - Position $x < 0$ (<b>negative</b>).<br>\n      - Tangent slope is positive ($x$ is increasing from negative minimum): velocity $v > 0$ (<b>positive</b>).<br>\n      - Acceleration $a = -\\omega^2 x > 0$ (<b>positive</b>).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">SHM relationship stated: $a = -\\omega^2 x$ and $v = \\text{slope of } x-t$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct signs at $t = 0.3\\text{ s}$ ($x<0, v<0, a>0$)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct signs at $t = 1.2\\text{ s}$ ($x>0, v>0, a<0$)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct signs at $t = -1.2\\text{ s}$ ($x<0, v>0, a>0$)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q21')\">\n      <div class=\"q-num\">Question 2.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fig. 2.7 gives the $x-t$ plot of a particle in one-dimensional motion. Three different equal intervals of time are shown. In which interval is the average speed greatest, and in which is it the least? Give the sign of average velocity for each interval.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Concept:</b><br>\n    • Average speed in any time interval $\\Delta t$ is given by $\\frac{\\text{Total path length}}{\\Delta t} = \\frac{|\\Delta x|}{\\Delta t}$, which is represented by the <i>steepness of the slope</i> of the chord connecting the endpoints of that interval.<br>\n    • Average velocity is given by $\\frac{x_2 - x_1}{\\Delta t}$, whose sign is determined by whether the chord slopes upward ($+$) or downward ($-$).<br><br>\n    <b>1. Greatest and Least Average Speed:</b><br>\n    • <b>Interval 3:</b> The slope of the curve is steepest in Interval 3. Therefore, <b>average speed is greatest in Interval 3</b>.<br>\n    • <b>Interval 2:</b> The curve is almost flat (horizontal chord, very small change in position). Therefore, <b>average speed is least in Interval 2</b>.<br><br>\n    <b>2. Signs of Average Velocity:</b><br>\n    • <b>Interval 1:</b> The position increases from initial to final instant (chord has upward slope). $\\therefore \\mathbf{\\text{Positive (+)}}$.<br>\n    • <b>Interval 2:</b> The position increases slightly (chord has upward slope). $\\therefore \\mathbf{\\text{Positive (+)}}$.<br>\n    • <b>Interval 3:</b> The position decreases sharply from initial to final instant (chord has downward slope). $\\therefore \\mathbf{\\text{Negative (-)}}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Criterion relating average speed to absolute slope steepness</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Greatest in Interval 3, least in Interval 2</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Signs of average velocity: Interval 1 (+), Interval 2 (+), Interval 3 (-)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch2-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch2-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch2-q22')\">\n      <div class=\"q-num\">Question 2.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fig. 2.8 gives a speed-time graph of a particle in motion along a constant direction. Three equal intervals of time are shown. In which interval is the average acceleration greatest in magnitude? In which interval is the average speed greatest? Choosing the positive direction as the constant direction of motion, give the signs of $v$ and $a$ in the three intervals. What are the accelerations at the points A, B, C and D?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Greatest Average Acceleration Magnitude:</b><br>\n    Average acceleration magnitude $|a_{avg}| = \\frac{|\\Delta v|}{\\Delta t}$, which equals the absolute slope of the speed-time curve. The slope is steepest in <b>Interval 2</b>.<br>\n    $$\\therefore \\text{Average acceleration is greatest in magnitude in } \\mathbf{\\text{Interval 2}}.$$\n    <br>\n    <b>2. Greatest Average Speed:</b><br>\n    Average speed is proportional to the area under the curve divided by $\\Delta t$. Interval 3 lies at the highest average speed values on the vertical axis.<br>\n    $$\\therefore \\text{Average speed is greatest in } \\mathbf{\\text{Interval 3}}.$$\n    <br>\n    <b>3. Signs of $v$ and $a$:</b><br>\n    Since motion is in the positive direction throughout, velocity $v > 0$ (<b>positive</b>) in all three intervals.<br>\n    • <b>Interval 1:</b> Slope is positive $\\implies a > 0$ (<b>positive</b>).<br>\n    • <b>Interval 2:</b> Slope is negative $\\implies a < 0$ (<b>negative</b>).<br>\n    • <b>Interval 3:</b> Curve is virtually flat parallel to time axis $\\implies a = 0$ (or slightly undulating).<br><br>\n    <b>4. Accelerations at points A, B, C and D:</b><br>\n    Points A, B, C and D are local peaks and valleys (maxima and minima) where the tangent to the speed-time graph is horizontal (slope $= 0$).<br>\n    $$\\therefore a_A = a_B = a_C = a_D = \\mathbf{0\\text{ m s}^{-2}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Greatest acceleration magnitude in Interval 2 based on slope steepness</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Greatest average speed in Interval 3 based on vertical altitude / area</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Signs of $v$ (positive in all) and $a$ (positive in 1, negative in 2, zero in 3)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Zero acceleration at points A, B, C, D due to horizontal tangents (slope $= 0$)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer;\">← Prev: Chapter 1 (Units &amp; Measurements)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#7c3aed; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 3 (Motion in a Plane) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c11p-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Physics &bull; Chapter 3</div>\n      <h2>Motion in a Plane</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 25 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.2\"><path d=\"M4 20h16\"/><path d=\"M4 20Q12 4 20 20\"/></svg>\n      2D Kinematics Dynamics: Projectile Parabolic Trajectory &amp; Vector Resolution\n    </h3>\n    <svg viewBox=\"0 0 780 230\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: Projectile Trajectory -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"35\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">1. Projectile Motion Trajectory &amp; Vectors:</text>\n\n      <!-- Trajectory curve -->\n      <path d=\"M 45 180 Q 200 40 355 180\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n      <line x1=\"40\" y1=\"180\" x2=\"365\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n\n      <!-- Launch vector -->\n      <line x1=\"45\" y1=\"180\" x2=\"115\" y2=\"110\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n      <polygon points=\"115,110 102,116 110,124\" fill=\"#2563eb\"/>\n      <text x=\"75\" y=\"105\" font-size=\"10\" font-weight=\"bold\" fill=\"#2563eb\">u</text>\n      <text x=\"75\" y=\"174\" font-size=\"9\" font-weight=\"bold\" fill=\"#475569\">&theta;</text>\n\n      <!-- Apex -->\n      <line x1=\"200\" y1=\"110\" x2=\"255\" y2=\"110\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <polygon points=\"255,110 245,106 245,114\" fill=\"#059669\"/>\n      <text x=\"200\" y=\"100\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#059669\">v_x = u cos &theta; (v_y = 0)</text>\n\n      <line x1=\"200\" y1=\"110\" x2=\"200\" y2=\"180\" stroke=\"#94a3b8\" stroke-dasharray=\"3,3\"/>\n      <text x=\"205\" y=\"150\" font-size=\"9\" font-weight=\"bold\" fill=\"#7c3aed\">H_max = u&sup2;sin&sup2;&theta;/2g</text>\n      <text x=\"170\" y=\"195\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#1e293b\">Range R = u&sup2;sin(2&theta;)/g</text>\n\n      <!-- Panel 2: Vector Triangle & Relative Velocity -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">2. Relative Velocity &amp; Vector Triangle:</text>\n\n      <!-- Triangle: rain vs bicycle -->\n      <line x1=\"470\" y1=\"65\" x2=\"470\" y2=\"165\" stroke=\"#0284c7\" stroke-width=\"2.5\"/>\n      <polygon points=\"470,165 466,152 474,152\" fill=\"#0284c7\"/>\n      <text x=\"425\" y=\"115\" font-size=\"10\" font-weight=\"bold\" fill=\"#0284c7\">v_rain (-30j)</text>\n\n      <line x1=\"470\" y1=\"165\" x2=\"570\" y2=\"165\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n      <polygon points=\"570,165 558,161 558,169\" fill=\"#dc2626\"/>\n      <text x=\"495\" y=\"180\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\">-v_bike (+10i)</text>\n\n      <line x1=\"470\" y1=\"65\" x2=\"570\" y2=\"165\" stroke=\"#7c3aed\" stroke-width=\"3\"/>\n      <polygon points=\"570,165 565,152 555,160\" fill=\"#7c3aed\"/>\n      <text x=\"535\" y=\"105\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#7c3aed\">v_rel</text>\n\n      <rect x=\"585\" y=\"65\" width=\"165\" height=\"115\" rx=\"6\" fill=\"#f5f3ff\" stroke=\"#ddd6fe\"/>\n      <text x=\"595\" y=\"85\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#5b21b6\">Relative Motion Formula:</text>\n      <text x=\"595\" y=\"105\" font-size=\"9\" fill=\"#334155\">&bull; v_rel = v_r - v_b</text>\n      <text x=\"595\" y=\"125\" font-size=\"9\" fill=\"#334155\">&bull; tan &theta; = |v_b| / |v_r|</text>\n      <text x=\"595\" y=\"145\" font-size=\"9\" font-weight=\"bold\" fill=\"#047857\">&bull; &theta; = 18.4&deg; with vertical</text>\n      <text x=\"595\" y=\"165\" font-size=\"9\" fill=\"#475569\">&bull; Umbrella tilted South</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 3.1 to 3.25: Scalar &amp; Vector Algebra, Relative Velocity in 2D, Projectile Motion &amp; Uniform Circular Motion</div>\n\n  <!-- c11p-ch3-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q1')\">\n      <div class=\"q-num\">Question 3.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State, for each of the following physical quantities, if it is a scalar or a vector:<br>volume, mass, speed, acceleration, density, number of moles, velocity, angular frequency, displacement, angular velocity.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Classification based on directional dependence and vector addition laws:</b><br><br>\n    • <b>Scalar Quantities:</b> (Possess magnitude only, no directional dependence)<br>\n      1. <b>Volume:</b> Magnitude only (SI unit: $\\text{m}^3$).<br>\n      2. <b>Mass:</b> Fundamental scalar (SI unit: $\\text{kg}$).<br>\n      3. <b>Speed:</b> Magnitude of velocity, scalar (SI unit: $\\text{m s}^{-1}$).<br>\n      4. <b>Density:</b> Ratio of mass to volume, scalar (SI unit: $\\text{kg m}^{-3}$).<br>\n      5. <b>Number of moles:</b> Amount of substance, scalar (SI unit: $\\text{mol}$).<br>\n      6. <b>Angular frequency ($\\omega$):</b> Scalar rate of phase change (SI unit: $\\text{rad s}^{-1}$).<br><br>\n    • <b>Vector Quantities:</b> (Possess magnitude, specified direction, and obey vector addition)<br>\n      1. <b>Acceleration:</b> Rate of change of velocity, directed quantity (SI unit: $\\text{m s}^{-2}$).<br>\n      2. <b>Velocity:</b> Rate of displacement, directed quantity (SI unit: $\\text{m s}^{-1}$).<br>\n      3. <b>Displacement:</b> Directed straight line from initial to final point (SI unit: $\\text{m}$).<br>\n      4. <b>Angular velocity ($\\vec{\\omega}$):</b> Axial vector directed along axis of rotation by right-hand rule (SI unit: $\\text{rad s}^{-1}$).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Criteria for scalar (magnitude only) and vector (magnitude + direction + vector addition)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of 6 scalar quantities</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of 4 vector quantities</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q2')\">\n      <div class=\"q-num\">Question 3.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Pick out the two scalar quantities in the following list:<br>force, angular momentum, work, current, linear momentum, electric field, average velocity, magnetic moment, relative velocity.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Analysis of Each Quantity:</b><br>\n    • <b>Work:</b> Scalar product of force and displacement vectors ($W = \\vec{F} \\cdot \\vec{s}$). Possesses magnitude and unit (Joule), but no directional vector orientation. <b>(Scalar)</b><br>\n    • <b>Current (electric current):</b> Although current has a direction along a wire, it does not obey vector addition laws (Kirchhoff's current law is simple algebraic addition, independent of spatial orientation of wires). Hence, it is treated as a <b>scalar</b> (or tensor of rank 0). <b>(Scalar)</b><br><br>\n    • Force, angular momentum, linear momentum, electric field, average velocity, magnetic moment, and relative velocity are all vectors.<br><br>\n    $$\\mathbf{\\text{The two scalar quantities are: Work and Current.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Work as dot product scalar</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Current as scalar due to non-adherence to vector triangle addition</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q3')\">\n      <div class=\"q-num\">Question 3.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Pick out the only vector quantity in the following list:<br>temperature, pressure, impulse, time, power, total path length, energy, gravitational potential, coefficient of friction, charge.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Detailed Examination:</b><br>\n    • <i>Temperature, time, power, total path length, energy, gravitational potential, coefficient of friction, charge:</i> All are scalars.<br>\n    • <i>Pressure:</i> Hydrostatic pressure acts equally in all directions at a point ($P = dF_{\\perp}/dA$), making it a scalar.<br>\n    • <b>Impulse ($\\vec{J}$):</b> Impulse is defined as the product of average force and the time interval during which it acts: $\\vec{J} = \\vec{F}_{avg} \\Delta t = \\Delta \\vec{p}$. It is equal to the change in linear momentum, which has both magnitude and a definite spatial direction (identical to the direction of force).<br><br>\n    $$\\mathbf{\\text{The only vector quantity is: Impulse.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Impulse as the vector quantity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification via impulse-momentum relation $\\vec{J} = \\vec{F}\\Delta t = \\Delta\\vec{p}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q4')\">\n      <div class=\"q-num\">Question 3.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State with reasons, whether the following algebraic operations with scalar and vector quantities are permissible:<br>(a) adding any two scalars,<br>(b) adding a scalar to a vector of the same dimensions,<br>(c) multiplying any vector by any scalar,<br>(d) multiplying any two scalars,<br>(e) adding any two vectors,<br>(f) adding a component of a vector to the same vector.\n      </div>\n      <div class=\"q-marks\">[6 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Adding any two scalars:</b> <b>Not permissible in general.</b> Two scalars can be added only if they represent the same physical quantity and have identical physical dimensions (e.g., adding mass to temperature is physically meaningless).<br><br>\n    • <b>(b) Adding a scalar to a vector of the same dimensions:</b> <b>Not permissible.</b> A scalar has no direction, whereas a vector has a specific direction. Addition of a scalar and a vector is mathematically undefined, even if their dimensions are the same.<br><br>\n    • <b>(c) Multiplying any vector by any scalar:</b> <b>Permissible.</b> Multiplying a vector $\\vec{A}$ by a scalar $k$ yields a new vector $k\\vec{A}$ with magnitude scaled by $|k|$ and units being the product of their units (e.g., $\\vec{F} = m\\vec{a}$, or $\\vec{p} = m\\vec{v}$).<br><br>\n    • <b>(d) Multiplying any two scalars:</b> <b>Permissible.</b> Any two scalars can be multiplied regardless of their physical dimensions (e.g., $\\text{Mass} \\times \\text{Specific Heat} \\times \\Delta T = Q$, or $\\text{Power} \\times \\text{time} = \\text{Energy}$).<br><br>\n    • <b>(e) Adding any two vectors:</b> <b>Not permissible in general.</b> Two vectors can be added if and only if they represent the same physical quantity and possess identical dimensions (e.g., a velocity vector cannot be added to an electric field vector).<br><br>\n    • <b>(f) Adding a component of a vector to the same vector:</b> <b>Not permissible.</b> A component of a vector along a direction is a scalar (its projection $A_x = A \\cos \\theta$). Adding a scalar component directly to the vector itself is undefined. (If the component is taken as a component vector $A_x \\hat{i}$, they have identical dimensions, but adding them produces a new vector $\\vec{A} + A_x\\hat{i}$, which does not represent the original vector).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Not permissible: Must have identical physical dimensions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Not permissible: Scalar cannot be added to vector</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Permissible: Scalar multiplication scales vector magnitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Permissible: Multiplication of scalars is universally valid</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Not permissible: Vectors must represent identical physical quantities</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(f) Not permissible: Scalar component cannot be added to vector</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q5')\">\n      <div class=\"q-num\">Question 3.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Read each statement below carefully and state with reasons, if it is true or false:<br>(a) The magnitude of a vector is always a scalar,<br>(b) each component of a vector is always a scalar,<br>(c) the total path length is always equal to the magnitude of the displacement vector of a particle.<br>(d) the average speed of a particle (defined as total path length divided by the time taken to cover the path) is either greater or equal to the magnitude of average velocity of the particle over the same interval of time,<br>(e) Three vectors not lying in a plane can never add up to give a null vector.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) True:</b> The magnitude of a vector represents its size/length, which is a pure non-negative real number associated with a physical unit. It has no directional properties; hence, it is always a scalar.<br><br>\n    • <b>(b) False:</b> A component of a vector can be treated either as a scalar component ($A_x = A \\cos \\theta$, which can be positive or negative) or as a component vector ($A_x \\hat{i}$, which is a vector). In standard vector terminology, component vectors have directional unit vectors attached; hence, saying it is <i>always</i> a scalar is not universally true.<br><br>\n    • <b>(c) False:</b> Total path length is the actual trajectory length. It equals the magnitude of displacement if and only if the particle moves along a straight line in a fixed direction without reversing. In all other cases (e.g., curved paths, back-and-forth motion), $\\text{Total path length} > |\\text{Displacement}|$.<br><br>\n    • <b>(d) True:</b> Since $\\text{Total path length} \\ge |\\text{Displacement}|$, dividing both sides by the positive time interval $\\Delta t$ gives $\\text{Average speed} \\ge |\\text{Average velocity}|$.<br><br>\n    • <b>(e) True:</b> For the resultant of three non-zero vectors to be zero ($\\vec{a} + \\vec{b} + \\vec{c} = \\mathbf{0}$), the third vector must be equal and opposite to the resultant of the first two ($\\vec{c} = -(\\vec{a} + \\vec{b})$). But the resultant of any two vectors $(\\vec{a} + \\vec{b})$ always lies in the plane containing $\\vec{a}$ and $\\vec{b}$. If the three vectors are non-coplanar, $\\vec{c}$ cannot lie in the plane of $\\vec{a}$ and $\\vec{b}$ and therefore can never cancel their resultant.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) True with definition of scalar magnitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False: component vectors carry unit vectors</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) False: path length $\\ge$ displacement magnitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) True: consequence of path length $\\ge$ displacement</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) True: two vectors define a plane; third non-coplanar vector cannot cancel their sum</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q6')\">\n      <div class=\"q-num\">Question 3.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Establish the following vector inequalities geometrically or otherwise:<br>(a) $|\\vec{a} + \\vec{b}| \\le |\\vec{a}| + |\\vec{b}|$<br>(b) $|\\vec{a} + \\vec{b}| \\ge ||\\vec{a}| - |\\vec{b}||$<br>(c) $|\\vec{a} - \\vec{b}| \\le |\\vec{a}| + |\\vec{b}|$<br>(d) $|\\vec{a} - \\vec{b}| \\ge ||\\vec{a}| - |\\vec{b}||$<br>When does the equality sign apply?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Consider triangle $OPQ$ formed by vectors $\\vec{OP} = \\vec{a}$, $\\vec{PQ} = \\vec{b}$, and resultant $\\vec{OQ} = \\vec{a} + \\vec{b}$.<br><br>\n    • <b>(a) Triangle Inequality:</b> In any triangle, the length of any side is strictly less than the sum of the lengths of the other two sides: $OQ \\le OP + PQ$.<br>\n      $$|\\vec{a} + \\vec{b}| \\le |\\vec{a}| + |\\vec{b}|$$<br>\n      <i>Equality holds:</i> When $\\vec{a}$ and $\\vec{b}$ are collinear and in the <b>same direction</b> ($\\theta = 0^\\circ$).<br><br>\n    • <b>(b) Difference Inequality:</b> In triangle $OPQ$, the length of any side is greater than or equal to the difference of the other two sides: $OQ \\ge |OP - PQ|$.<br>\n      $$|\\vec{a} + \\vec{b}| \\ge ||\\vec{a}| - |\\vec{b}||$$<br>\n      <i>Equality holds:</i> When $\\vec{a}$ and $\\vec{b}$ are collinear and in <b>opposite directions</b> ($\\theta = 180^\\circ$).<br><br>\n    • <b>(c) Replacing $\\vec{b}$ with $-\\vec{b}$ in (a):</b><br>\n      $$|\\vec{a} + (-\\vec{b})| \\le |\\vec{a}| + |-\\vec{b}| \\implies |\\vec{a} - \\vec{b}| \\le |\\vec{a}| + |\\vec{b}|$$<br>\n      <i>Equality holds:</i> When $\\vec{a}$ and $-\\vec{b}$ are in the same direction, i.e., $\\vec{a}$ and $\\vec{b}$ are in <b>opposite directions</b> ($\\theta = 180^\\circ$).<br><br>\n    • <b>(d) Replacing $\\vec{b}$ with $-\\vec{b}$ in (b):</b><br>\n      $$|\\vec{a} - \\vec{b}| \\ge ||\\vec{a}| - |-\\vec{b}|| \\implies |\\vec{a} - \\vec{b}| \\ge ||\\vec{a}| - |\\vec{b}||$$<br>\n      <i>Equality holds:</i> When $\\vec{a}$ and $\\vec{b}$ are in the <b>same direction</b> ($\\theta = 0^\\circ$).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Triangle inequality proof and $\\theta = 0^\\circ$ equality condition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Side difference property proof and $\\theta = 180^\\circ$ equality condition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Substitution of $-\\vec{b}$ into sum inequality with $\\theta = 180^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Substitution of $-\\vec{b}$ into difference inequality with $\\theta = 0^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q7')\">\n      <div class=\"q-num\">Question 3.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Given $\\vec{a} + \\vec{b} + \\vec{c} + \\vec{d} = \\mathbf{0}$, which of the following statements are correct:<br>(a) $\\vec{a}, \\vec{b}, \\vec{c}$, and $\\vec{d}$ must each be a null vector,<br>(b) The magnitude of $(\\vec{a} + \\vec{c})$ equals the magnitude of $(\\vec{b} + \\vec{d})$,<br>(c) The magnitude of $\\vec{a}$ can never be greater than the sum of the magnitudes of $\\vec{b}, \\vec{c}$, and $\\vec{d}$,<br>(d) $\\vec{b} + \\vec{c}$ must lie in the plane of $\\vec{a}$ and $\\vec{d}$ if $\\vec{a}$ and $\\vec{d}$ are not collinear, and in the line of $\\vec{a}$ and $\\vec{d}$ if they are collinear?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Incorrect:</b> The sum of four non-zero vectors can easily be zero if they form the closed sides of a polygon taken in order. They do not each have to be null vectors.<br><br>\n    • <b>(b) Correct:</b> Rearranging $\\vec{a} + \\vec{b} + \\vec{c} + \\vec{d} = \\mathbf{0}$:<br>\n      $$\\vec{a} + \\vec{c} = -(\\vec{b} + \\vec{d})$$<br>\n      Taking magnitude on both sides:<br>\n      $$|\\vec{a} + \\vec{c}| = |-(\\vec{b} + \\vec{d})| = |\\vec{b} + \\vec{d}|$$<br><br>\n    • <b>(c) Correct:</b> Rearranging for $\\vec{a}$:<br>\n      $$\\vec{a} = -(\\vec{b} + \\vec{c} + \\vec{d})$$<br>\n      Taking magnitude and using generalized triangle inequality:<br>\n      $$|\\vec{a}| = |-(\\vec{b} + \\vec{c} + \\vec{d})| = |\\vec{b} + \\vec{c} + \\vec{d}| \\le |\\vec{b}| + |\\vec{c}| + |\\vec{d}|$$<br>\n      Thus, the magnitude of $\\vec{a}$ can never exceed the sum of the magnitudes of the other three vectors.<br><br>\n    • <b>(d) Correct:</b> From $\\vec{a} + (\\vec{b} + \\vec{c}) + \\vec{d} = \\mathbf{0}$, we have:<br>\n      $$\\vec{b} + \\vec{c} = -(\\vec{a} + \\vec{d})$$<br>\n      The vector $(\\vec{a} + \\vec{d})$ lies in the plane defined by $\\vec{a}$ and $\\vec{d}$. Therefore, $-(\\vec{a} + \\vec{d})$, which is $(\\vec{b} + \\vec{c})$, must also lie in the plane of $\\vec{a}$ and $\\vec{d}$. If $\\vec{a}$ and $\\vec{d}$ are collinear, $(\\vec{a} + \\vec{d})$ lies along their common line, so $(\\vec{b} + \\vec{c})$ also lies along that same line.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Incorrect with closed polygon counterexample</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Correct via $|\\vec{a} + \\vec{c}| = |-(\\vec{b} + \\vec{d})|$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Correct via triangle inequality on $|\\vec{b} + \\vec{c} + \\vec{d}|$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Correct via coplanarity of $\\vec{a} + \\vec{d}$ and its opposite</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q8')\">\n      <div class=\"q-num\">Question 3.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Three girls skating on a circular ice ground of radius $200\\text{ m}$ start from a point P on the edge of the ground and reach a point Q diametrically opposite to P following different paths as shown in Fig. 3.20. What is the magnitude of the displacement vector for each? For which girl is this equal to the actual path length skated?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Displacement Vector Magnitude:</b><br>\n    • The displacement vector $\\Delta\\vec{r} = \\vec{r}_Q - \\vec{r}_P$ depends only on the initial point $P$ and final point $Q$, regardless of the actual path taken.<br>\n    • Since $Q$ is diametrically opposite to $P$ on a circular track of radius $R = 200\\text{ m}$, the straight line distance $PQ$ is the diameter of the circle:<br>\n      $$\\text{Displacement Magnitude} = 2R = 2 \\times 200\\text{ m} = \\mathbf{400\\text{ m}}$$<br>\n    • Therefore, the magnitude of the displacement vector is $\\mathbf{400\\text{ m}}$ for <b>all three girls (A, B, and C)</b>.<br><br>\n    <b>2. Equality with Actual Path Length:</b><br>\n    • Girl B skates directly along the straight diameter path from $P$ to $Q$.<br>\n    • Her path length = $PQ = 400\\text{ m}$, which is strictly equal to the magnitude of her displacement vector.<br>\n    • Girls A and C skate along curved paths; their path lengths exceed $400\\text{ m}$.<br>\n    $$\\mathbf{\\text{Displacement magnitude equals the actual path length only for Girl B.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of displacement as straight line independent of path</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of displacement magnitude $2R = 400\\text{ m}$ for all three girls</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Girl B moving along the straight diameter</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q9')\">\n      <div class=\"q-num\">Question 3.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A cyclist starts from the centre O of a circular park of radius $1\\text{ km}$, reaches the edge P of the park, then cycles along the circumference and reaches the point Q via the shortest arc, and returns to the centre along QO as shown in Fig. 3.21. If the round trip takes $10\\text{ min}$, what is the (a) net displacement, (b) average velocity, and (c) average speed of the cyclist?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Radius $R = 1\\text{ km}$. Round trip path: $O \\to P \\to Q \\to O$. Arc $PQ$ subtends $90^\\circ$ (quarter circle).<br>\n    Time taken $t = 10\\text{ min} = \\frac{10}{60}\\text{ h} = \\frac{1}{6}\\text{ h}$.<br><br>\n    • <b>(a) Net Displacement:</b><br>\n      The cyclist starts at $O$ and finally returns to $O$. Initial and final positions coincide.<br>\n      $$\\mathbf{\\text{Net displacement} = 0}$$<br>\n    • <b>(b) Average Velocity:</b><br>\n      $$\\text{Average velocity} = \\frac{\\text{Net displacement}}{\\text{Total time}} = \\frac{0}{1/6\\text{ h}} = \\mathbf{0\\text{ km h}^{-1}}$$<br>\n    • <b>(c) Average Speed:</b><br>\n      $$\\text{Total distance} = OP + \\text{Arc } PQ + QO = R + \\frac{1}{4}(2\\pi R) + R = 2R + \\frac{\\pi R}{2}$$<br>\n      $$= 2(1) + \\frac{3.1416 \\times 1}{2} = 2 + 1.5708 = 3.5708\\text{ km}$$<br>\n      $$\\text{Average speed} = \\frac{\\text{Total distance}}{\\text{Total time}} = \\frac{3.5708\\text{ km}}{1/6\\text{ h}} = 3.5708 \\times 6 = \\mathbf{21.43\\text{ km h}^{-1}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Zero net displacement since initial and final points coincide</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Zero average velocity derived from zero displacement</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Correct total distance: $2 + \\pi/2 = 3.57\\text{ km}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Average speed calculation: $21.43\\text{ km/h}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q10')\">\n      <div class=\"q-num\">Question 3.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        On an open ground, a motorist follows a track that turns to his left by an angle of $60^\\circ$ after every $500\\text{ m}$. Starting from a given turn, specify the displacement of the motorist at the third, sixth and eighth turn. Compare the magnitude of the displacement with the total path length covered by the motorist in each case.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Geometrical Track:</b> Each turn is $60^\\circ$ to the left after $500\\text{ m}$. Since an interior polygon turn of $60^\\circ$ exterior angle satisfies $6 \\times 60^\\circ = 360^\\circ$, the path forms a regular hexagon of side length $a = 500\\text{ m}$.<br>\n    Let the vertices of the hexagon be $A, B, C, D, E, F$, starting from vertex $A$.<br><br>\n    • <b>1. At the Third Turn (Vertex D):</b><br>\n      - Path covered: $A \\to B \\to C \\to D$. Path length $= 3 \\times 500\\text{ m} = \\mathbf{1500\\text{ m} = 1.5\\text{ km}}$.<br>\n      - Displacement $\\vec{AD}$ is the main diameter of the regular hexagon:<br>\n        $$|\\text{Displacement}| = 2a = 2 \\times 500\\text{ m} = \\mathbf{1000\\text{ m} = 1.0\\text{ km}}$$<br>\n      - Ratio: $\\frac{\\text{Displacement}}{\\text{Path Length}} = \\frac{1000}{1500} = \\frac{2}{3} = \\mathbf{0.67}$.<br><br>\n    • <b>2. At the Sixth Turn (Vertex A):</b><br>\n      - Path covered: Complete loop back to start $A$. Path length $= 6 \\times 500\\text{ m} = \\mathbf{3000\\text{ m} = 3.0\\text{ km}}$.<br>\n      - Displacement = $\\mathbf{0}$.<br>\n      - Ratio: $\\frac{\\text{Displacement}}{\\text{Path Length}} = \\mathbf{0}$.<br><br>\n    • <b>3. At the Eighth Turn (Vertex C):</b><br>\n      - Path covered: 1 full hexagon ($3000\\text{ m}$) + 2 additional sides ($A \\to B \\to C$).<br>\n      - Path length $= 8 \\times 500\\text{ m} = \\mathbf{4000\\text{ m} = 4.0\\text{ km}}$.<br>\n      - Displacement is the chord $AC$ of the regular hexagon:<br>\n        $$|\\vec{AC}| = 2a \\cos 30^\\circ = 2 \\times 500 \\times \\frac{\\sqrt{3}}{2} = 500\\sqrt{3} \\approx \\mathbf{866\\text{ m} = 0.866\\text{ km}}$$<br>\n        Direction is at $30^\\circ$ to the initial direction $AB$.<br>\n      - Ratio: $\\frac{\\text{Displacement}}{\\text{Path Length}} = \\frac{500\\sqrt{3}}{4000} = \\frac{\\sqrt{3}}{8} \\approx \\mathbf{0.2165}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of path as regular hexagon of side $500\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3rd turn: Path $1500\\text{ m}$, displacement $1000\\text{ m}$, ratio $2/3$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">6th turn: Path $3000\\text{ m}$, displacement $0$, ratio $0$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">8th turn: Path $4000\\text{ m}$, displacement $500\\sqrt{3} = 866\\text{ m}$, ratio $0.217$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q11')\">\n      <div class=\"q-num\">Question 3.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A passenger arriving in a new town wishes to go from the station to a hotel located $10\\text{ km}$ away on a straight road from the station. A dishonest cabman takes him along a circuitous path $23\\text{ km}$ long and reaches the hotel in $28\\text{ min}$. What is (a) the average speed of the taxi, (b) the magnitude of average velocity? Are the two equal?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Straight-line distance (displacement magnitude) $|\\Delta\\vec{r}| = 10\\text{ km}$.<br>\n    Path length travelled = $23\\text{ km}$.<br>\n    Time taken $\\Delta t = 28\\text{ min} = \\frac{28}{60}\\text{ h} = \\frac{7}{15}\\text{ h}$.<br><br>\n    • <b>(a) Average Speed:</b><br>\n      $$v_{avg} = \\frac{\\text{Total path length}}{\\Delta t} = \\frac{23\\text{ km}}{\\frac{7}{15}\\text{ h}} = \\frac{23 \\times 15}{7} = \\frac{345}{7} \\approx \\mathbf{49.29\\text{ km h}^{-1}}$$<br><br>\n    • <b>(b) Magnitude of Average Velocity:</b><br>\n      $$|\\bar{v}| = \\frac{\\text{Magnitude of displacement}}{\\Delta t} = \\frac{10\\text{ km}}{\\frac{7}{15}\\text{ h}} = \\frac{150}{7} \\approx \\mathbf{21.43\\text{ km h}^{-1}}$$<br><br>\n    • <b>Comparison:</b><br>\n      The two values are <b>not equal</b> ($v_{avg} \\ne |\\bar{v}|$) because the taxi travelled along a circuitous curved route rather than along the straight shortest line.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Average speed calculation: $345/7 = 49.29\\text{ km/h}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Average velocity calculation: $150/7 = 21.43\\text{ km/h}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inequality justification due to curved trajectory</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q12')\">\n      <div class=\"q-num\">Question 3.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Rain is falling vertically with a speed of $30\\text{ m s}^{-1}$. A woman rides a bicycle with a speed of $10\\text{ m s}^{-1}$ in the north to south direction. What is the direction in which she should hold her umbrella?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let unit vector $\\hat{j}$ be vertically upward and $\\hat{i}$ be towards North (so South is $-\\hat{i}$).<br><br>\n    • Velocity of rain relative to ground: $\\vec{v}_r = -30\\hat{j}\\text{ m s}^{-1}$ (falling vertically down).<br>\n    • Velocity of bicycle relative to ground: $\\vec{v}_b = -10\\hat{i}\\text{ m s}^{-1}$ (towards South).<br><br>\n    <b>Relative velocity of rain with respect to woman ($\\vec{v}_{rb}$):</b><br>\n    $$\\vec{v}_{rb} = \\vec{v}_r - \\vec{v}_b = -30\\hat{j} - (-10\\hat{i}) = 10\\hat{i} - 30\\hat{j}\\text{ m s}^{-1}$$<br><br>\n    <b>Direction:</b><br>\n    Let $\\theta$ be the angle that the relative velocity makes with the <i>vertical</i>:<br>\n    $$\\tan \\theta = \\frac{|v_x|}{|v_y|} = \\frac{10}{30} = \\frac{1}{3} \\approx 0.3333$$<br>\n    $$\\theta = \\arctan(0.3333) \\approx \\mathbf{18.43^\\circ} \\approx \\mathbf{18^\\circ 26'}$$<br><br>\n    To protect herself from the oncoming rain, she must hold her umbrella <b>opposite</b> to the direction of relative rain velocity:<br>\n    $$\\mathbf{\\text{She should hold her umbrella at an angle of } 18.4^\\circ \\text{ with the vertical, tilted towards the South.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Vector formulation: $\\vec{v}_{rb} = \\vec{v}_r - \\vec{v}_b$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Angle determination: $\\tan\\theta = 10/30 = 1/3 \\implies \\theta = 18.4^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical direction: tilted at $18.4^\\circ$ towards South</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q13')\">\n      <div class=\"q-num\">Question 3.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A man can swim with a speed of $4.0\\text{ km h}^{-1}$ in still water. How long does he take to cross a river $1.0\\text{ km}$ wide if the river flows steadily at $3.0\\text{ km h}^{-1}$ and he makes his strokes normal to the river current? How far down the river does he go when he reaches the other bank?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Speed of swimmer in still water (relative to water): $v_s = 4.0\\text{ km h}^{-1}$ (directed across, perpendicular to flow).<br>\n    • Speed of river current: $v_r = 3.0\\text{ km h}^{-1}$ (directed downstream).<br>\n    • River width $d = 1.0\\text{ km}$.<br><br>\n    <b>1. Time Taken to Cross River ($t$):</b><br>\n    The component of velocity responsible for crossing the river is solely the perpendicular component $v_s = 4.0\\text{ km h}^{-1}$:<br>\n    $$t = \\frac{d}{v_s} = \\frac{1.0\\text{ km}}{4.0\\text{ km h}^{-1}} = 0.25\\text{ h} = 0.25 \\times 60\\text{ min} = \\mathbf{15\\text{ minutes}}$$<br><br>\n    <b>2. Drift Down the River ($x$):</b><br>\n    During this time, the river current carries him downstream:<br>\n    $$x = v_r \\times t = 3.0\\text{ km h}^{-1} \\times 0.25\\text{ h} = 0.75\\text{ km} = \\mathbf{750\\text{ m}}$$<br><br>\n    $$\\therefore \\text{Time taken } = \\mathbf{15\\text{ minutes}}, \\quad \\text{Drift downstream } = \\mathbf{750\\text{ m}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Crossing time formula $t = d/v_s$ yielding $0.25\\text{ h} = 15\\text{ min}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Drift calculation $x = v_r t = 0.75\\text{ km} = 750\\text{ m}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q14')\">\n      <div class=\"q-num\">Question 3.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        In a harbour, wind is blowing at the speed of $72\\text{ km h}^{-1}$ and the flag on the mast of a boat anchored in the harbour flutters along the N-E direction. If the boat starts moving at a speed of $51\\text{ km h}^{-1}$ to the north, what is the direction of the flag on the mast of the boat?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • When the boat is anchored, the flag flutters along the direction of the wind relative to the boat. Thus, wind velocity with respect to ground is $\\vec{v}_w$ directed along North-East ($45^\\circ$ East of North):<br>\n      $$|\\vec{v}_w| = 72\\text{ km h}^{-1}$$<br>\n      $$\\vec{v}_w = 72 \\cos 45^\\circ \\hat{i} + 72 \\sin 45^\\circ \\hat{j} = \\frac{72}{\\sqrt{2}}\\hat{i} + \\frac{72}{\\sqrt{2}}\\hat{j} \\approx 50.91\\hat{i} + 50.91\\hat{j}$$<br><br>\n    • When the boat moves North at $51\\text{ km h}^{-1}$:<br>\n      $$\\vec{v}_b = 51\\hat{j}\\text{ km h}^{-1}$$<br><br>\n    • <b>Relative velocity of wind with respect to moving boat ($\\vec{v}_{wb}$):</b><br>\n      $$\\vec{v}_{wb} = \\vec{v}_w - \\vec{v}_b = 50.91\\hat{i} + (50.91 - 51)\\hat{j} = 50.91\\hat{i} - 0.09\\hat{j}$$<br><br>\n    • <b>Direction of Flag:</b><br>\n      The $x$-component is positive ($50.91$ towards East) and the $y$-component is virtually zero ($-0.09$, extremely small towards South):<br>\n      $$\\tan \\beta = \\frac{-0.09}{50.91} \\approx -0.00177 \\implies \\beta \\approx 0^\\circ$$<br>\n      $$\\mathbf{\\text{The flag will flutter almost due East (strictly } 0.1^\\circ \\text{ South of East).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Resolution of wind vector into components along N and E</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Relative wind vector $\\vec{v}_{wb} = \\vec{v}_w - \\vec{v}_b$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final orientation deduced as almost exactly due East</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q15')\">\n      <div class=\"q-num\">Question 3.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The ceiling of a long hall is $25\\text{ m}$ high. What is the maximum horizontal distance that a ball thrown with a speed of $40\\text{ m s}^{-1}$ can go without hitting the ceiling of the hall?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Max permissible vertical height $H = 25\\text{ m}$, Initial launch speed $u = 40\\text{ m s}^{-1}$, $g = 9.8\\text{ m s}^{-2}$.<br><br>\n    <b>1. Determining Launch Angle ($\\theta$):</b><br>\n    The maximum height for a projectile launched at angle $\\theta$ is:<br>\n    $$H = \\frac{u^2 \\sin^2 \\theta}{2g}$$<br>\n    $$25 = \\frac{(40)^2 \\sin^2 \\theta}{2 \\times 9.8} = \\frac{1600 \\sin^2 \\theta}{19.6}$$<br>\n    $$\\sin^2 \\theta = \\frac{25 \\times 19.6}{1600} = \\frac{490}{1600} = 0.30625$$<br>\n    $$\\sin \\theta = \\sqrt{0.30625} \\approx 0.5534 \\implies \\theta \\approx 33.6^\\circ$$<br>\n    $$\\cos^2 \\theta = 1 - \\sin^2 \\theta = 1 - 0.30625 = 0.69375 \\implies \\cos \\theta = \\sqrt{0.69375} \\approx 0.8329$$<br><br>\n    <b>2. Calculating Horizontal Range ($R$):</b><br>\n    $$R = \\frac{u^2 \\sin 2\\theta}{g} = \\frac{2 u^2 \\sin \\theta \\cos \\theta}{g}$$<br>\n    $$R = \\frac{2 \\times 1600 \\times 0.5534 \\times 0.8329}{9.8} = \\frac{2950.45}{9.8} \\approx \\mathbf{150.5\\text{ m}}$$<br><br>\n    $$\\therefore \\text{The maximum horizontal distance without hitting the ceiling is } \\mathbf{150.5\\text{ m}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formula for maximum projectile height $H = \\frac{u^2\\sin^2\\theta}{2g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for $\\sin^2\\theta = 0.30625$ and angle $\\theta = 33.6^\\circ$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Horizontal range formula $R = \\frac{2u^2\\sin\\theta\\cos\\theta}{g}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer: $R = 150.5\\text{ m}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q16')\">\n      <div class=\"q-num\">Question 3.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A cricketer can throw a ball to a maximum horizontal distance of $100\\text{ m}$. How much high above the ground can the cricketer throw the same ball?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Maximum Horizontal Range ($R_{max}$):</b><br>\n    The range is maximum when the launch angle $\\theta = 45^\\circ$ (so $\\sin 2\\theta = \\sin 90^\\circ = 1$):<br>\n    $$R_{max} = \\frac{u^2}{g} = 100\\text{ m} \\implies u^2 = 100 g$$<br><br>\n    <b>2. Maximum Vertical Height ($H_{max}$):</b><br>\n    To achieve maximum vertical height, the ball must be thrown straight up vertically (launch angle $\\theta = 90^\\circ$):<br>\n    $$H_{max} = \\frac{u^2}{2g}$$<br>\n    Substituting $u^2 = 100 g$:<br>\n    $$H_{max} = \\frac{100 g}{2g} = \\frac{100}{2} = \\mathbf{50\\text{ m}}$$<br><br>\n    $$\\therefore \\text{The cricketer can throw the same ball to a height of } \\mathbf{50\\text{ m}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Relation for maximum horizontal range $R_{max} = u^2/g = 100\\text{ m}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Relation for maximum vertical height $H_{max} = u^2/(2g) = R_{max}/2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer $H_{max} = 50\\text{ m}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q17')\">\n      <div class=\"q-num\">Question 3.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A stone tied to the end of a string $80\\text{ cm}$ long is whirled in a horizontal circle with a constant speed. If the stone makes $14$ revolutions in $25\\text{ s}$, what is the magnitude and direction of acceleration of the stone?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Radius $r = 80\\text{ cm} = 0.80\\text{ m}$.<br>\n    • Number of revolutions $N = 14$ in time $t = 25\\text{ s}$.<br><br>\n    <b>1. Angular Frequency ($\\omega$):</b><br>\n    Frequency $\\nu = \\frac{N}{t} = \\frac{14}{25}\\text{ rev s}^{-1}$.<br>\n    $$\\omega = 2\\pi \\nu = 2 \\times \\frac{22}{7} \\times \\frac{14}{25} = \\frac{88}{25} = 3.52\\text{ rad s}^{-1}$$<br><br>\n    <b>2. Centripetal Acceleration Magnitude ($a_c$):</b><br>\n    Since speed is constant, the only acceleration is centripetal acceleration:<br>\n    $$a_c = \\omega^2 r = (3.52)^2 \\times 0.80 = 12.3904 \\times 0.80 = \\mathbf{9.91\\text{ m s}^{-2}}$$<br><br>\n    <b>3. Direction:</b><br>\n    $$\\mathbf{\\text{The acceleration is directed radially inwards along the string towards the centre of the circle.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Angular velocity calculation $\\omega = 2\\pi\\nu = 3.52\\text{ rad/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Centripetal acceleration formula $a_c = \\omega^2 r = 9.91\\text{ m/s}^2$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direction stated as radially inwards towards center</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q18')\">\n      <div class=\"q-num\">Question 3.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An aircraft executes a horizontal loop of radius $1.00\\text{ km}$ with a steady speed of $900\\text{ km h}^{-1}$. Compare its centripetal acceleration with the acceleration due to gravity.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Radius $R = 1.00\\text{ km} = 1000\\text{ m}$.<br>\n    • Speed $v = 900\\text{ km h}^{-1} = 900 \\times \\frac{5}{18}\\text{ m s}^{-1} = 250\\text{ m s}^{-1}$.<br>\n    • Acceleration due to gravity $g = 9.8\\text{ m s}^{-2}$.<br><br>\n    <b>1. Centripetal Acceleration ($a_c$):</b><br>\n    $$a_c = \\frac{v^2}{R} = \\frac{(250)^2}{1000} = \\frac{62500}{1000} = \\mathbf{62.5\\text{ m s}^{-2}}$$<br><br>\n    <b>2. Comparison with $g$:</b><br>\n    $$\\frac{a_c}{g} = \\frac{62.5}{9.8} \\approx \\mathbf{6.38}$$<br><br>\n    $$\\therefore \\text{The centripetal acceleration is approximately } \\mathbf{6.38\\text{ times }} g.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Speed conversion to $250\\text{ m/s}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Centripetal acceleration formula $a_c = v^2/R = 62.5\\text{ m/s}^2$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison ratio $a_c / g = 6.38$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q19')\">\n      <div class=\"q-num\">Question 3.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Read each statement below carefully and state, with reasons, if it is true or false:<br>(a) The net acceleration of a particle in circular motion is always along the radius of the circle towards the centre.<br>(b) The velocity vector of a particle at a point is always along the tangent to the path of the particle at that point.<br>(c) The acceleration vector of a particle in uniform circular motion averaged over one cycle is a null vector.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) False:</b> Net acceleration is directed purely radially towards the centre <b>only in uniform circular motion</b> (where tangential acceleration $a_t = \\frac{dv}{dt} = 0$). In non-uniform circular motion, there is also a tangential acceleration $a_t$, and net acceleration $\\vec{a} = \\vec{a}_c + \\vec{a}_t$ is inclined at an angle to the radius.<br><br>\n    • <b>(b) True:</b> By definition, instantaneous velocity is $\\vec{v} = \\lim_{\\Delta t \\to 0} \\frac{\\Delta \\vec{r}}{\\Delta t}$. The direction of the displacement chord $\\Delta \\vec{r}$ approaches the geometrical tangent to the trajectory curve as $\\Delta t \\to 0$.<br><br>\n    • <b>(c) True:</b> In uniform circular motion, the acceleration vector $\\vec{a}_c = -\\omega^2 R(\\cos \\omega t \\hat{i} + \\sin \\omega t \\hat{j})$ has constant magnitude but continuously changing direction. Over one complete period $T$, for every instant with inward acceleration in one direction, there exists an instant $T/2$ later with an equal and opposite acceleration vector. The integral $\\frac{1}{T}\\int_0^T \\vec{a}(t) dt = \\mathbf{0}$.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) False with non-uniform circular motion counterexample ($a_t \\ne 0$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) True via definition of instantaneous velocity tangent to curve</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True: radial symmetry over complete cycle yields zero average vector</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q20')\">\n      <div class=\"q-num\">Question 3.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The position of a particle is given by $\\vec{r} = 3.0t\\hat{i} - 2.0t^2\\hat{j} + 4.0\\hat{k}\\text{ m}$, where $t$ is in seconds and the coefficients have the proper units for $\\vec{r}$ to be in metres.<br>(a) Find $\\vec{v}$ and $\\vec{a}$ of the particle.<br>(b) What is the magnitude and direction of velocity $\\vec{v}(t)$ at $t = 2.0\\text{ s}$?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Finding $\\vec{v}(t)$ and $\\vec{a}(t)$ by differentiation:</b><br>\n      $$\\vec{v}(t) = \\frac{d\\vec{r}}{dt} = \\frac{d}{dt}\\left(3.0t\\hat{i} - 2.0t^2\\hat{j} + 4.0\\hat{k}\\right) = \\mathbf{3.0\\hat{i} - 4.0t\\hat{j}\\text{ m s}^{-1}}$$<br>\n      $$\\vec{a}(t) = \\frac{d\\vec{v}}{dt} = \\frac{d}{dt}\\left(3.0\\hat{i} - 4.0t\\hat{j}\\right) = \\mathbf{-4.0\\hat{j}\\text{ m s}^{-2}}$$<br><br>\n    • <b>(b) Velocity at $t = 2.0\\text{ s}$:</b><br>\n      $$\\vec{v}(2.0) = 3.0\\hat{i} - 4.0(2.0)\\hat{j} = \\mathbf{3.0\\hat{i} - 8.0\\hat{j}\\text{ m s}^{-1}}$$<br>\n      Magnitude:<br>\n      $$|\\vec{v}| = \\sqrt{(3.0)^2 + (-8.0)^2} = \\sqrt{9 + 64} = \\sqrt{73} \\approx \\mathbf{8.54\\text{ m s}^{-1}}$$<br>\n      Direction with x-axis:<br>\n      $$\\tan \\theta = \\frac{v_y}{v_x} = \\frac{-8.0}{3.0} = -2.667 \\implies \\theta = -69.4^\\circ$$<br>\n      $$\\mathbf{\\text{Velocity has magnitude } 8.54\\text{ m s}^{-1} \\text{ at an angle of } 69.4^\\circ \\text{ below the positive x-axis.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) First derivative for $\\vec{v} = 3.0\\hat{i} - 4.0t\\hat{j}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Second derivative for $\\vec{a} = -4.0\\hat{j}\\text{ m/s}^2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Velocity magnitude at $t=2\\text{ s}$: $\\sqrt{73} = 8.54\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direction calculation: $\\theta = -69.4^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q21')\">\n      <div class=\"q-num\">Question 3.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A particle starts from the origin at $t = 0\\text{ s}$ with a velocity of $10.0\\hat{j}\\text{ m s}^{-1}$ and moves in the $x-y$ plane with a constant acceleration of $(8.0\\hat{i} + 2.0\\hat{j})\\text{ m s}^{-2}$.<br>(a) At what time is the x-coordinate of the particle $16\\text{ m}$? What is the y-coordinate of the particle at that time?<br>(b) What is the speed of the particle at that time?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $\\vec{r}_0 = \\mathbf{0}$, $\\vec{u} = 10.0\\hat{j}\\text{ m s}^{-1}$ ($u_x = 0, u_y = 10.0\\text{ m s}^{-1}$), $\\vec{a} = 8.0\\hat{i} + 2.0\\hat{j}\\text{ m s}^{-2}$ ($a_x = 8.0, a_y = 2.0\\text{ m s}^{-2}$).<br><br>\n    • <b>(a) Position components at time $t$:</b><br>\n      $$x(t) = u_x t + \\frac{1}{2}a_x t^2 = 0 + \\frac{1}{2}(8.0)t^2 = 4.0 t^2$$<br>\n      When $x = 16\\text{ m}$:<br>\n      $$4.0 t^2 = 16 \\implies t^2 = 4 \\implies \\mathbf{t = 2.0\\text{ s}}$$<br>\n      $y$-coordinate at $t = 2.0\\text{ s}$:<br>\n      $$y(t) = u_y t + \\frac{1}{2}a_y t^2 = 10.0(2.0) + \\frac{1}{2}(2.0)(2.0)^2 = 20.0 + 4.0 = \\mathbf{24.0\\text{ m}}$$<br><br>\n    • <b>(b) Speed at $t = 2.0\\text{ s}$:</b><br>\n      $$v_x = u_x + a_x t = 0 + 8.0(2.0) = 16.0\\text{ m s}^{-1}$$<br>\n      $$v_y = u_y + a_y t = 10.0 + 2.0(2.0) = 14.0\\text{ m s}^{-1}$$<br>\n      $$\\text{Speed } v = \\sqrt{v_x^2 + v_y^2} = \\sqrt{(16.0)^2 + (14.0)^2} = \\sqrt{256 + 196} = \\sqrt{452} \\approx \\mathbf{21.26\\text{ m s}^{-1}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Determination of time $t = 2.0\\text{ s}$ from $x = 4t^2 = 16$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of $y$-coordinate: $y = 24.0\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Velocity components $v_x = 16, v_y = 14$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final speed: $v = \\sqrt{452} = 21.26\\text{ m s}^{-1}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q22')\">\n      <div class=\"q-num\">Question 3.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        $\\hat{i}$ and $\\hat{j}$ are unit vectors along x- and y- axes respectively. What is the magnitude and direction of the vectors $\\hat{i} + \\hat{j}$, and $\\hat{i} - \\hat{j}$? What are the components of a vector $\\vec{A} = 2\\hat{i} + 3\\hat{j}$ along the directions of $\\hat{i} + \\hat{j}$ and $\\hat{i} - \\hat{j}$? [You may use graphical method]\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>1. Vector $\\vec{P} = \\hat{i} + \\hat{j}$:</b><br>\n    • Magnitude: $|\\vec{P}| = \\sqrt{1^2 + 1^2} = \\mathbf{\\sqrt{2}}$.<br>\n    • Direction: $\\tan \\theta_1 = \\frac{1}{1} = 1 \\implies \\mathbf{\\theta_1 = 45^\\circ}$ with positive x-axis.<br><br>\n    <b>2. Vector $\\vec{Q} = \\hat{i} - \\hat{j}$:</b><br>\n    • Magnitude: $|\\vec{Q}| = \\sqrt{1^2 + (-1)^2} = \\mathbf{\\sqrt{2}}$.<br>\n    • Direction: $\\tan \\theta_2 = \\frac{-1}{1} = -1 \\implies \\mathbf{\\theta_2 = -45^\\circ}$ (or $315^\\circ$) with positive x-axis.<br><br>\n    <b>3. Component of $\\vec{A} = 2\\hat{i} + 3\\hat{j}$ along $\\hat{i} + \\hat{j}$:</b><br>\n    Unit vector along $\\hat{i} + \\hat{j}$ is $\\hat{u}_1 = \\frac{\\hat{i} + \\hat{j}}{\\sqrt{2}}$.<br>\n    $$A_{\\parallel 1} = \\vec{A} \\cdot \\hat{u}_1 = \\frac{(2\\hat{i} + 3\\hat{j}) \\cdot (\\hat{i} + \\hat{j})}{\\sqrt{2}} = \\frac{2(1) + 3(1)}{\\sqrt{2}} = \\frac{5}{\\sqrt{2}} = \\mathbf{\\frac{5\\sqrt{2}}{2} \\approx 3.54}$$<br><br>\n    <b>4. Component of $\\vec{A} = 2\\hat{i} + 3\\hat{j}$ along $\\hat{i} - \\hat{j}$:</b><br>\n    Unit vector along $\\hat{i} - \\hat{j}$ is $\\hat{u}_2 = \\frac{\\hat{i} - \\hat{j}}{\\sqrt{2}}$.<br>\n    $$A_{\\parallel 2} = \\vec{A} \\cdot \\hat{u}_2 = \\frac{(2\\hat{i} + 3\\hat{j}) \\cdot (\\hat{i} - \\hat{j})}{\\sqrt{2}} = \\frac{2(1) + 3(-1)}{\\sqrt{2}} = \\mathbf{-\\frac{1}{\\sqrt{2}} \\approx -0.707}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Magnitudes and directions of $\\hat{i}+\\hat{j}$ and $\\hat{i}-\\hat{j}$ ($\\sqrt{2}, \\pm 45^\\circ$)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Component of $\\vec{A}$ along $\\hat{i}+\\hat{j}$ evaluated as $5/\\sqrt{2}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Component of $\\vec{A}$ along $\\hat{i}-\\hat{j}$ evaluated as $-1/\\sqrt{2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q23 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q23\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q23')\">\n      <div class=\"q-num\">Question 3.23</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        For any arbitrary motion in space, which of the following relations are true:<br>(a) $\\vec{v}_{average} = (1/2)(\\vec{v}(t_1) + \\vec{v}(t_2))$<br>(b) $\\vec{v}_{average} = \\frac{\\vec{r}(t_2) - \\vec{r}(t_1)}{t_2 - t_1}$<br>(c) $\\vec{v}(t) = \\vec{v}(0) + \\vec{a}t$<br>(d) $\\vec{r}(t) = \\vec{r}(0) + \\vec{v}(0)t + (1/2)\\vec{a}t^2$<br>(e) $\\vec{a}_{average} = \\frac{\\vec{v}(t_2) - \\vec{v}(t_1)}{t_2 - t_1}$<br>(The ‘average’ stands for average of the quantity over the time interval $t_1$ to $t_2$)\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Arbitrary Motion in Space</b> means acceleration may not be constant (acceleration $\\vec{a}(t)$ can vary arbitrarily in magnitude and direction).<br><br>\n    • <b>(a) False:</b> $\\vec{v}_{avg} = \\frac{\\vec{v}_1 + \\vec{v}_2}{2}$ is true <i>only</i> for uniformly accelerated motion (constant $\\vec{a}$). For arbitrary motion with changing acceleration, it does not hold.<br><br>\n    • <b>(b) True:</b> This is the fundamental, universal definition of average velocity vector for <i>any</i> general motion in space.<br><br>\n    • <b>(c) False:</b> $\\vec{v}(t) = \\vec{v}(0) + \\vec{a}t$ is valid <i>only</i> when acceleration is constant.<br><br>\n    • <b>(d) False:</b> $\\vec{r}(t) = \\vec{r}(0) + \\vec{v}(0)t + \\frac{1}{2}\\vec{a}t^2$ is valid <i>only</i> when acceleration is constant.<br><br>\n    • <b>(e) True:</b> This is the fundamental, universal definition of average acceleration vector for <i>any</i> general motion in space.<br><br>\n    $$\\mathbf{\\text{Correct relations for arbitrary motion are: (b) and (e).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) False: restricted to uniform acceleration only</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) True: universal definition of average velocity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) False: restricted to uniform acceleration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) False: restricted to uniform acceleration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) True: universal definition of average acceleration</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q24 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q24\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q24')\">\n      <div class=\"q-num\">Question 3.24</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Read each statement below carefully and state, with reasons and examples, if it is true or false:<br>A scalar quantity is one that<br>(a) is conserved in a process<br>(b) can never take negative values<br>(c) must be dimensionless<br>(d) does not vary from one point to another in space<br>(e) has the same value for observers with different orientations of axes.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) False:</b> Not all scalars are conserved. For example, kinetic energy in an inelastic collision is not conserved, though it is a scalar. (Only special scalars like total energy in an isolated system are conserved).<br><br>\n    • <b>(b) False:</b> Many scalar quantities can take negative values. For example, temperature ($-10^\\circ\\text{C}$), electric charge ($-e$), work done by friction ($-W$), and gravitational potential ($-GM/r$) are all negative scalars.<br><br>\n    • <b>(c) False:</b> Most physical scalars have dimensions. For example, mass $[M]$, speed $[LT^{-1}]$, density $[ML^{-3}]$ are dimensional scalars.<br><br>\n    • <b>(d) False:</b> A scalar field can vary continuously from point to point in space. For example, atmospheric temperature $T(x,y,z)$, pressure $P(x,y,z)$, and gravitational potential $V(x,y,z)$ vary spatially.<br><br>\n    • <b>(e) True:</b> By definition, a scalar is an invariant under spatial coordinate rotations (tensor of rank 0). While vector components change when coordinate axes are rotated, scalar quantities (such as mass, charge, temperature, or the dot product of two vectors) remain strictly invariant.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) False with kinetic energy non-conservation example</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False with negative temperature/charge examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) False with dimensional scalar examples (mass, speed)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) False with scalar field spatial variations (pressure, temp)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) True: invariance under coordinate frame rotation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch3-q25 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch3-q25\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch3-q25')\">\n      <div class=\"q-num\">Question 3.25</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        An aircraft is flying at a height of $3400\\text{ m}$ above the ground. If the angle subtended at a ground observation point by the aircraft positions $10.0\\text{ s}$ apart is $30^\\circ$, what is the speed of the aircraft?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Let $O$ be the observation point on the ground.<br>\n    Let $P$ and $Q$ be the aircraft positions at times $t_1$ and $t_2$ ($10.0\\text{ s}$ apart) flying horizontally at height $h = 3400\\text{ m}$.<br>\n    Let $M$ be the midpoint of $PQ$, and $OM$ be the vertical height from ground ($OM = h = 3400\\text{ m}$).<br><br>\n    • Total angle subtended $\\angle POQ = 30^\\circ$.<br>\n    • By symmetry, the vertical line $OM$ bisects the angle: $\\angle POM = \\angle QOM = 15^\\circ$.<br><br>\n    In right-angled triangle $OMP$:<br>\n    $$\\tan 15^\\circ = \\frac{PM}{OM} \\implies PM = OM \\times \\tan 15^\\circ$$<br>\n    $$\\tan 15^\\circ = 2 - \\sqrt{3} \\approx 2 - 1.73205 = 0.26795$$<br>\n    $$PM = 3400 \\times 0.26795 \\approx 911.03\\text{ m}$$<br><br>\n    Total horizontal distance flown in $10.0\\text{ s}$:<br>\n    $$PQ = 2 \\times PM = 2 \\times 911.03 = 1822.06\\text{ m}$$<br><br>\n    Speed of aircraft:<br>\n    $$v = \\frac{PQ}{\\Delta t} = \\frac{1822.06\\text{ m}}{10.0\\text{ s}} = \\mathbf{182.2\\text{ m s}^{-1}}$$<br>\n    In $\\text{km h}^{-1}$:<br>\n    $$v = 182.2 \\times \\frac{18}{5} = \\mathbf{655.9\\text{ km h}^{-1}} \\approx \\mathbf{656\\text{ km h}^{-1}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Geometrical setup with half-angle $\\angle POM = 15^\\circ$ and altitude $h = 3400\\text{ m}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Distance calculation $PM = 3400\\tan 15^\\circ = 911\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total distance $PQ = 1822\\text{ m}$ in $10\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final speed: $182.2\\text{ m s}^{-1} = 656\\text{ km h}^{-1}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer;\">← Prev: Chapter 2 (Motion in a Straight Line)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#7c3aed; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 4 (Laws of Motion) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[4] = "<section class=\"chapter-section\" id=\"c11p-ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">CBSE Class 11 Physics &bull; Chapter 4</div>\n      <h2>Laws of Motion</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 31 Verbatim Questions with Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:white; padding:20px; border-radius:12px; border:1px solid #e2e8f0; box-shadow:0 2px 8px rgba(0,0,0,0.04);\">\n    <h3 style=\"font-size:1.05rem; font-weight:800; color:#1e293b; margin-bottom:12px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.2\"><path d=\"M12 2v20\"/><path d=\"m17 5-5-3-5 3\"/><path d=\"m17 19-5 3-5-3\"/></svg>\n      Dynamics Free-Body Diagrams (FBD): Inclined Plane Equilibrium &amp; Atwood Pulley Tension\n    </h3>\n    <svg viewBox=\"0 0 780 230\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Panel 1: Inclined Plane Friction FBD -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"35\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">1. Inclined Plane Free-Body Resolution:</text>\n\n      <!-- Inclined plane wedge -->\n      <polygon points=\"45,185 240,75 240,185\" fill=\"#f1f5f9\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n      <text x=\"75\" y=\"180\" font-size=\"10\" font-weight=\"bold\" fill=\"#475569\">&theta;</text>\n\n      <!-- Block on incline -->\n      <g transform=\"translate(140, 130) rotate(-29.5)\">\n        <rect x=\"-25\" y=\"-20\" width=\"50\" height=\"30\" rx=\"4\" fill=\"#ddd6fe\" stroke=\"#7c3aed\" stroke-width=\"1.8\"/>\n        <text x=\"-6\" y=\"0\" font-size=\"9\" font-weight=\"bold\" fill=\"#5b21b6\">m</text>\n        \n        <!-- Normal force N -->\n        <line x1=\"0\" y1=\"-20\" x2=\"0\" y2=\"-60\" stroke=\"#059669\" stroke-width=\"2\"/>\n        <polygon points=\"0,-60 -4,-50 4,-50\" fill=\"#059669\"/>\n        <text x=\"6\" y=\"-45\" font-size=\"9\" font-weight=\"bold\" fill=\"#059669\">N</text>\n\n        <!-- Friction force f_k -->\n        <line x1=\"-25\" y1=\"-5\" x2=\"-65\" y2=\"-5\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n        <polygon points=\"-65,-5 -55,-9 -55,-1\" fill=\"#dc2626\"/>\n        <text x=\"-70\" y=\"-12\" font-size=\"9\" font-weight=\"bold\" fill=\"#dc2626\">f_s</text>\n      </g>\n\n      <!-- Downward gravity & components -->\n      <line x1=\"140\" y1=\"130\" x2=\"140\" y2=\"195\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <polygon points=\"140,195 136,185 144,185\" fill=\"#2563eb\"/>\n      <text x=\"145\" y=\"175\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#2563eb\">mg</text>\n\n      <rect x=\"250\" y=\"55\" width=\"130\" height=\"135\" rx=\"6\" fill=\"#f5f3ff\" stroke=\"#ddd6fe\"/>\n      <text x=\"258\" y=\"75\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#5b21b6\">Equilibrium:</text>\n      <text x=\"258\" y=\"95\" font-size=\"9\" fill=\"#334155\">&bull; N = mg cos &theta;</text>\n      <text x=\"258\" y=\"115\" font-size=\"9\" fill=\"#334155\">&bull; F_net = mg sin &theta; - f</text>\n      <text x=\"258\" y=\"135\" font-size=\"9\" fill=\"#334155\">&bull; f_s &le; &mu;_s N</text>\n      <text x=\"258\" y=\"155\" font-size=\"9\" font-weight=\"bold\" fill=\"#047857\">&bull; &theta;_repose = tan&oline;&sup1;(&mu;_s)</text>\n\n      <!-- Panel 2: Atwood Pulley Dynamics -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e293b\">2. Connected Masses &amp; Atwood Machine:</text>\n\n      <!-- Pulley circle -->\n      <circle cx=\"530\" cy=\"70\" r=\"18\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"2\"/>\n      <circle cx=\"530\" cy=\"70\" r=\"3\" fill=\"#0f172a\"/>\n      <line x1=\"530\" y1=\"35\" x2=\"530\" y2=\"70\" stroke=\"#475569\" stroke-width=\"2\"/>\n\n      <!-- String and Mass 1 -->\n      <line x1=\"512\" y1=\"70\" x2=\"512\" y2=\"135\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <rect x=\"497\" y=\"135\" width=\"30\" height=\"30\" rx=\"4\" fill=\"#fee2e2\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n      <text x=\"504\" y=\"154\" font-size=\"9\" font-weight=\"bold\" fill=\"#b91c1c\">m_1</text>\n      <!-- Tension T -->\n      <line x1=\"512\" y1=\"125\" x2=\"512\" y2=\"105\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n      <polygon points=\"512,105 508,113 516,113\" fill=\"#7c3aed\"/>\n      <text x=\"518\" y=\"118\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#7c3aed\">T</text>\n\n      <!-- String and Mass 2 -->\n      <line x1=\"548\" y1=\"70\" x2=\"548\" y2=\"155\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <rect x=\"531\" y=\"155\" width=\"34\" height=\"36\" rx=\"4\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n      <text x=\"538\" y=\"177\" font-size=\"9\" font-weight=\"bold\" fill=\"#1d4ed8\">m_2</text>\n      <!-- Tension T -->\n      <line x1=\"548\" y1=\"145\" x2=\"548\" y2=\"125\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n      <polygon points=\"548,125 544,133 552,133\" fill=\"#7c3aed\"/>\n      <text x=\"554\" y=\"138\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#7c3aed\">T</text>\n\n      <rect x=\"580\" y=\"55\" width=\"175\" height=\"135\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n      <text x=\"590\" y=\"75\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#1e293b\">Atwood Formulas:</text>\n      <text x=\"590\" y=\"98\" font-size=\"9\" font-weight=\"bold\" fill=\"#2563eb\">a = (m&sup2; - m&sup1;)g / (m&sup1; + m&sup2;)</text>\n      <text x=\"590\" y=\"123\" font-size=\"9\" font-weight=\"bold\" fill=\"#7c3aed\">T = 2m&sup1;m&sup2;g / (m&sup1; + m&sup2;)</text>\n      <text x=\"590\" y=\"150\" font-size=\"8.5\" fill=\"#475569\">If m&sup2; &gt; m&sup1;:</text>\n      <text x=\"590\" y=\"168\" font-size=\"8.5\" fill=\"#047857\">&bull; m&sup2; accelerates &darr;</text>\n      <text x=\"590\" y=\"184\" font-size=\"8.5\" fill=\"#047857\">&bull; m&sup1; accelerates &uarr;</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 4.1 to 4.31: Newton's Laws, Momentum Conservation, Impulse, Friction, Circular Dynamics &amp; Pulley Systems</div>\n\n  <!-- c11p-ch4-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q1')\">\n      <div class=\"q-num\">Question 4.1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give the magnitude and direction of the net force acting on<br>(a) a drop of rain falling vertically with a constant speed,<br>(b) a cork of mass $10\\text{ g}$ floating on water,<br>(c) a kite skillfully held stationary in the sky,<br>(d) a car moving with a constant velocity of $30\\text{ km h}^{-1}$ on a rough road,<br>(e) a high-speed electron in space far from all gravitational objects, and free of electric and magnetic fields.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Newton’s First Law of Motion:</b> If a body is at rest or moving with uniform velocity in a straight line, its acceleration is zero ($a = 0$), so the net external force acting on it is identically zero ($\\vec{F}_{net} = m\\vec{a} = \\mathbf{0}$).<br><br>\n    • <b>(a) Raindrop falling at constant speed:</b> Acceleration $a = 0$. Downward gravity is balanced by upward viscous air drag and buoyant force.<br>\n      $$\\mathbf{\\text{Net force} = 0}$$<br>\n    • <b>(b) Cork of mass $10\\text{ g}$ floating on water:</b> Cork is at rest on the water surface ($a = 0$). Downward gravitational weight is exactly balanced by the upward buoyant upthrust.<br>\n      $$\\mathbf{\\text{Net force} = 0}$$<br>\n    • <b>(c) Kite skillfully held stationary:</b> The kite is at rest ($a = 0$). The upward aerodynamic lift is balanced by tension in the string and gravity.<br>\n      $$\\mathbf{\\text{Net force} = 0}$$<br>\n    • <b>(d) Car moving with constant velocity $30\\text{ km h}^{-1}$:</b> Since velocity is constant (both in magnitude and direction), $a = 0$. The forward driving force of the engine exactly balances backward friction and air resistance.<br>\n      $$\\mathbf{\\text{Net force} = 0}$$<br>\n    • <b>(e) High-speed electron far in field-free space:</b> The electron experiences no gravitational, electric, or magnetic fields. There is no external agent exerting force.<br>\n      $$\\mathbf{\\text{Net force} = 0}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating Newton's First Law: Constant velocity implies zero net force</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification and zero net force for parts (a) and (b)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification and zero net force for parts (c), (d), and (e)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q2')\">\n      <div class=\"q-num\">Question 4.2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A pebble of mass $0.05\\text{ kg}$ is thrown vertically upwards. Give the direction and magnitude of the net force on the pebble,<br>(a) during its upward motion,<br>(b) during its downward motion,<br>(c) at the highest point where it is momentarily at rest. Do your answers change if the pebble was thrown at an angle of $45^\\circ$ with the horizontal direction? Ignore air resistance.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given mass of pebble $m = 0.05\\text{ kg}$, $g = 9.8\\text{ m s}^{-2}$.<br>\n    Once released, the only force acting on the pebble (neglecting air resistance) is the gravitational force of Earth:<br>\n    $$F = mg = 0.05\\text{ kg} \\times 9.8\\text{ m s}^{-2} = \\mathbf{0.49\\text{ N}}$$<br><br>\n    • <b>(a) During upward motion:</b> Magnitude = $\\mathbf{0.49\\text{ N}}$, directed <b>vertically downwards</b>.<br>\n    • <b>(b) During downward motion:</b> Magnitude = $\\mathbf{0.49\\text{ N}}$, directed <b>vertically downwards</b>.<br>\n    • <b>(c) At the highest point:</b> Even though instantaneous velocity is zero, acceleration is still $g$. Magnitude = $\\mathbf{0.49\\text{ N}}$, directed <b>vertically downwards</b>.<br><br>\n    • <b>If thrown at $45^\\circ$ angle:</b> The horizontal velocity component ($u \\cos 45^\\circ$) remains constant, but the horizontal acceleration is zero ($a_x = 0$). The only acceleration is still $g$ vertically downwards. Therefore, <b>the answer does not change</b>; in all cases, the net force remains $\\mathbf{0.49\\text{ N}}$ vertically downwards.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of gravitational force: $F = mg = 0.49\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Force magnitude and vertically downward direction in (a), (b), (c)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of $45^\\circ$ projectile motion: force remains unchanged at $0.49\\text{ N}$ downwards</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q3')\">\n      <div class=\"q-num\">Question 4.3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give the magnitude and direction of the net force acting on a stone of mass $0.1\\text{ kg}$,<br>(a) just after it is dropped from the window of a stationary train,<br>(b) just after it is dropped from the window of a train running at a constant velocity of $36\\text{ km h}^{-1}$,<br>(c) just after it is dropped from the window of a train accelerating with $1\\text{ m s}^{-2}$,<br>(d) lying on the floor of a train which is accelerating with $1\\text{ m s}^{-2}$, the stone being at rest relative to the train. Neglect air resistance throughout.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Mass $m = 0.1\\text{ kg}$, $g = 9.8\\text{ m s}^{-2}$.<br><br>\n    • <b>(a) Dropped from stationary train:</b> The moment the stone leaves the train, contact is broken. The only force acting is gravity:<br>\n      $$F = mg = 0.1 \\times 9.8 = \\mathbf{0.98\\text{ N, vertically downwards}}$$<br><br>\n    • <b>(b) Dropped from train with constant velocity $36\\text{ km h}^{-1}$:</b> The stone retains the horizontal velocity by inertia, but no horizontal force acts on it. The only force is gravity:<br>\n      $$F = mg = \\mathbf{0.98\\text{ N, vertically downwards}}$$<br><br>\n    • <b>(c) Dropped from train accelerating with $1\\text{ m s}^{-2}$:</b> The moment it is dropped, no contact force or pseudo force exists from the train. The only acting force is gravity:<br>\n      $$F = mg = \\mathbf{0.98\\text{ N, vertically downwards}}$$<br><br>\n    • <b>(d) Lying on floor of accelerating train ($a = 1\\text{ m s}^{-2}$):</b> The vertical normal reaction balances gravity ($N = mg$). Since the stone is at rest relative to the accelerating train, it shares the train’s acceleration ($a = 1\\text{ m s}^{-2}$ in the horizontal forward direction), provided by static friction:<br>\n      $$F_{net} = ma = 0.1\\text{ kg} \\times 1\\text{ m s}^{-2} = \\mathbf{0.1\\text{ N, horizontally in the direction of motion of the train}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a), (b), (c) Gravitational force $F = 0.98\\text{ N}$ vertically downwards</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Net force $F = ma = 0.1\\text{ N}$ horizontally forward due to static friction</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q4')\">\n      <div class=\"q-num\">Question 4.4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        One end of a string of length $l$ is connected to a particle of mass $m$ and the other to a small peg on a smooth horizontal table. If the particle moves in a circle with speed $v$ the net force on the particle (directed towards the centre) is:<br>(i) $T$,<br>(ii) $T - \\frac{m v^2}{l}$,<br>(iii) $T + \\frac{m v^2}{l}$,<br>(iv) $0$<br>[$T$ is the tension in the string]. [Choose the correct alternative].\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Correct Option: (i) $T$</b><br><br>\n    <b>Justification:</b><br>\n    The particle is moving on a smooth horizontal table in a circular path. The normal reaction from the table balances the downward weight ($N = mg$).<br>\n    The only physical horizontal force acting on the particle is the tension $T$ exerted by the string directed towards the centre peg.<br>\n    According to Newton’s second law, this net inward force provides the required centripetal acceleration:<br>\n    $$F_{net} = T = \\frac{m v^2}{l}$$<br>\n    Therefore, the <i>net force</i> acting on the particle directed towards the centre is simply $\\mathbf{T}$.<br>\n    (Note: $\\frac{mv^2}{l}$ is the value of $m\\vec{a}$, not an additional physical force).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of correct option (i) $T$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that tension is the sole real force providing centripetal acceleration $ma_c$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q5')\">\n      <div class=\"q-num\">Question 4.5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A constant retarding force of $50\\text{ N}$ is applied to a body of mass $20\\text{ kg}$ moving initially with a speed of $15\\text{ m s}^{-1}$. How long does the body take to stop?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass $m = 20\\text{ kg}$<br>\n    • Initial speed $u = 15\\text{ m s}^{-1}$<br>\n    • Final speed $v = 0$<br>\n    • Retarding force $F = -50\\text{ N}$<br><br>\n    <b>1. Retardation (acceleration):</b><br>\n    $$a = \\frac{F}{m} = \\frac{-50\\text{ N}}{20\\text{ kg}} = -2.5\\text{ m s}^{-2}$$<br><br>\n    <b>2. Time taken to stop ($t$):</b><br>\n    Using the first equation of motion $v = u + at$:<br>\n    $$0 = 15 + (-2.5)t \\implies 2.5 t = 15$$<br>\n    $$t = \\frac{15}{2.5} = \\mathbf{6.0\\text{ seconds}}$$<br><br>\n    $$\\therefore \\text{The body takes } \\mathbf{6.0\\text{ seconds}} \\text{ to come to rest.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Retardation calculation $a = F/m = -2.5\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of $v = u + at$ to find stopping time $t = 6\\text{ s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q6')\">\n      <div class=\"q-num\">Question 4.6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A constant force acting on a body of mass $3.0\\text{ kg}$ changes its speed from $2.0\\text{ m s}^{-1}$ to $3.5\\text{ m s}^{-1}$ in $25\\text{ s}$. The direction of the motion of the body remains unchanged. What is the magnitude and direction of the force?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass $m = 3.0\\text{ kg}$<br>\n    • Initial velocity $u = 2.0\\text{ m s}^{-1}$<br>\n    • Final velocity $v = 3.5\\text{ m s}^{-1}$<br>\n    • Time interval $t = 25\\text{ s}$<br><br>\n    <b>1. Acceleration ($a$):</b><br>\n    $$a = \\frac{v - u}{t} = \\frac{3.5 - 2.0}{25} = \\frac{1.5}{25} = 0.06\\text{ m s}^{-2}$$<br><br>\n    <b>2. Magnitude of Force ($F$):</b><br>\n    $$F = ma = 3.0\\text{ kg} \\times 0.06\\text{ m s}^{-2} = \\mathbf{0.18\\text{ N}}$$<br><br>\n    <b>3. Direction of Force:</b><br>\n    Since velocity increases in the original direction, the acceleration is in the direction of motion.<br>\n    $$\\mathbf{\\text{The force is } 0.18\\text{ N in the direction of motion of the body.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of acceleration $a = 0.06\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Force magnitude $F = ma = 0.18\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating direction as aligned with the motion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q7')\">\n      <div class=\"q-num\">Question 4.7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A body of mass $5\\text{ kg}$ is acted upon by two perpendicular forces $8\\text{ N}$ and $6\\text{ N}$. Give the magnitude and direction of the acceleration of the body.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass $m = 5\\text{ kg}$<br>\n    • Perpendicular forces: $F_1 = 8\\text{ N}$, $F_2 = 6\\text{ N}$ (angle $\\theta = 90^\\circ$).<br><br>\n    <b>1. Magnitude of Resultant Force ($F$):</b><br>\n    $$F = \\sqrt{F_1^2 + F_2^2} = \\sqrt{8^2 + 6^2} = \\sqrt{64 + 36} = \\sqrt{100} = \\mathbf{10\\text{ N}}$$<br><br>\n    <b>2. Magnitude of Acceleration ($a$):</b><br>\n    $$a = \\frac{F}{m} = \\frac{10\\text{ N}}{5\\text{ kg}} = \\mathbf{2.0\\text{ m s}^{-2}}$$<br><br>\n    <b>3. Direction of Acceleration:</b><br>\n    The acceleration is in the direction of the resultant force. Let $\\theta$ be the angle made with the $8\\text{ N}$ force:<br>\n    $$\\tan \\theta = \\frac{F_2}{F_1} = \\frac{6}{8} = 0.75$$<br>\n    $$\\theta = \\arctan(0.75) \\approx \\mathbf{36.87^\\circ} \\approx \\mathbf{37^\\circ}$$<br><br>\n    $$\\therefore \\text{Acceleration has magnitude } \\mathbf{2\\text{ m s}^{-2}} \\text{ directed at } \\mathbf{37^\\circ} \\text{ to the } 8\\text{ N force.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Resultant force calculation $F = \\sqrt{8^2+6^2} = 10\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acceleration magnitude $a = F/m = 2\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direction determination $\\theta = \\arctan(0.75) \\approx 37^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q8')\">\n      <div class=\"q-num\">Question 4.8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The driver of a three-wheeler moving with a speed of $36\\text{ km h}^{-1}$ sees a child standing in the middle of the road and brings his vehicle to rest in $4.0\\text{ s}$ just in time to save the child. What is the average retarding force on the vehicle? The mass of the three-wheeler is $400\\text{ kg}$ and the mass of the driver is $65\\text{ kg}$.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Initial speed $u = 36\\text{ km h}^{-1} = 36 \\times \\frac{5}{18} = 10\\text{ m s}^{-1}$<br>\n    • Final speed $v = 0$<br>\n    • Time taken $t = 4.0\\text{ s}$<br>\n    • Total mass $M = \\text{mass of vehicle} + \\text{mass of driver} = 400 + 65 = 465\\text{ kg}$<br><br>\n    <b>1. Retardation ($a$):</b><br>\n    $$a = \\frac{v - u}{t} = \\frac{0 - 10}{4.0} = -2.5\\text{ m s}^{-2}$$<br><br>\n    <b>2. Average Retarding Force ($F$):</b><br>\n    $$F = M |a| = 465\\text{ kg} \\times 2.5\\text{ m s}^{-2} = \\mathbf{1162.5\\text{ N}} \\approx \\mathbf{1.16 \\times 10^3\\text{ N}}$$<br><br>\n    $$\\therefore \\text{The average retarding force on the vehicle is } \\mathbf{1162.5\\text{ N}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Total mass calculation $M = 465\\text{ kg}$ and speed conversion to $10\\text{ m/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Retardation magnitude $|a| = 2.5\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Retarding force $F = Ma = 1162.5\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q9')\">\n      <div class=\"q-num\">Question 4.9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A rocket with a lift-off mass $20,000\\text{ kg}$ is blasted upwards with an initial acceleration of $5.0\\text{ m s}^{-2}$. Calculate the initial thrust (force) of the blast.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass of rocket $m = 20,000\\text{ kg} = 2 \\times 10^4\\text{ kg}$<br>\n    • Upward acceleration $a = 5.0\\text{ m s}^{-2}$<br>\n    • Acceleration due to gravity $g = 9.8\\text{ m s}^{-2}$ (or $10\\text{ m s}^{-2}$)<br><br>\n    <b>Equation of Motion:</b><br>\n    Thrust force $T$ acts vertically upwards, while gravity $mg$ acts vertically downwards:<br>\n    $$T - mg = ma \\implies T = m(g + a)$$<br><br>\n    Using $g = 9.8\\text{ m s}^{-2}$:<br>\n    $$T = 20000 \\times (9.8 + 5.0) = 20000 \\times 14.8 = \\mathbf{296,000\\text{ N}} = \\mathbf{2.96 \\times 10^5\\text{ N}}$$<br><br>\n    (If $g = 10\\text{ m s}^{-2}$ is used: $T = 20000 \\times 15.0 = 3.0 \\times 10^5\\text{ N}$).<br>\n    $$\\therefore \\text{Initial thrust of the blast is } \\mathbf{2.96 \\times 10^5\\text{ N}} \\text{ vertically upwards.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formulation of rocket dynamic balance: $T - mg = ma$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and final thrust calculation: $2.96 \\times 10^5\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q10')\">\n      <div class=\"q-num\">Question 4.10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A body of mass $0.40\\text{ kg}$ moving initially with a constant speed of $10\\text{ m s}^{-1}$ to the north is subject to a constant force of $8.0\\text{ N}$ directed towards the south for $30\\text{ s}$. Take the instant the force is applied to be $t = 0$, the position of the body at that time to be $x = 0$, and predict its position at $t = -5\\text{ s}, 25\\text{ s}, 100\\text{ s}$.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Choose North as positive ($+x$) and South as negative ($-x$).<br>\n    Given: $m = 0.40\\text{ kg}$, initial velocity $u = +10\\text{ m s}^{-1}$ at $t = 0$, $x(0) = 0$.<br>\n    Force for $0 \\le t \\le 30\\text{ s}$: $F = -8.0\\text{ N}$.<br>\n    Acceleration during $0 \\le t \\le 30\\text{ s}$:<br>\n    $$a = \\frac{F}{m} = \\frac{-8.0}{0.40} = -20\\text{ m s}^{-2}$$<br><br>\n    • <b>1. At $t = -5\\text{ s}$ (before force is applied):</b><br>\n      The body moved with uniform velocity $u = 10\\text{ m s}^{-1}$ with $a = 0$.<br>\n      $$x(-5) = u t = 10 \\times (-5) = \\mathbf{-50\\text{ m}}$$<br><br>\n    • <b>2. At $t = 25\\text{ s}$ (during action of force):</b><br>\n      $$x(25) = u t + \\frac{1}{2} a t^2 = 10(25) + \\frac{1}{2}(-20)(25)^2 = 250 - 10(625) = 250 - 6250 = \\mathbf{-6000\\text{ m} = -6.0\\text{ km}}$$<br><br>\n    • <b>3. At $t = 100\\text{ s}$ (force ceases after $30\\text{ s}$):</b><br>\n      At $t = 30\\text{ s}$, position is:<br>\n      $$x(30) = 10(30) + \\frac{1}{2}(-20)(30)^2 = 300 - 9000 = -8700\\text{ m}$$<br>\n      Velocity at $t = 30\\text{ s}$:<br>\n      $$v(30) = u + a t = 10 + (-20)(30) = 10 - 600 = -590\\text{ m s}^{-1}$$<br>\n      For the remaining interval of $70\\text{ s}$ (from $t = 30$ to $100\\text{ s}$), force is zero, so velocity remains constant at $-590\\text{ m s}^{-1}$:<br>\n      $$x(100) = x(30) + v(30) \\times (100 - 30) = -8700 + (-590)(70) = -8700 - 41300 = \\mathbf{-50000\\text{ m} = -50\\text{ km}}$$<br><br>\n    $$\\therefore \\text{Positions are: } x(-5) = \\mathbf{-50\\text{ m}}, \\quad x(25) = \\mathbf{-6\\text{ km}}, \\quad x(100) = \\mathbf{-50\\text{ km}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Acceleration calculation $a = -20\\text{ m s}^{-2}$ in South direction</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Position at $t = -5\\text{ s}$: $-50\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Position at $t = 25\\text{ s}$: $-6000\\text{ m}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Position at $t = 100\\text{ s}$: $-50000\\text{ m}$ considering zero force after $30\\text{ s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q11')\">\n      <div class=\"q-num\">Question 4.11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A truck starts from rest and accelerates uniformly at $2.0\\text{ m s}^{-2}$. At $t = 10\\text{ s}$, a stone is dropped by a person standing on the top of the truck ($6\\text{ m}$ high from the ground). What are the (a) velocity, and (b) acceleration of the stone at $t = 11\\text{ s}$? (Neglect air resistance.)\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $u = 0$, $a_{truck} = 2.0\\text{ m s}^{-2}$, stone dropped at $t = 10\\text{ s}$.<br><br>\n    • <b>Horizontal velocity at the instant of drop ($t = 10\\text{ s}$):</b><br>\n      $$v_x = u + a_{truck} t = 0 + 2.0(10) = 20\\text{ m s}^{-1}$$<br>\n      After being dropped, no horizontal force acts on the stone (neglecting air resistance), so $v_x = 20\\text{ m s}^{-1}$ remains constant.<br><br>\n    • <b>(a) Velocity at $t = 11\\text{ s}$:</b><br>\n      Time elapsed since drop: $\\Delta t = 11 - 10 = 1\\text{ s}$.<br>\n      Vertical velocity acquired under gravity ($g = 9.8\\text{ m s}^{-2}$):<br>\n      $$v_y = 0 + g \\Delta t = 9.8 \\times 1 = 9.8\\text{ m s}^{-1} \\text{ (downwards)}$$<br>\n      Net velocity magnitude:<br>\n      $$v = \\sqrt{v_x^2 + v_y^2} = \\sqrt{20^2 + (9.8)^2} = \\sqrt{400 + 96.04} = \\sqrt{496.04} \\approx \\mathbf{22.27\\text{ m s}^{-1} \\approx 22.3\\text{ m s}^{-1}}$$<br>\n      Direction with horizontal:<br>\n      $$\\tan \\theta = \\frac{v_y}{v_x} = \\frac{9.8}{20} = 0.49 \\implies \\theta = \\arctan(0.49) \\approx \\mathbf{26.1^\\circ} \\text{ below the horizontal.}$$<br><br>\n    • <b>(b) Acceleration at $t = 11\\text{ s}$:</b><br>\n      Once released, the stone is a free projectile under gravity.<br>\n      $$\\mathbf{a = 9.8\\text{ m s}^{-2} \\text{ vertically downwards.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Horizontal velocity at drop: $v_x = 20\\text{ m s}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vertical velocity at $t = 11\\text{ s}$: $v_y = 9.8\\text{ m s}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Net velocity magnitude and direction: $22.3\\text{ m s}^{-1}$ at $26.1^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acceleration of free projectile: $9.8\\text{ m s}^{-2}$ vertically downwards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q12')\">\n      <div class=\"q-num\">Question 4.12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A bob of mass $0.1\\text{ kg}$ hung from the ceiling of a room by a string $2\\text{ m}$ long is set into oscillation. The speed of the bob at its mean position is $1\\text{ m s}^{-1}$. What is the trajectory of the bob if the string is cut when the bob is (a) at one of its extreme positions, (b) at its mean position?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Cut at one of the extreme positions:</b><br>\n      At the extreme position of an oscillation, the instantaneous velocity of the bob is zero ($v = 0$).<br>\n      When the string is cut, there is no initial horizontal velocity. The only force acting on the bob is gravity vertically downwards.<br>\n      Therefore, the bob <b>falls vertically downwards in a straight line</b> under gravity.<br><br>\n    • <b>(b) Cut at its mean position:</b><br>\n      At the mean position, the bob possesses a horizontal velocity of $v = 1\\text{ m s}^{-1}$ directed tangential to its circular arc.<br>\n      When the string is cut, it behaves like a projectile launched horizontally with initial velocity $u_x = 1\\text{ m s}^{-1}$ and acceleration $g$ vertically downwards.<br>\n      Therefore, the trajectory of the bob is a <b>parabolic path</b> until it hits the ground.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Zero velocity at extreme leading to straight vertical free fall</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Horizontal velocity at mean position resulting in parabolic trajectory</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q13')\">\n      <div class=\"q-num\">Question 4.13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A man of mass $70\\text{ kg}$ stands on a weighing scale in a lift which is moving<br>(a) upwards with a uniform speed of $10\\text{ m s}^{-1}$,<br>(b) downwards with a uniform acceleration of $5\\text{ m s}^{-2}$,<br>(c) upwards with a uniform acceleration of $5\\text{ m s}^{-2}$.<br>What would be the readings on the scale in each case?<br>(d) What would be the reading if the lift mechanism failed and it hurtled down freely under gravity? (Take $g = 9.8\\text{ m s}^{-2}$).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given mass of man $m = 70\\text{ kg}$, $g = 9.8\\text{ m s}^{-2}$.<br>\n    The reading of the weighing scale is the normal reaction $R$ (apparent weight). Scale reading in $\\text{kg-wt} = R/g$.<br><br>\n    • <b>(a) Uniform speed upwards ($a = 0$):</b><br>\n      $$R = mg = 70 \\times 9.8 = \\mathbf{686\\text{ N}}$$<br>\n      $$\\text{Reading} = \\frac{686}{9.8} = \\mathbf{70\\text{ kg}}$$<br><br>\n    • <b>(b) Downward acceleration $a = 5\\text{ m s}^{-2}$ ($a < g$):</b><br>\n      $$R = m(g - a) = 70(9.8 - 5.0) = 70 \\times 4.8 = \\mathbf{336\\text{ N}}$$<br>\n      $$\\text{Reading} = \\frac{336}{9.8} \\approx \\mathbf{34.29\\text{ kg}}$$<br><br>\n    • <b>(c) Upward acceleration $a = 5\\text{ m s}^{-2}$:</b><br>\n      $$R = m(g + a) = 70(9.8 + 5.0) = 70 \\times 14.8 = \\mathbf{1036\\text{ N}}$$<br>\n      $$\\text{Reading} = \\frac{1036}{9.8} \\approx \\mathbf{105.71\\text{ kg}}$$<br><br>\n    • <b>(d) Free fall ($a = g$):</b><br>\n      $$R = m(g - g) = \\mathbf{0\\text{ N}}$$<br>\n      $$\\text{Reading} = \\mathbf{0\\text{ kg}} \\text{ (State of Weightlessness)}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Apparent weight $R = mg = 686\\text{ N}$ (scale: $70\\text{ kg}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Apparent weight $R = m(g-a) = 336\\text{ N}$ (scale: $34.3\\text{ kg}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Apparent weight $R = m(g+a) = 1036\\text{ N}$ (scale: $105.7\\text{ kg}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Free fall weightlessness $R = 0\\text{ N}$ (scale: $0\\text{ kg}$)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q14')\">\n      <div class=\"q-num\">Question 4.14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Figure 4.16 shows the position-time graph of a particle of mass $4\\text{ kg}$. What is the (a) force on the particle for $t < 0$, $t > 4\\text{ s}$, $0 < t < 4\\text{ s}$? (b) impulse at $t = 0$ and $t = 4\\text{ s}$? (Consider one-dimensional motion only).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Mass $m = 4\\text{ kg}$.<br><br>\n    • <b>(a) Forces in different time intervals:</b><br>\n      - <i>For $t < 0$:</i> The particle is at rest ($x = 0$), so velocity $v = 0$ and acceleration $a = 0$. $\\therefore \\mathbf{F = 0}$.<br>\n      - <i>For $0 < t < 4\\text{ s}$:</i> The graph is a straight line of constant slope: $v = \\frac{3 - 0}{4 - 0} = 0.75\\text{ m s}^{-1}$. Since velocity is constant, acceleration $a = 0$. $\\therefore \\mathbf{F = 0}$.<br>\n      - <i>For $t > 4\\text{ s}$:</i> The particle is at rest at $x = 3\\text{ m}$ (horizontal line), so $v = 0$ and $a = 0$. $\\therefore \\mathbf{F = 0}$.<br><br>\n    • <b>(b) Impulse at $t = 0$ and $t = 4\\text{ s}$:</b><br>\n      Impulse = Change in momentum = $m(v_f - v_i)$.<br>\n      - <i>At $t = 0$:</i> Initial velocity $v_i = 0$, final velocity $v_f = 0.75\\text{ m s}^{-1}$.<br>\n        $$\\text{Impulse} = 4\\text{ kg} \\times (0.75 - 0) = \\mathbf{+3.0\\text{ kg m s}^{-1} = +3.0\\text{ N s}}$$<br>\n      - <i>At $t = 4\\text{ s}$:</i> Initial velocity $v_i = 0.75\\text{ m s}^{-1}$, final velocity $v_f = 0$.<br>\n        $$\\text{Impulse} = 4\\text{ kg} \\times (0 - 0.75) = \\mathbf{-3.0\\text{ kg m s}^{-1} = -3.0\\text{ N s}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Force evaluated as zero in all three intervals ($a = 0$)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Impulse at $t = 0$: $+3.0\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Impulse at $t = 4\\text{ s}$: $-3.0\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q15')\">\n      <div class=\"q-num\">Question 4.15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Two bodies of masses $10\\text{ kg}$ and $20\\text{ kg}$ respectively, kept on a smooth, horizontal surface are tied to the ends of a light string. A horizontal force $F = 600\\text{ N}$ is applied to (i) A, (ii) B along the direction of string. What is the tension in the string in each case?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $m_A = 10\\text{ kg}$, $m_B = 20\\text{ kg}$, $F = 600\\text{ N}$.<br>\n    Common acceleration of the combined system:<br>\n    $$a = \\frac{F}{m_A + m_B} = \\frac{600}{10 + 20} = \\frac{600}{30} = 20\\text{ m s}^{-2}$$<br><br>\n    • <b>Case (i): Force applied to body A ($10\\text{ kg}$):</b><br>\n      The tension $T$ in the string is responsible for accelerating body B behind it:<br>\n      $$T = m_B a = 20\\text{ kg} \\times 20\\text{ m s}^{-2} = \\mathbf{400\\text{ N}}$$<br><br>\n    • <b>Case (ii): Force applied to body B ($20\\text{ kg}$):</b><br>\n      The tension $T$ in the string is responsible for accelerating body A behind it:<br>\n      $$T = m_A a = 10\\text{ kg} \\times 20\\text{ m s}^{-2} = \\mathbf{200\\text{ N}}$$<br><br>\n    $$\\therefore \\text{Tension is } \\mathbf{400\\text{ N}} \\text{ in Case (i), and } \\mathbf{200\\text{ N}} \\text{ in Case (ii)}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Common acceleration calculation $a = 20\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Case (i) tension $T = m_B a = 400\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Case (ii) tension $T = m_A a = 200\\text{ N}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q16')\">\n      <div class=\"q-num\">Question 4.16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Two masses $8\\text{ kg}$ and $12\\text{ kg}$ are connected at the two ends of a light inextensible string that goes over a frictionless pulley. Find the acceleration of the masses, and the tension in the string when the masses are released.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: $m_1 = 8\\text{ kg}$, $m_2 = 12\\text{ kg}$, $g = 9.8\\text{ m s}^{-2}$.<br>\n    This is Atwood's machine. Mass $m_2$ accelerates downwards while $m_1$ accelerates upwards.<br><br>\n    <b>1. Acceleration ($a$):</b><br>\n    $$a = \\frac{m_2 - m_1}{m_1 + m_2} g = \\frac{12 - 8}{12 + 8} \\times 9.8 = \\frac{4}{20} \\times 9.8 = \\frac{9.8}{5} = \\mathbf{1.96\\text{ m s}^{-2}}$$<br><br>\n    <b>2. Tension in the string ($T$):</b><br>\n    $$T = \\frac{2 m_1 m_2}{m_1 + m_2} g = \\frac{2 \\times 8 \\times 12}{8 + 12} \\times 9.8 = \\frac{192}{20} \\times 9.8 = 9.6 \\times 9.8 = \\mathbf{94.08\\text{ N}} \\approx \\mathbf{94.1\\text{ N}}$$<br><br>\n    $$\\therefore \\text{Acceleration } a = \\mathbf{1.96\\text{ m s}^{-2}}, \\quad \\text{Tension } T = \\mathbf{94.1\\text{ N}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Atwood machine equations of motion derived</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acceleration calculated: $a = 1.96\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tension calculated: $T = 94.08\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q17 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q17\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q17')\">\n      <div class=\"q-num\">Question 4.17</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A nucleus is at rest in the laboratory frame of reference. Show that if it disintegrates into two smaller nuclei the products must be emitted in opposite directions.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Conservation of Linear Momentum:</b><br>\n    Let $M$ be the mass of the parent nucleus at rest.<br>\n    Initial linear momentum of the nucleus:<br>\n    $$\\vec{P}_i = \\mathbf{0}$$<br><br>\n    Let the nucleus disintegrate into two fragments of masses $m_1$ and $m_2$ with final velocities $\\vec{v}_1$ and $\\vec{v}_2$ respectively.<br>\n    Final linear momentum of the system:<br>\n    $$\\vec{P}_f = m_1\\vec{v}_1 + m_2\\vec{v}_2$$<br><br>\n    Since no external force acts during the internal nuclear decay, the total linear momentum is conserved:<br>\n    $$\\vec{P}_f = \\vec{P}_i \\implies m_1\\vec{v}_1 + m_2\\vec{v}_2 = \\mathbf{0}$$<br>\n    $$m_1\\vec{v}_1 = -m_2\\vec{v}_2 \\implies \\vec{v}_1 = -\\left(\\frac{m_2}{m_1}\\right)\\vec{v}_2$$<br><br>\n    Since masses $m_1$ and $m_2$ are positive scalars, the ratio $\\frac{m_2}{m_1}$ is a positive real number.<br>\n    The negative sign demonstrates that the velocity vector $\\vec{v}_1$ is strictly antiparallel to $\\vec{v}_2$.<br>\n    $$\\mathbf{\\text{Hence, the two daughter fragments must move in diametrically opposite directions.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Statement of law of conservation of linear momentum with zero initial momentum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mathematical equation: $m_1\\vec{v}_1 = -m_2\\vec{v}_2$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical interpretation of the negative sign confirming opposite emission directions</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q18 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q18\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q18')\">\n      <div class=\"q-num\">Question 4.18</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Two billiard balls each of mass $0.05\\text{ kg}$ moving in opposite directions with speed $6\\text{ m s}^{-1}$ collide and rebound with the same speed. What is the impulse imparted to each ball due to the other?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given mass of each ball $m = 0.05\\text{ kg}$, speed $u = 6\\text{ m s}^{-1}$.<br>\n    Let the initial direction of motion of the first ball be positive.<br><br>\n    • <b>For the first ball:</b><br>\n      Initial momentum: $p_i = m u = 0.05 \\times (+6) = +0.3\\text{ kg m s}^{-1}$.<br>\n      Final momentum after rebound: $p_f = m (-u) = 0.05 \\times (-6) = -0.3\\text{ kg m s}^{-1}$.<br>\n      $$\\text{Impulse imparted to first ball} = p_f - p_i = -0.3 - (+0.3) = \\mathbf{-0.6\\text{ kg m s}^{-1} = -0.6\\text{ N s}}$$<br><br>\n    • <b>For the second ball:</b><br>\n      Initial momentum: $p_i = m (-u) = -0.3\\text{ kg m s}^{-1}$.<br>\n      Final momentum after rebound: $p_f = m (+u) = +0.3\\text{ kg m s}^{-1}$.<br>\n      $$\\text{Impulse imparted to second ball} = p_f - p_i = +0.3 - (-0.3) = \\mathbf{+0.6\\text{ kg m s}^{-1} = +0.6\\text{ N s}}$$<br><br>\n    $$\\therefore \\text{The magnitude of impulse imparted to each ball is } \\mathbf{0.6\\text{ N s}} \\text{ (opposite in directions).}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Momentum calculation before collision: $\\pm 0.3\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Momentum calculation after rebound: $\\mp 0.3\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Impulse evaluation $\\Delta p = 0.6\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q19 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q19\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q19')\">\n      <div class=\"q-num\">Question 4.19</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A shell of mass $0.020\\text{ kg}$ is fired by a gun of mass $100\\text{ kg}$. If the muzzle speed of the shell is $80\\text{ m s}^{-1}$, what is the recoil speed of the gun?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass of shell $m = 0.020\\text{ kg}$<br>\n    • Mass of gun $M = 100\\text{ kg}$<br>\n    • Muzzle speed of shell $v = 80\\text{ m s}^{-1}$<br>\n    • Recoil speed of gun = $V$<br><br>\n    <b>Conservation of Linear Momentum:</b><br>\n    Initially, the gun and shell are at rest: $P_i = 0$.<br>\n    After firing:<br>\n    $$P_f = M V + m v = 0$$<br>\n    $$V = -\\frac{m v}{M} = -\\frac{0.020 \\times 80}{100} = -\\frac{1.6}{100} = \\mathbf{-0.016\\text{ m s}^{-1} = -1.6\\text{ cm s}^{-1}}$$<br><br>\n    The negative sign indicates that the gun recoils in the direction opposite to the bullet.<br>\n    $$\\therefore \\text{Recoil speed of the gun is } \\mathbf{0.016\\text{ m s}^{-1}} \\text{ (or } 1.6\\text{ cm s}^{-1}\\text{)}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Principle of conservation of momentum stated: $MV + mv = 0$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution: $V = -(0.02 \\times 80)/100$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Recoil speed magnitude: $0.016\\text{ m s}^{-1}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q20 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q20\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q20')\">\n      <div class=\"q-num\">Question 4.20</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A batsman deflects a ball by an angle of $45^\\circ$ without changing its initial speed which is equal to $54\\text{ km h}^{-1}$. What is the impulse imparted to the ball? (Mass of the ball is $0.15\\text{ kg}$.)\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass of ball $m = 0.15\\text{ kg}$<br>\n    • Speed $u = 54\\text{ km h}^{-1} = 54 \\times \\frac{5}{18} = 15\\text{ m s}^{-1}$<br>\n    • Total deflection angle $= 45^\\circ$<br><br>\n    <b>Vector Resolution:</b><br>\n    Let the line of symmetry bisecting the angle of deflection be the normal (perpendicular to the bat face).<br>\n    Angle of incidence with normal: $\\alpha = \\frac{45^\\circ}{2} = 22.5^\\circ$.<br>\n    Angle of reflection with normal: $\\alpha = 22.5^\\circ$.<br><br>\n    • The component of velocity parallel to the bat surface remains unchanged: $v_{\\parallel} = u \\sin 22.5^\\circ$.<br>\n    • The component of velocity perpendicular to the bat surface is reversed from $+u \\cos 22.5^\\circ$ to $-u \\cos 22.5^\\circ$.<br><br>\n    <b>Impulse Imparted:</b><br>\n    $$J = |\\Delta p| = m |\\Delta v_{\\perp}| = m \\left(u \\cos 22.5^\\circ - (-u \\cos 22.5^\\circ)\\right) = 2 m u \\cos 22.5^\\circ$$<br>\n    $$\\cos 22.5^\\circ = \\sqrt{\\frac{1 + \\cos 45^\\circ}{2}} = \\sqrt{\\frac{1 + 0.7071}{2}} = \\sqrt{0.85355} \\approx 0.9239$$<br>\n    $$J = 2 \\times 0.15\\text{ kg} \\times 15\\text{ m s}^{-1} \\times 0.9239 = 4.5 \\times 0.9239 = \\mathbf{4.157\\text{ N s} \\approx 4.16\\text{ N s}}$$<br><br>\n    $$\\therefore \\text{The impulse imparted to the ball is } \\mathbf{4.16\\text{ N s}} \\text{ directed normal to the bat away from it.}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Speed conversion to $15\\text{ m s}^{-1}$ and half-angle analysis $\\alpha = 22.5^\\circ$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Derivation of normal momentum change: $J = 2 m u \\cos 22.5^\\circ$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculation: $J = 4.16\\text{ N s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q21 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q21\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q21')\">\n      <div class=\"q-num\">Question 4.21</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        A stone of mass $0.25\\text{ kg}$ tied to the end of a string is whirled round in a circle of radius $1.5\\text{ m}$ with a speed of $40\\text{ rev./min}$ in a horizontal plane. What is the tension in the string? What is the maximum speed with which the stone can be whirled around if the string can withstand a maximum tension of $200\\text{ N}$?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass $m = 0.25\\text{ kg}$, Radius $r = 1.5\\text{ m}$<br>\n    • Frequency $\\nu = 40\\text{ rev/min} = \\frac{40}{60} = \\frac{2}{3}\\text{ rev s}^{-1}$<br>\n    • Angular velocity $\\omega = 2\\pi \\nu = 2\\pi \\times \\frac{2}{3} = \\frac{4\\pi}{3}\\text{ rad s}^{-1} \\approx 4.189\\text{ rad s}^{-1}$<br><br>\n    <b>1. Tension in the string ($T$):</b><br>\n    $$T = m \\omega^2 r = 0.25 \\times \\left(\\frac{4\\pi}{3}\\right)^2 \\times 1.5 = 0.25 \\times \\frac{16\\pi^2}{9} \\times 1.5 = \\frac{6\\pi^2}{9} \\approx \\frac{6 \\times 9.8696}{9} = \\mathbf{6.58\\text{ N} \\approx 6.6\\text{ N}}$$<br><br>\n    <b>2. Maximum speed ($v_{max}$) for $T_{max} = 200\\text{ N}$:</b><br>\n    $$T_{max} = \\frac{m v_{max}^2}{r} \\implies v_{max}^2 = \\frac{T_{max} r}{m}$$<br>\n    $$v_{max}^2 = \\frac{200 \\times 1.5}{0.25} = \\frac{300}{0.25} = 1200$$<br>\n    $$v_{max} = \\sqrt{1200} = 20\\sqrt{3} \\approx \\mathbf{34.64\\text{ m s}^{-1}}$$<br><br>\n    $$\\therefore \\text{Current tension } = \\mathbf{6.6\\text{ N}}, \\quad \\text{Maximum permissible speed } = \\mathbf{34.6\\text{ m s}^{-1}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of angular velocity $\\omega = 4\\pi/3\\text{ rad/s}$</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tension calculation $T = m\\omega^2 r = 6.6\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Maximum speed formula $v_{max} = \\sqrt{T_{max}r/m} = 34.6\\text{ m/s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q22 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q22\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q22')\">\n      <div class=\"q-num\">Question 4.22</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If, in Exercise 4.21, the speed of the stone is increased beyond the maximum permissible value, and the string breaks suddenly, which of the following correctly describes the trajectory of the stone after the string breaks:<br>(a) the stone moves radially outwards,<br>(b) the stone flies off tangentially from the instant the string breaks,<br>(c) the stone moves off at an angle with the tangent whose magnitude depends on the speed of the particle?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Correct Option: (b)</b><br><br>\n    <b>Physical Reason:</b><br>\n    At any instant during circular motion, the velocity vector of the stone is oriented strictly <b>tangentially</b> to the circular path.<br>\n    The tension in the string provides the centripetal force that continuously changes the direction of this tangential velocity.<br>\n    The moment the string breaks, tension becomes zero ($T = 0$), so no centripetal force acts on the stone.<br>\n    By Newton’s First Law of Motion (law of inertia), an object in motion continues in its state of uniform rectilinear motion along the direction it possessed at that instant.<br>\n    $$\\mathbf{\\text{Therefore, the stone flies off tangentially from the point of break.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of option (b) flying off tangentially</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation via Newton's First Law of inertia of tangential velocity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q23 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q23\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q23')\">\n      <div class=\"q-num\">Question 4.23</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain why<br>(a) a horse cannot pull a cart and run in empty space,<br>(b) passengers are thrown forward from their seats when a speeding bus stops suddenly,<br>(c) it is easier to pull a lawn mower than to push it,<br>(d) a cricketer moves his hands backwards while holding a catch.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    • <b>(a) Horse in empty space:</b> To move forward, the horse must push backward against the ground with its hooves. By Newton’s Third Law, the ground exerts an equal and opposite forward reaction force that propels the horse and cart forward. In empty space, there is no ground or external medium to provide this reaction force; hence, the horse cannot move.<br><br>\n    • <b>(b) Passengers thrown forward when bus stops:</b> When the bus is moving, the passengers’ bodies share the forward velocity. When brakes are applied suddenly, the lower part of the body in contact with the seat comes to rest immediately, but the upper body tends to remain in motion due to <b>inertia of motion</b> (Newton’s First Law).<br><br>\n    • <b>(c) Pulling vs Pushing a lawn mower:</b><br>\n      - When <i>pushing</i>, the applied force $F$ has a downward vertical component ($F \\sin \\theta$), increasing the effective normal reaction: $N = mg + F \\sin \\theta$. The friction force increases ($f_k = \\mu N$).<br>\n      - When <i>pulling</i>, the applied force has an upward vertical component ($F \\sin \\theta$), decreasing the normal reaction: $N = mg - F \\sin \\theta$. The friction force decreases ($f_k = \\mu N$).<br>\n      Hence, <b>pulling encounters less friction and is much easier</b>.<br><br>\n    • <b>(d) Cricketer moving hands backward:</b> Impulse $J = F_{avg} \\times \\Delta t = \\Delta p$. The momentum change $\\Delta p$ is fixed. By pulling his hands backward, the cricketer increases the impact time interval $\\Delta t$. Since $F_{avg} = \\frac{\\Delta p}{\\Delta t}$, increasing $\\Delta t$ significantly <b>reduces the impact force</b> exerted on his palms, preventing pain and injury.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Newton's third law reaction explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Inertia of motion explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Normal reaction resolution and friction comparison ($N = mg \\pm F\\sin\\theta$)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Impulse-momentum theorem $F = \\Delta p / \\Delta t$ and time prolongation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q24 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q24\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q24')\">\n      <div class=\"q-num\">Question 4.24</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        Figure 4.17 shows a man standing stationary with respect to a horizontal conveyor belt that is accelerating with $1\\text{ m s}^{-2}$. What is the net force on the man? If the coefficient of static friction between the man’s shoes and the belt is $0.2$, up to what acceleration of the belt can the man continue to be stationary relative to the belt? (Mass of the man = $65\\text{ kg}$.)\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given: Mass $m = 65\\text{ kg}$, Belt acceleration $a = 1\\text{ m s}^{-2}$, $\\mu_s = 0.2$, $g = 9.8\\text{ m s}^{-2}$.<br><br>\n    <b>1. Net force on the man:</b><br>\n    Since the man is stationary relative to the accelerating belt, he accelerates at $a = 1\\text{ m s}^{-2}$.<br>\n    $$F_{net} = m a = 65\\text{ kg} \\times 1\\text{ m s}^{-2} = \\mathbf{65\\text{ N}}$$<br>\n    This force is provided by the static friction between his shoes and the belt, directed in the forward direction of motion of the belt.<br><br>\n    <b>2. Maximum acceleration ($a_{max}$) before slipping:</b><br>\n    The maximum available static friction force is:<br>\n    $$f_{s,max} = \\mu_s N = \\mu_s m g$$<br>\n    For the man not to slip relative to the belt:<br>\n    $$m a_{max} = f_{s,max} = \\mu_s m g \\implies a_{max} = \\mu_s g$$<br>\n    $$a_{max} = 0.2 \\times 9.8 = \\mathbf{1.96\\text{ m s}^{-2}}$$<br><br>\n    $$\\therefore \\text{Net force } = \\mathbf{65\\text{ N}}, \\quad \\text{Maximum permissible acceleration } = \\mathbf{1.96\\text{ m s}^{-2}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Net force calculated $F = ma = 65\\text{ N}$ via static friction</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Maximum acceleration condition $a_{max} = \\mu_s g = 1.96\\text{ m s}^{-2}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q25 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q25\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q25')\">\n      <div class=\"q-num\">Question 4.25</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        A stone of mass $m$ tied to the end of a string revolves in a vertical circle of radius $R$. The net forces at the lowest and highest points of the circle directed vertically downwards are: [Choose the correct alternative]<br>Lowest Point &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Highest Point<br>(a) $mg - T_1$ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; $mg + T_2$<br>(b) $mg + T_1$ &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; $mg - T_2$<br>(c) $mg + T_1 - (m v_1^2)/R$ &nbsp;&nbsp; $mg - T_2 + (m v_2^2)/R$<br>(d) $mg - T_1 - (m v_1^2)/R$ &nbsp;&nbsp; $mg + T_2 + (m v_2^2)/R$<br>[$T_1$ and $v_1$ denote tension and speed at the lowest point; $T_2$ and $v_2$ denote corresponding values at highest point].\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <b>Correct Alternative: (a) $mg - T_1$ at Lowest Point, and $mg + T_2$ at Highest Point</b><br><br>\n    <b>Justification:</b><br>\n    The question asks for the <b>net force directed vertically downwards</b>:<br><br>\n    • <b>1. At the Lowest Point:</b><br>\n      - Weight $mg$ acts vertically downwards ($+mg$).<br>\n      - Tension $T_1$ acts vertically upwards ($-T_1$).<br>\n      - Net force directed vertically downwards = $\\mathbf{mg - T_1}$.<br>\n      (Note: directed upwards, the net force is $T_1 - mg = \\frac{m v_1^2}{R}$).<br><br>\n    • <b>2. At the Highest Point:</b><br>\n      - Weight $mg$ acts vertically downwards ($+mg$).<br>\n      - Tension $T_2$ acts vertically downwards towards centre ($+T_2$).<br>\n      - Net force directed vertically downwards = $\\mathbf{mg + T_2}$.<br>\n      (This provides the necessary downward centripetal force: $mg + T_2 = \\frac{m v_2^2}{R}$).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of correct alternative (a)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vector force summation for downward direction at both points</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q26 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q26\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q26')\">\n      <div class=\"q-num\">Question 4.26</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        A helicopter of mass $1000\\text{ kg}$ rises with a vertical acceleration of $15\\text{ m s}^{-2}$. The crew and the passengers weigh $300\\text{ kg}$. Give the magnitude and direction of the<br>(a) force on the floor by the crew and passengers,<br>(b) action of the rotor of the helicopter on the surrounding air,<br>(c) force on the helicopter due to the surrounding air. (Take $g = 10\\text{ m s}^{-2}$).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass of helicopter $M = 1000\\text{ kg}$<br>\n    • Mass of crew and passengers $m = 300\\text{ kg}$<br>\n    • Total mass $M_{total} = 1000 + 300 = 1300\\text{ kg}$<br>\n    • Upward acceleration $a = 15\\text{ m s}^{-2}$<br>\n    • $g = 10\\text{ m s}^{-2}$<br><br>\n    • <b>(a) Force on the floor by the crew and passengers:</b><br>\n      The normal reaction $R$ exerted by the floor on the crew is given by:<br>\n      $$R - mg = ma \\implies R = m(g + a) = 300 \\times (10 + 15) = 300 \\times 25 = 7500\\text{ N}$$<br>\n      By Newton’s third law, the force exerted by the crew on the floor is equal in magnitude and directed downwards.<br>\n      $$\\mathbf{\\text{Force on floor} = 7500\\text{ N, vertically downwards}}$$<br><br>\n    • <b>(b) Action of the rotor on the surrounding air:</b><br>\n      The rotor must push air downwards with a thrust force $T$ to accelerate the entire helicopter system upwards.<br>\n      $$T = M_{total}(g + a) = 1300 \\times (10 + 15) = 1300 \\times 25 = 32500\\text{ N} = 3.25 \\times 10^4\\text{ N}$$<br>\n      $$\\mathbf{\\text{Action of rotor on air} = 32500\\text{ N, vertically downwards}}$$<br><br>\n    • <b>(c) Force on the helicopter due to surrounding air:</b><br>\n      By Newton’s third law, the air pushes up on the helicopter rotor with an equal and opposite reaction force:<br>\n      $$\\mathbf{\\text{Reaction on helicopter} = 32500\\text{ N, vertically upwards}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Normal reaction on floor: $7500\\text{ N}$ downwards</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Action of rotor on air: $32500\\text{ N}$ downwards</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Upward air reaction force: $32500\\text{ N}$ upwards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q27 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q27\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q27')\">\n      <div class=\"q-num\">Question 4.27</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        A stream of water flowing horizontally with a speed of $15\\text{ m s}^{-1}$ gushes out of a tube of cross-sectional area $10^{-2}\\text{ m}^2$, and hits a vertical wall normally. Assuming that water does not rebound, what is the force exerted on the wall by the impact of water?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Speed of water $v = 15\\text{ m s}^{-1}$<br>\n    • Cross-sectional area $A = 10^{-2}\\text{ m}^2$<br>\n    • Density of water $\\rho = 10^3\\text{ kg m}^{-3}$<br><br>\n    <b>1. Mass of water hitting wall per second:</b><br>\n    $$\\frac{dm}{dt} = \\rho A v = 10^3\\text{ kg m}^{-3} \\times 10^{-2}\\text{ m}^2 \\times 15\\text{ m s}^{-1} = 150\\text{ kg s}^{-1}$$<br><br>\n    <b>2. Momentum change per second:</b><br>\n    Initial momentum of water per second = $\\frac{dm}{dt} v = 150 \\times 15 = 2250\\text{ kg m s}^{-2}$.<br>\n    Since water does not rebound, its final horizontal velocity is zero.<br><br>\n    <b>3. Force exerted on the wall ($F$):</b><br>\n    $$F = \\frac{dp}{dt} = \\frac{dm}{dt} v = \\rho A v^2$$<br>\n    $$F = 150\\text{ kg s}^{-1} \\times 15\\text{ m s}^{-1} = \\mathbf{2250\\text{ N} = 2.25 \\times 10^3\\text{ N}}$$<br><br>\n    $$\\therefore \\text{The force exerted on the wall is } \\mathbf{2250\\text{ N}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mass flow rate calculation $\\frac{dm}{dt} = \\rho Av = 150\\text{ kg/s}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Force calculation $F = \\frac{dm}{dt}v = 2250\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q28 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q28\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q28')\">\n      <div class=\"q-num\">Question 4.28</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        Ten one-rupee coins are put on top of each other on a table. Each coin has a mass $m$. Give the magnitude and direction of<br>(a) the force on the 7th coin (counted from the bottom) due to all the coins on its top,<br>(b) the force on the 7th coin by the eighth coin,<br>(c) the reaction of the 6th coin on the 7th coin.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Coins are numbered $1$ to $10$ from the bottom up.<br><br>\n    • <b>(a) Force on 7th coin due to all coins on its top:</b><br>\n      Above the 7th coin, there are $3$ coins (the 8th, 9th, and 10th coins).<br>\n      Total mass of these 3 coins = $3m$.<br>\n      They exert a downward gravitational force equal to their combined weight:<br>\n      $$\\mathbf{F = 3mg, \\text{ vertically downwards}}$$<br><br>\n    • <b>(b) Force on the 7th coin by the eighth coin:</b><br>\n      The 8th coin supports itself and the two coins above it (9th and 10th), transmitting their total weight of $3m$ to the 7th coin.<br>\n      $$\\mathbf{F = 3mg, \\text{ vertically downwards}}$$<br><br>\n    • <b>(c) Reaction of the 6th coin on the 7th coin:</b><br>\n      The 7th coin is in contact with the 6th coin below it. The 7th coin and the 3 coins above it have a total of $4$ coins (7th, 8th, 9th, 10th) of total mass $4m$ pressing down on the 6th coin.<br>\n      By Newton’s third law, the 6th coin exerts an equal and opposite upward normal reaction force:<br>\n      $$\\mathbf{R = 4mg, \\text{ vertically upwards}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Force due to 3 coins above: $3mg$ downwards</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Force by 8th coin transmitting total load: $3mg$ downwards</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Reaction by 6th coin supporting 4 coins: $4mg$ upwards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q29 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q29\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q29')\">\n      <div class=\"q-num\">Question 4.29</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        An aircraft executes a horizontal loop at a speed of $720\\text{ km h}^{-1}$ with its wings banked at $15^\\circ$. What is the radius of the loop?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Speed $v = 720\\text{ km h}^{-1} = 720 \\times \\frac{5}{18}\\text{ m s}^{-1} = 200\\text{ m s}^{-1}$<br>\n    • Banking angle $\\theta = 15^\\circ$<br>\n    • Acceleration due to gravity $g = 9.8\\text{ m s}^{-2}$<br><br>\n    <b>Banking Formula:</b><br>\n    For a banked turn without slipping, the horizontal component of aerodynamic lift provides centripetal acceleration:<br>\n    $$\\tan \\theta = \\frac{v^2}{R g} \\implies R = \\frac{v^2}{g \\tan \\theta}$$<br><br>\n    Substituting known values:<br>\n    $$\\tan 15^\\circ = 2 - \\sqrt{3} \\approx 0.26795$$<br>\n    $$R = \\frac{(200)^2}{9.8 \\times 0.26795} = \\frac{40000}{2.6259} \\approx \\mathbf{15233\\text{ m} = 15.23\\text{ km}}$$<br><br>\n    $$\\therefore \\text{The radius of the horizontal loop is } \\mathbf{15.23\\text{ km}}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Speed conversion to $200\\text{ m s}^{-1}$</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Banking angle relation $\\tan\\theta = v^2/(Rg)$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final calculation $R = 15.23\\text{ km}$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q30 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q30\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q30')\">\n      <div class=\"q-num\">Question 4.30</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        A train runs along an unbanked circular track of radius $30\\text{ m}$ at a speed of $54\\text{ km h}^{-1}$. The mass of the train is $10^6\\text{ kg}$. What provides the centripetal force required for this motion? The engine or the rails? What is the angle of banking required to prevent wearing out of the rail?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Radius $R = 30\\text{ m}$<br>\n    • Speed $v = 54\\text{ km h}^{-1} = 54 \\times \\frac{5}{18} = 15\\text{ m s}^{-1}$<br>\n    • Mass $M = 10^6\\text{ kg}$, $g = 9.8\\text{ m s}^{-2}$<br><br>\n    • <b>1. Source of Centripetal Force:</b><br>\n      On an unbanked track, the centripetal force is provided by the <b>lateral thrust (reaction) exerted by the outer rail</b> on the flanges of the wheels. The engine only provides the forward driving force along the track.<br><br>\n    • <b>2. Angle of Banking ($\\theta$):</b><br>\n      To prevent lateral wear and tear on the rail flanges, the track must be banked so that the normal reaction provides the centripetal force:<br>\n      $$\\tan \\theta = \\frac{v^2}{R g} = \\frac{(15)^2}{30 \\times 9.8} = \\frac{225}{294} \\approx 0.7653$$<br>\n      $$\\theta = \\arctan(0.7653) \\approx \\mathbf{37.4^\\circ} \\approx \\mathbf{37^\\circ 25'}$$<br><br>\n    $$\\therefore \\text{Lateral thrust of the rails provides centripetal force; required banking angle is } \\mathbf{37.4^\\circ}.$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of outer rail lateral thrust on wheel flanges</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Banking angle formula $\\tan\\theta = v^2/(Rg)$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of required banking angle $\\theta = 37.4^\\circ$</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11p-ch4-q31 (NCERT Additional Exercise) -->\n  <div class=\"q-card\" id=\"c11p-ch4-q31\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11p-ch4-q31')\">\n      <div class=\"q-num\">Question 4.31</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#f5f3ff; color:#7c3aed; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Additional Exercise</span><br>\n        A block of mass $25\\text{ kg}$ is raised by a $50\\text{ kg}$ man in two different ways as shown in Fig. 4.19: (a) by pulling directly upward, and (b) by pulling down via a pulley. What is the action on the floor by the man in the two cases? If the floor yields to a normal force of $700\\text{ N}$, which mode should the man adopt?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    Given:<br>\n    • Mass of man $M = 50\\text{ kg}$, Weight of man $W_m = Mg = 50 \\times 9.8 = 490\\text{ N}$<br>\n    • Mass of block $m = 25\\text{ kg}$, Weight of block $W_b = mg = 25 \\times 9.8 = 245\\text{ N}$<br>\n    • Maximum force floor can support $= 700\\text{ N}$<br><br>\n    • <b>Case (a): Pulling directly upward:</b><br>\n      The man pulls the rope upward with tension $T = mg = 245\\text{ N}$.<br>\n      By Newton’s third law, the rope pulls the man downwards with an equal force $T = 245\\text{ N}$.<br>\n      Total normal force exerted by the man on the floor:<br>\n      $$N_a = Mg + mg = 490 + 245 = \\mathbf{735\\text{ N}}$$<br><br>\n    • <b>Case (b): Pulling down via a ceiling pulley:</b><br>\n      The man pulls the rope downward with force $T = mg = 245\\text{ N}$.<br>\n      By Newton’s third law, the rope pulls the man upwards with force $T = 245\\text{ N}$.<br>\n      Total normal force exerted by the man on the floor:<br>\n      $$N_b = Mg - mg = 490 - 245 = \\mathbf{245\\text{ N}}$$<br><br>\n    • <b>Conclusion:</b><br>\n      Since the floor yields to a normal force of $700\\text{ N}$, in Case (a) the normal force ($735\\text{ N}$) exceeds the limit and the floor will collapse. In Case (b), the normal force is only $245\\text{ N} < 700\\text{ N}$.<br>\n      $$\\mathbf{\\text{The man should adopt Mode (b) (using the pulley).}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Case (a) upward pull force analysis: $N_a = Mg + mg = 735\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Case (b) downward pull via pulley analysis: $N_b = Mg - mg = 245\\text{ N}$</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison with floor limit $700\\text{ N}$ and recommending Mode (b)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer;\">← Prev: Chapter 3 (Motion in a Plane)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#7c3aed; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 5 (Work, Energy and Power) →</button>\n  </div>\n</section>";
